function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const u = minSide / 1000;
  const cx = width * 0.5;
  const cy = height * 0.5;
  const loopPhase = (loopT / duration) * Math.PI * 2;
  const heroZoom = 1.22;

  // Color Palette — Void Indigo-Slate + Electric Crimson & Bright Periwinkle
  const C = {
    bgTop: '#090914',
    bgMid: '#111124',
    bgBot: '#1B1B36',
    gridMark: 'rgba(129, 140, 248, 0.065)',
    trackMuted: '#222247',
    trackStroke: '#3C3C78',
    surfaceDark: '#121229',
    surfaceMid: '#1D1D3F',
    surfaceLight: '#2C2C5E',
    crimson: '#FF2E54',
    crimsonMid: '#E01E42',
    crimsonDeep: '#B31232',
    periwinkle: '#818CF8',
    periwinkleMid: '#6366F1',
    indigoDeep: '#4338CA',
    roseWhite: '#FFE4EA',
    white: '#F8FAFC'
  };

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function range01(p, start, end) {
    return clamp01((p - start) / (end - start));
  }

  function easeOutCubic(x) {
    const inv = 1 - clamp01(x);
    return 1 - inv * inv * inv;
  }

  function easeInCubic(x) {
    const v = clamp01(x);
    return v * v * v;
  }

  function easeInOutCubic(x) {
    const v = clamp01(x);
    return v < 0.5 ? 4 * v * v * v : 1 - Math.pow(-2 * v + 2, 3) / 2;
  }

  function lerpColor(hexA, hexB, f) {
    const k = clamp01(f);
    const a = parseInt(hexA.slice(1), 16);
    const b = parseInt(hexB.slice(1), 16);
    const ar = (a >> 16) & 255;
    const ag = (a >> 8) & 255;
    const ab = a & 255;
    const br = (b >> 16) & 255;
    const bg = (b >> 8) & 255;
    const bb = b & 255;
    const r = Math.round(ar + (br - ar) * k);
    const g = Math.round(ag + (bg - ag) * k);
    const bl = Math.round(ab + (bb - ab) * k);
    return 'rgb(' + r + ',' + g + ',' + bl + ')';
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function diamondPath(x, y, r) {
    ctx.beginPath();
    ctx.moveTo(x, y - r);
    ctx.lineTo(x + r, y);
    ctx.lineTo(x, y + r);
    ctx.lineTo(x - r, y);
    ctx.closePath();
  }

  function drawBackground() {
    const bgGrad = ctx.createLinearGradient(0, 0, width, height);
    bgGrad.addColorStop(0, C.bgTop);
    bgGrad.addColorStop(0.5, C.bgMid);
    bgGrad.addColorStop(1, C.bgBot);
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, width, height);

    // Subtle uniform diagonal micro-chevrons drifting cleanly upward-right
    const step = 68 * u;
    const drift = (loopT / duration) * step;
    const cols = Math.ceil(width / step) + 2;
    const rows = Math.ceil(height / step) + 2;
    const startX = cx - Math.floor(cols * 0.5) * step + (drift % step) - step;
    const startY = cy - Math.floor(rows * 0.5) * step - (drift % step) + step;
    const arm = 3 * u;

    ctx.strokeStyle = C.gridMark;
    ctx.lineWidth = 1.2 * u;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.beginPath();
    for (let r = 0; r < rows; r++) {
      const py = startY + r * step;
      if (py < 26 * u || py > height - 26 * u) continue;
      for (let c = 0; c < cols; c++) {
        const px = startX + c * step;
        if (px < 26 * u || px > width - 26 * u) continue;
        ctx.moveTo(px - arm, py + arm * 0.5);
        ctx.lineTo(px, py - arm * 0.5);
        ctx.lineTo(px + arm, py + arm * 0.5);
      }
    }
    ctx.stroke();
  }

  function drawSideTelemetry() {
    const minHalfW = 580 * u;
    if (width * 0.5 < minHalfW + 80 * u) return;

    const sideOffset = Math.min(620 * u, width * 0.5 - 110 * u);
    const lx = cx - sideOffset;
    const rx = cx + sideOffset;

    const capW = 6 * u;
    const capH = 40 * u;
    const capGap = 20 * u;
    const totalH = sceneCount * capH + (sceneCount - 1) * capGap;
    const topY = cy - totalH * 0.5;

    const activeFade = Math.min(
      easeOutCubic(range01(sceneProgress, 0.0, 0.08)),
      1 - easeInCubic(range01(sceneProgress, 0.90, 1.0))
    );

    for (let i = 0; i < sceneCount; i++) {
      const y = topY + i * (capH + capGap);
      ctx.fillStyle = C.trackMuted;
      roundedRectPath(lx - capW * 0.5, y, capW, capH, capW * 0.5);
      ctx.fill();

      if (i === currentScene && activeFade > 0.01) {
        const fillFrac = easeInOutCubic(range01(sceneProgress, 0.0, 0.90));
        const fillH = Math.max(capW, capH * fillFrac);
        ctx.fillStyle = lerpColor(C.trackMuted, C.crimson, activeFade);
        roundedRectPath(lx - capW * 0.5, y, capW, fillH, capW * 0.5);
        ctx.fill();
      }
    }

    const barMaxW = 60 * u;
    const barH = 6 * u;
    for (let i = 0; i < 4; i++) {
      const y = topY + i * (capH + capGap) + (capH - barH) * 0.5;
      const wave = 0.5 + 0.5 * Math.sin(loopPhase * 2 - i * 0.8);
      const activeW = (18 + wave * 38) * u;

      ctx.fillStyle = C.trackMuted;
      roundedRectPath(rx - barMaxW * 0.5, y, barMaxW, barH, barH * 0.5);
      ctx.fill();

      const highlight = i === currentScene ? activeFade : 0;
      ctx.fillStyle = lerpColor(C.trackStroke, i % 2 === 0 ? C.crimson : C.periwinkle, highlight);
      roundedRectPath(rx - barMaxW * 0.5, y, activeW, barH, barH * 0.5);
      ctx.fill();
    }
  }

  function getSceneEnvelope(p) {
    const enterP = range01(p, 0.0, 0.14);
    const exitP = range01(p, 0.86, 1.0);
    const enterEase = easeOutCubic(enterP);
    const exitEase = easeInCubic(exitP);
    const scale = p < 0.5 ? 0.86 + 0.14 * enterEase : 1 - 0.14 * exitEase;
    const liftY = p < 0.5 ? (1 - enterEase) * 18 * u : -exitEase * 18 * u;
    const alpha = p < 0.10
      ? easeOutCubic(range01(p, 0.0, 0.10))
      : p > 0.90
        ? 1 - easeInCubic(range01(p, 0.90, 1.0))
        : 1;
    return { scale, alpha, liftY };
  }

  // =========================================================================
  // SCENE 1 (0-5s): EXPONENTIAL SCALING STEPS
  // =========================================================================
  function drawScene1Steps(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    const floatY = Math.sin(range01(p, 0.14, 0.86) * Math.PI * 2) * 4 * u;

    ctx.save();
    ctx.translate(cx, cy + 16 * u + floatY + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    const baseY = 112 * u;

    // Clean Horizontal Baseline
    ctx.fillStyle = C.trackStroke;
    roundedRectPath(-164 * u, baseY + 8 * u, 328 * u, 7 * u, 3.5 * u);
    ctx.fill();

    // 4 Ascending Scaling Step Blocks (width = 56u, gap = 22u -> total span 290u centered!)
    const stepW = 56 * u;
    const steps = [
      { x: -117, h: 48, colL: C.indigoDeep, colR: '#312E81', delay: 0.08 },
      { x: -39, h: 92, colL: C.periwinkleMid, colR: C.indigoDeep, delay: 0.14 },
      { x: 39, h: 138, colL: C.periwinkle, colR: C.periwinkleMid, delay: 0.20 },
      { x: 117, h: 186, colL: C.crimson, colR: C.crimsonMid, delay: 0.26 }
    ];

    const tops = [];
    for (let i = 0; i < steps.length; i++) {
      const st = steps[i];
      const grow = easeOutCubic(range01(p, st.delay, st.delay + 0.18));
      const bh = st.h * u * grow;
      const bx = st.x * u - stepW * 0.5;
      const by = baseY - bh;
      tops.push([st.x * u, baseY - st.h * u]);

      if (bh > 2 * u) {
        ctx.save();
        roundedRectPath(bx, by, stepW, bh, 9 * u);
        ctx.clip();
        ctx.fillStyle = st.colL;
        ctx.fillRect(bx, by, stepW * 0.5, bh);
        ctx.fillStyle = st.colR;
        ctx.fillRect(bx + stepW * 0.5, by, stepW * 0.5, bh);
        ctx.restore();
      }
    }

    // Parabolic Energy Diamond hopping cleanly 24u ABOVE each step top (zero collision with blocks!)
    const hopGlobal = range01(p, 0.26, 0.74);
    if (hopGlobal > 0.005) {
      const segF = hopGlobal * 3;
      const segIdx = Math.min(2, Math.floor(segF));
      const local = easeInOutCubic(segF - segIdx);
      const p0 = tops[segIdx];
      const p1 = tops[segIdx + 1];
      const hx = p0[0] + (p1[0] - p0[0]) * local;
      const linearY = p0[1] + (p1[1] - p0[1]) * local;
      const arcLift = Math.sin(local * Math.PI) * 44 * u;
      const hy = linearY - 26 * u - arcLift;

      // Clean subtle elevated trajectory dots along completed hops
      ctx.fillStyle = C.roseWhite;
      for (let k = 0; k <= segIdx; k++) {
        if (k === segIdx && local < 0.15) continue;
        ctx.beginPath();
        ctx.arc(tops[k][0], tops[k][1] - 26 * u, 4 * u, 0, Math.PI * 2);
        ctx.fill();
      }

      // Hero Energy Diamond
      ctx.fillStyle = C.crimson;
      diamondPath(hx, hy, 18 * u);
      ctx.fill();

      ctx.fillStyle = C.roseWhite;
      diamondPath(hx, hy, 9 * u);
      ctx.fill();
    }

    ctx.restore();
  }

  // =========================================================================
  // SCENE 2 (5-10s): VENTURE CAPITAL FUNNEL
  // =========================================================================
  function drawScene2Funnel(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    const floatY = Math.sin(range01(p, 0.14, 0.86) * Math.PI * 2) * 4 * u;

    ctx.save();
    ctx.translate(cx, cy + floatY + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    // 3 Deal Tokens smoothly converging DOWN into funnel top mouth (strictly clipped ABOVE y = -82u!)
    ctx.save();
    ctx.beginPath();
    ctx.rect(-170 * u, -210 * u, 340 * u, 128 * u);
    ctx.clip();

    const inputs = [
      { sx: -76, start: 0.12, end: 0.42, shape: 0, col: C.periwinkle },
      { sx: 0, start: 0.22, end: 0.52, shape: 1, col: C.roseWhite },
      { sx: 76, start: 0.32, end: 0.62, shape: 2, col: C.crimson }
    ];
    for (let i = 0; i < inputs.length; i++) {
      const inp = inputs[i];
      const ip = range01(p, inp.start, inp.end);
      if (ip <= 0 || ip >= 1) continue;
      const move = easeInOutCubic(ip);
      const fade = Math.min(easeOutCubic(range01(ip, 0, 0.22)), 1 - easeInCubic(range01(ip, 0.85, 1)));
      const tx = inp.sx * (1 - move * 0.55) * u;
      const ty = (-162 + move * 98) * u;

      ctx.save();
      ctx.globalAlpha = env.alpha * fade;
      ctx.fillStyle = inp.col;
      if (inp.shape === 0) {
        ctx.beginPath();
        ctx.arc(tx, ty, 13 * u, 0, Math.PI * 2);
        ctx.fill();
      } else if (inp.shape === 1) {
        roundedRectPath(tx - 12 * u, ty - 12 * u, 24 * u, 24 * u, 5 * u);
        ctx.fill();
      } else {
        diamondPath(tx, ty, 15 * u);
        ctx.fill();
      }
      ctx.restore();
    }
    ctx.restore();

    // Emerging Refined Capital Crystal cleanly BELOW funnel spout (clipped strictly BELOW y = +94u!)
    const outP = range01(p, 0.42, 0.72);
    if (outP > 0.01) {
      const drop = easeOutCubic(outP);
      const cyOut = (96 + drop * 48) * u;
      ctx.save();
      ctx.beginPath();
      ctx.rect(-100 * u, 94 * u, 200 * u, 110 * u);
      ctx.clip();
      ctx.fillStyle = C.crimson;
      diamondPath(0, cyOut, 26 * u);
      ctx.fill();
      ctx.fillStyle = C.roseWhite;
      diamondPath(0, cyOut, 13 * u);
      ctx.fill();
      ctx.restore();
    }

    // Architectural 3-Tier Flat Vector Funnel Silhouette (y = -82u .. +94u, crisp 6u gaps between tiers!)
    function tierTrap(y0, y1, w0, w1, colL, colR) {
      ctx.save();
      ctx.beginPath();
      ctx.moveTo(-w0 * 0.5, y0);
      ctx.lineTo(w0 * 0.5, y0);
      ctx.lineTo(w1 * 0.5, y1);
      ctx.lineTo(-w1 * 0.5, y1);
      ctx.closePath();
      ctx.clip();
      ctx.fillStyle = colL;
      ctx.fillRect(-w0 * 0.5, y0, w0 * 0.5, y1 - y0);
      ctx.fillStyle = colR;
      ctx.fillRect(0, y0, w0 * 0.5, y1 - y0);
      ctx.restore();
    }

    // Tier 1 (Seed / Top Funnel)
    tierTrap(-82 * u, -34 * u, 256 * u, 186 * u, C.periwinkle, C.periwinkleMid);
    // Tier 2 (Growth / Mid Funnel) — 8u clean separation gap
    tierTrap(-26 * u, 22 * u, 174 * u, 102 * u, C.periwinkleMid, C.indigoDeep);
    // Tier 3 (Venture Output Spout) — 8u clean separation gap
    tierTrap(30 * u, 94 * u, 88 * u, 50 * u, C.crimson, C.crimsonMid);

    ctx.restore();
  }

  // =========================================================================
  // SCENE 3 (10-15s): MARKET TRACTION MAGNET
  // =========================================================================
  function drawScene3Magnet(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    const floatY = Math.sin(range01(p, 0.14, 0.86) * Math.PI * 2) * 4 * u;

    ctx.save();
    ctx.translate(cx, cy + floatY + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    // Horseshoe Magnet oriented cleanly left-to-right (poles at x = +48u, facing open field on right!)
    const arcCx = -46 * u;
    const midR = 76 * u;
    const thick = 48 * u;

    // Curved U-body (top half Crimson, bottom half CrimsonMid via clean clip split)
    ctx.save();
    ctx.beginPath();
    ctx.rect(-180 * u, -150 * u, 220 * u, 150 * u);
    ctx.clip();
    ctx.strokeStyle = C.crimson;
    ctx.lineWidth = thick;
    ctx.lineCap = 'butt';
    ctx.beginPath();
    ctx.moveTo(10 * u, -midR);
    ctx.lineTo(arcCx, -midR);
    ctx.arc(arcCx, 0, midR, -Math.PI * 0.5, Math.PI * 0.5, true);
    ctx.stroke();
    ctx.restore();

    ctx.save();
    ctx.beginPath();
    ctx.rect(-180 * u, 0, 220 * u, 150 * u);
    ctx.clip();
    ctx.strokeStyle = C.crimsonMid;
    ctx.lineWidth = thick;
    ctx.lineCap = 'butt';
    ctx.beginPath();
    ctx.moveTo(arcCx, midR);
    ctx.lineTo(10 * u, midR);
    ctx.arc(arcCx, 0, midR, Math.PI * 0.5, -Math.PI * 0.5, false);
    ctx.stroke();
    ctx.restore();

    // Metallic Pole Tips cleanly separated by 6u dark seam (x = +16u .. +56u)
    ctx.fillStyle = C.roseWhite;
    roundedRectPath(16 * u, -midR - thick * 0.5, 40 * u, thick, 8 * u);
    ctx.fill();
    ctx.fillStyle = C.periwinkle;
    roundedRectPath(16 * u, midR - thick * 0.5, 40 * u, thick, 8 * u);
    ctx.fill();

    // Clean Traction Field Wave Chevrons & Accelerating Market Nodes strictly in x = +86u .. +186u
    // (>= 30u clear air gap from magnet poles at +56u — ZERO collision!)
    const waveSpeed = p * 2.4;
    for (let i = 0; i < 3; i++) {
      const f = (waveSpeed + i / 3) % 1; // 0 (far right) -> 1 (approaching poles)
      const accel = easeInCubic(f);
      const wx = (176 - accel * 86) * u;
      const fade = Math.min(easeOutCubic(range01(f, 0, 0.25)), 1 - easeInCubic(range01(f, 0.78, 1)));
      ctx.save();
      ctx.globalAlpha = env.alpha * fade * 0.85;
      ctx.strokeStyle = i % 2 === 0 ? C.periwinkle : C.roseWhite;
      ctx.lineWidth = 4 * u;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.beginPath();
      ctx.moveTo(wx + 12 * u, -30 * u);
      ctx.lineTo(wx, 0);
      ctx.lineTo(wx + 12 * u, 30 * u);
      ctx.stroke();
      ctx.restore();
    }

    // 2 Market Traction Nodes pulled cleanly along UPPER & LOWER pole lanes (y = ±76u)
    // Strictly separated vertically (>= 46u) from center chevron field (y = -24u .. +24u) — ZERO overlap!
    const nodes = [
      { y: -76, off: 0.12, col: C.roseWhite },
      { y: 76, off: 0.62, col: C.periwinkle }
    ];
    for (let i = 0; i < nodes.length; i++) {
      const nd = nodes[i];
      const f = (waveSpeed * 0.85 + nd.off) % 1;
      const pull = easeInCubic(f);
      const nx = (186 - pull * 96) * u;
      const fade = Math.min(easeOutCubic(range01(f, 0, 0.25)), 1 - easeInCubic(range01(f, 0.78, 1)));
      ctx.save();
      ctx.globalAlpha = env.alpha * fade;
      ctx.fillStyle = nd.col;
      diamondPath(nx, nd.y * u, 12 * u);
      ctx.fill();
      ctx.restore();
    }

    ctx.restore();
  }

  // =========================================================================
  // SCENE 4 (15-20s): SUMMIT MILESTONE FLAG
  // =========================================================================
  function drawScene4Summit(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    const floatY = Math.sin(range01(p, 0.14, 0.86) * Math.PI * 2) * 4 * u;

    ctx.save();
    ctx.translate(cx, cy + 16 * u + floatY + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    const baseY = 114 * u;
    const peakX = -26 * u;
    const peakY = -44 * u;

    // Secondary Back Mountain Peak cleanly tucked behind right slope
    ctx.fillStyle = C.surfaceLight;
    ctx.beginPath();
    ctx.moveTo(4 * u, baseY);
    ctx.lineTo(74 * u, -2 * u);
    ctx.lineTo(148 * u, baseY);
    ctx.closePath();
    ctx.fill();

    // Primary Flat Vector Summit Mountain (duotone Periwinkle / Indigo split)
    ctx.fillStyle = C.periwinkle;
    ctx.beginPath();
    ctx.moveTo(peakX, peakY);
    ctx.lineTo(-152 * u, baseY);
    ctx.lineTo(peakX, baseY);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = C.periwinkleMid;
    ctx.beginPath();
    ctx.moveTo(peakX, peakY);
    ctx.lineTo(100 * u, baseY);
    ctx.lineTo(peakX, baseY);
    ctx.closePath();
    ctx.fill();

    // Crisp Geometric Snow Cap Polygon on Primary Peak
    ctx.fillStyle = C.roseWhite;
    ctx.beginPath();
    ctx.moveTo(peakX, peakY);
    ctx.lineTo(peakX - 42 * u, peakY + 52 * u);
    ctx.lineTo(peakX - 14 * u, peakY + 38 * u);
    ctx.lineTo(peakX, peakY + 54 * u);
    ctx.lineTo(peakX + 16 * u, peakY + 38 * u);
    ctx.lineTo(peakX + 42 * u, peakY + 52 * u);
    ctx.closePath();
    ctx.fill();

    // Clean Horizontal Ground Line
    ctx.fillStyle = C.trackStroke;
    roundedRectPath(-164 * u, baseY, 328 * u, 7 * u, 3.5 * u);
    ctx.fill();

    // Vertical Flagpole extruding cleanly from summit apex
    const poleGrow = easeOutCubic(range01(p, 0.14, 0.34));
    const poleH = 114 * u * poleGrow;
    const poleTopY = peakY - poleH;

    if (poleGrow > 0.01) {
      // Smooth Sine-Wave Procedural Cloth Pennant Flag (24 clean segments, zero distortion!)
      const flagP = easeOutCubic(range01(p, 0.28, 0.46));
      if (flagP > 0.01) {
        const flagW = 108 * u * flagP;
        const flagH = 54 * u;
        const wavePhase = p * Math.PI * 6;
        const segs = 24;

        ctx.fillStyle = C.crimson;
        ctx.beginPath();
        for (let i = 0; i <= segs; i++) {
          const f = i / segs;
          const fx = peakX + 4 * u + f * flagW;
          const dy = Math.sin(f * Math.PI * 2 - wavePhase) * 8 * u * f;
          const fy = poleTopY + 8 * u + dy;
          if (i === 0) ctx.moveTo(fx, fy);
          else ctx.lineTo(fx, fy);
        }
        // Subtle inward swallowtail notch at free end
        const endWave = Math.sin(Math.PI * 2 - wavePhase) * 8 * u;
        ctx.lineTo(peakX + 4 * u + flagW * 0.84, poleTopY + 8 * u + flagH * 0.5 + endWave * 0.85);
        for (let i = segs; i >= 0; i--) {
          const f = i / segs;
          const fx = peakX + 4 * u + f * flagW;
          const dy = Math.sin(f * Math.PI * 2 - wavePhase) * 8 * u * f;
          const fy = poleTopY + 8 * u + flagH + dy;
          ctx.lineTo(fx, fy);
        }
        ctx.closePath();
        ctx.fill();
      }

      // Crisp Flagpole Staff & Finial
      ctx.strokeStyle = C.white;
      ctx.lineWidth = 6.5 * u;
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(peakX, peakY + 4 * u);
      ctx.lineTo(peakX, poleTopY);
      ctx.stroke();

      ctx.fillStyle = C.crimson;
      ctx.beginPath();
      ctx.arc(peakX, poleTopY, 7.5 * u, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.restore();
  }

  // =========================================================================
  // RENDER PIPELINE
  // =========================================================================
  ctx.save();
  drawBackground();
  drawSideTelemetry();

  if (currentScene === 0) {
    drawScene1Steps(sceneProgress);
  } else if (currentScene === 1) {
    drawScene2Funnel(sceneProgress);
  } else if (currentScene === 2) {
    drawScene3Magnet(sceneProgress);
  } else {
    drawScene4Summit(sceneProgress);
  }
  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const u = minSide / 1000;
  const cx = width * 0.5;
  const cy = height * 0.5;
  const loopPhase = (loopT / duration) * Math.PI * 2;
  const heroZoom = 1.22;

  // Color Palette — Dark Velvet Burgundy + Coral Rose & Warm Apricot
  const C = {
    bgTop: '#170710',
    bgMid: '#240B1A',
    bgBot: '#331023',
    gridMark: 'rgba(253, 186, 116, 0.065)',
    trackMuted: '#3D172C',
    trackStroke: '#662849',
    surfaceDark: '#1F0A16',
    surfaceMid: '#2F1122',
    surfaceLight: '#471B34',
    rose: '#FB7185',
    roseMid: '#E1526B',
    roseDeep: '#BE3A53',
    apricot: '#FDBA74',
    apricotMid: '#F59E56',
    ivory: '#FFF1F2',
    ivoryShade: '#F5DDE0',
    sheen: 'rgba(255, 241, 242, 0.22)'
  };

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function range01(p, start, end) {
    return clamp01((p - start) / (end - start));
  }

  function easeOutCubic(x) {
    const inv = 1 - clamp01(x);
    return 1 - inv * inv * inv;
  }

  function easeInCubic(x) {
    const v = clamp01(x);
    return v * v * v;
  }

  function easeInOutCubic(x) {
    const v = clamp01(x);
    return v < 0.5 ? 4 * v * v * v : 1 - Math.pow(-2 * v + 2, 3) / 2;
  }

  function lerpColor(hexA, hexB, f) {
    const k = clamp01(f);
    const a = parseInt(hexA.slice(1), 16);
    const b = parseInt(hexB.slice(1), 16);
    const ar = (a >> 16) & 255;
    const ag = (a >> 8) & 255;
    const ab = a & 255;
    const br = (b >> 16) & 255;
    const bg = (b >> 8) & 255;
    const bb = b & 255;
    const r = Math.round(ar + (br - ar) * k);
    const g = Math.round(ag + (bg - ag) * k);
    const bl = Math.round(ab + (bb - ab) * k);
    return 'rgb(' + r + ',' + g + ',' + bl + ')';
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function drawPartialPolyline(points, progress) {
    if (progress <= 0 || points.length < 2) return;
    let totalLen = 0;
    const segLens = [];
    for (let i = 0; i < points.length - 1; i++) {
      const len = Math.hypot(points[i + 1][0] - points[i][0], points[i + 1][1] - points[i][1]);
      segLens.push(len);
      totalLen += len;
    }
    let remaining = totalLen * clamp01(progress);
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 0; i < segLens.length; i++) {
      if (remaining <= 0) break;
      if (remaining >= segLens[i]) {
        ctx.lineTo(points[i + 1][0], points[i + 1][1]);
        remaining -= segLens[i];
      } else {
        const frac = remaining / segLens[i];
        ctx.lineTo(
          points[i][0] + (points[i + 1][0] - points[i][0]) * frac,
          points[i][1] + (points[i + 1][1] - points[i][1]) * frac
        );
        remaining = 0;
      }
    }
    ctx.stroke();
  }

  function drawBackground() {
    const bgGrad = ctx.createLinearGradient(0, 0, width, height);
    bgGrad.addColorStop(0, C.bgTop);
    bgGrad.addColorStop(0.5, C.bgMid);
    bgGrad.addColorStop(1, C.bgBot);
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, width, height);

    // Subtle uniform ledger dot grid with seamless leftward drift
    const step = 60 * u;
    const driftX = -(loopT / duration) * step;
    const cols = Math.ceil(width / step) + 2;
    const rows = Math.ceil(height / step) + 2;
    const startX = cx - Math.floor(cols * 0.5) * step + (((driftX % step) + step) % step) - step;
    const startY = cy - Math.floor(rows * 0.5) * step;
    const dotR = 1.45 * u;

    ctx.fillStyle = C.gridMark;
    ctx.beginPath();
    for (let r = 0; r < rows; r++) {
      const py = startY + r * step;
      if (py < 24 * u || py > height - 24 * u) continue;
      for (let c = 0; c < cols; c++) {
        const px = startX + c * step;
        if (px < 24 * u || px > width - 24 * u) continue;
        ctx.moveTo(px + dotR, py);
        ctx.arc(px, py, dotR, 0, Math.PI * 2);
      }
    }
    ctx.fill();
  }

  function drawSideTelemetry() {
    const minHalfW = 580 * u;
    if (width * 0.5 < minHalfW + 80 * u) return;

    const sideOffset = Math.min(620 * u, width * 0.5 - 110 * u);
    const lx = cx - sideOffset;
    const rx = cx + sideOffset;

    const capW = 6 * u;
    const capH = 40 * u;
    const capGap = 20 * u;
    const totalH = sceneCount * capH + (sceneCount - 1) * capGap;
    const topY = cy - totalH * 0.5;

    const activeFade = Math.min(
      easeOutCubic(range01(sceneProgress, 0.0, 0.08)),
      1 - easeInCubic(range01(sceneProgress, 0.90, 1.0))
    );

    for (let i = 0; i < sceneCount; i++) {
      const y = topY + i * (capH + capGap);
      ctx.fillStyle = C.trackMuted;
      roundedRectPath(lx - capW * 0.5, y, capW, capH, capW * 0.5);
      ctx.fill();

      if (i === currentScene && activeFade > 0.01) {
        const fillFrac = easeInOutCubic(range01(sceneProgress, 0.0, 0.90));
        const fillH = Math.max(capW, capH * fillFrac);
        ctx.fillStyle = lerpColor(C.trackMuted, C.rose, activeFade);
        roundedRectPath(lx - capW * 0.5, y, capW, fillH, capW * 0.5);
        ctx.fill();
      }
    }

    const barMaxW = 60 * u;
    const barH = 6 * u;
    for (let i = 0; i < 4; i++) {
      const y = topY + i * (capH + capGap) + (capH - barH) * 0.5;
      const wave = 0.5 + 0.5 * Math.sin(loopPhase * 2 - i * 1.1);
      const activeW = (18 + wave * 38) * u;

      ctx.fillStyle = C.trackMuted;
      roundedRectPath(rx - barMaxW * 0.5, y, barMaxW, barH, barH * 0.5);
      ctx.fill();

      const highlight = i === currentScene ? activeFade : 0;
      ctx.fillStyle = lerpColor(C.trackStroke, i % 2 === 0 ? C.rose : C.apricot, highlight);
      roundedRectPath(rx - barMaxW * 0.5, y, activeW, barH, barH * 0.5);
      ctx.fill();
    }
  }

  function getSceneEnvelope(p) {
    const enterP = range01(p, 0.0, 0.14);
    const exitP = range01(p, 0.86, 1.0);
    const enterEase = easeOutCubic(enterP);
    const exitEase = easeInCubic(exitP);
    const scale = p < 0.5 ? 0.86 + 0.14 * enterEase : 1 - 0.14 * exitEase;
    const liftY = p < 0.5 ? (1 - enterEase) * 18 * u : -exitEase * 18 * u;
    const alpha = p < 0.10
      ? easeOutCubic(range01(p, 0.0, 0.10))
      : p > 0.90
        ? 1 - easeInCubic(range01(p, 0.90, 1.0))
        : 1;
    return { scale, alpha, liftY };
  }

  // =========================================================================
  // SCENE 1 (0-5s): INTERACTIVE BUSINESS CALCULATOR
  // =========================================================================
  function drawScene1Calculator(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    const floatY = Math.sin(range01(p, 0.14, 0.86) * Math.PI * 2) * 4.5 * u;

    ctx.save();
    ctx.translate(cx, cy + floatY + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    const cW = 232 * u;
    const cH = 308 * u;
    const left = -cW * 0.5;
    const top = -cH * 0.5;

    // Duotone Calculator Body
    ctx.save();
    roundedRectPath(left, top, cW, cH, 26 * u);
    ctx.clip();
    ctx.fillStyle = C.surfaceMid;
    ctx.fillRect(left, top, cW * 0.52, cH);
    ctx.fillStyle = C.surfaceDark;
    ctx.fillRect(left + cW * 0.52, top, cW * 0.48, cH);
    ctx.restore();

    ctx.strokeStyle = C.trackStroke;
    ctx.lineWidth = 3.2 * u;
    roundedRectPath(left, top, cW, cH, 26 * u);
    ctx.stroke();

    // Upper Digital Display Screen (184u x 64u)
    const scrW = 184 * u;
    const scrH = 64 * u;
    const scrX = -scrW * 0.5;
    const scrY = top + 24 * u;
    ctx.fillStyle = C.bgTop;
    roundedRectPath(scrX, scrY, scrW, scrH, 12 * u);
    ctx.fill();

    // Animated calculation readout bars inside display
    const calcFill = easeOutCubic(range01(p, 0.14, 0.68));
    ctx.fillStyle = C.trackStroke;
    roundedRectPath(scrX + 14 * u, scrY + 14 * u, 64 * u, 8 * u, 4 * u);
    ctx.fill();

    const resW = Math.max(16 * u, 132 * u * calcFill);
    ctx.fillStyle = C.apricot;
    roundedRectPath(scrX + scrW - 14 * u - resW, scrY + 34 * u, resW, 14 * u, 7 * u);
    ctx.fill();

    // 3x3 Clean Keypad Grid (48u x 40u buttons, exact 16u H-gap & 14u V-gap!)
    const btnW = 50 * u;
    const btnH = 42 * u;
    const gapX = 17 * u;
    const gapY = 16 * u;
    const gridW = 3 * btnW + 2 * gapX;
    const gridX0 = -gridW * 0.5;
    const gridY0 = scrY + scrH + 24 * u;

    // Sequential smooth press order across keys
    const pressSeq = [0, 4, 2, 7, 8];
    const seqPos = range01(p, 0.16, 0.78) * pressSeq.length;

    for (let row = 0; row < 3; row++) {
      for (let col = 0; col < 3; col++) {
        const idx = row * 3 + col;
        const bx = gridX0 + col * (btnW + gapX);
        const by = gridY0 + row * (btnH + gapY);

        let pressAmt = 0;
        for (let s = 0; s < pressSeq.length; s++) {
          if (pressSeq[s] === idx) {
            const dist = Math.abs(seqPos - (s + 0.5));
            if (dist < 0.55) {
              pressAmt = Math.max(pressAmt, easeOutCubic(1 - dist / 0.55));
            }
          }
        }

        const isEquals = idx === 8;
        const baseCol = isEquals ? C.rose : col === 2 ? C.surfaceLight : C.trackMuted;
        const activeCol = isEquals ? C.ivory : C.apricot;
        const sc = 1 - 0.08 * pressAmt;

        ctx.save();
        ctx.translate(bx + btnW * 0.5, by + btnH * 0.5);
        ctx.scale(sc, sc);
        ctx.fillStyle = lerpColor(baseCol, activeCol, pressAmt);
        roundedRectPath(-btnW * 0.5, -btnH * 0.5, btnW, btnH, 10 * u);
        ctx.fill();

        // Crisp geometric symbol dot/bar on key center
        ctx.fillStyle = isEquals
          ? lerpColor(C.ivory, C.surfaceDark, pressAmt)
          : lerpColor(C.ivory, C.surfaceDark, pressAmt * 0.8);
        if (isEquals) {
          roundedRectPath(-10 * u, -5 * u, 20 * u, 3.5 * u, 1.75 * u);
          ctx.fill();
          roundedRectPath(-10 * u, 2 * u, 20 * u, 3.5 * u, 1.75 * u);
          ctx.fill();
        } else if (col === 2 && row === 0) {
          roundedRectPath(-8 * u, -2 * u, 16 * u, 4 * u, 2 * u);
          ctx.fill();
          roundedRectPath(-2 * u, -8 * u, 4 * u, 16 * u, 2 * u);
          ctx.fill();
        } else if (col === 2 && row === 1) {
          roundedRectPath(-8 * u, -2 * u, 16 * u, 4 * u, 2 * u);
          ctx.fill();
        } else {
          ctx.beginPath();
          ctx.arc(0, 0, 4.5 * u, 0, Math.PI * 2);
          ctx.fill();
        }
        ctx.restore();
      }
    }

    ctx.restore();
  }

  // =========================================================================
  // SCENE 2 (5-10s): BALANCE SHEET & DONUT LEDGER
  // =========================================================================
  function drawScene2Ledger(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    const floatY = Math.sin(range01(p, 0.14, 0.86) * Math.PI * 2) * 4.5 * u;

    ctx.save();
    ctx.translate(cx, cy + floatY + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    const dW = 324 * u;
    const dH = 256 * u;
    const left = -dW * 0.5;
    const top = -dH * 0.5;
    const fold = 38 * u;

    // Ledger Sheet Silhouette with Folded Top-Right Corner
    function docPath() {
      ctx.beginPath();
      ctx.moveTo(left + 20 * u, top);
      ctx.lineTo(left + dW - fold, top);
      ctx.lineTo(left + dW, top + fold);
      ctx.lineTo(left + dW, top + dH - 20 * u);
      ctx.arcTo(left + dW, top + dH, left + dW - 20 * u, top + dH, 20 * u);
      ctx.lineTo(left + 20 * u, top + dH);
      ctx.arcTo(left, top + dH, left, top + dH - 20 * u, 20 * u);
      ctx.lineTo(left, top + 20 * u);
      ctx.arcTo(left, top, left + 20 * u, top, 20 * u);
      ctx.closePath();
    }

    ctx.fillStyle = C.surfaceMid;
    docPath();
    ctx.fill();

    ctx.strokeStyle = C.trackStroke;
    ctx.lineWidth = 3 * u;
    docPath();
    ctx.stroke();

    // Crisp Folded Dog-Ear Flap
    ctx.fillStyle = C.surfaceLight;
    ctx.beginPath();
    ctx.moveTo(left + dW - fold, top);
    ctx.lineTo(left + dW - fold, top + fold);
    ctx.lineTo(left + dW, top + fold);
    ctx.closePath();
    ctx.fill();

    // Left Zone: 3-Segment Progressive Donut Chart at (-66u, +10u), r = 62u
    const chartX = -66 * u;
    const chartY = 10 * u;
    const chartR = 58 * u;
    const sweepTotal = easeInOutCubic(range01(p, 0.14, 0.62));
    const segments = [
      { frac: 0.45, col: C.rose },
      { frac: 0.33, col: C.apricot },
      { frac: 0.22, col: C.ivory }
    ];

    // Muted track under donut
    ctx.strokeStyle = C.bgTop;
    ctx.lineWidth = 22 * u;
    ctx.beginPath();
    ctx.arc(chartX, chartY, chartR, 0, Math.PI * 2);
    ctx.stroke();

    const gapRad = 0.08;
    let cursor = -Math.PI * 0.5;
    ctx.lineCap = 'butt';
    ctx.lineWidth = 22 * u;
    for (let i = 0; i < segments.length; i++) {
      const seg = segments[i];
      const segAngle = seg.frac * Math.PI * 2 - gapRad;
      const drawn = clamp01((sweepTotal - (cursor + Math.PI * 0.5) / (Math.PI * 2)) / seg.frac);
      if (drawn > 0.005) {
        ctx.strokeStyle = seg.col;
        ctx.beginPath();
        ctx.arc(chartX, chartY, chartR, cursor + gapRad * 0.5, cursor + gapRad * 0.5 + segAngle * drawn);
        ctx.stroke();
      }
      cursor += seg.frac * Math.PI * 2;
    }

    // Right Zone: 3 Color-Coded Ledger Balance Rows strictly clear of donut (x = +26u .. +134u)
    const rowCols = [C.rose, C.apricot, C.ivory];
    const rowWidths = [84, 68, 54];
    for (let i = 0; i < 3; i++) {
      const ry = -38 * u + i * 48 * u;
      const rp = easeOutCubic(range01(p, 0.22 + i * 0.11, 0.38 + i * 0.11));
      if (rp <= 0.01) continue;

      ctx.fillStyle = rowCols[i];
      ctx.beginPath();
      ctx.arc(32 * u, ry, 7 * u * rp, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = C.trackMuted;
      roundedRectPath(50 * u, ry - 5.5 * u, 84 * u, 11 * u, 5.5 * u);
      ctx.fill();

      ctx.fillStyle = rowCols[i];
      roundedRectPath(50 * u, ry - 5.5 * u, rowWidths[i] * u * rp, 11 * u, 5.5 * u);
      ctx.fill();
    }

    ctx.restore();
  }

  // =========================================================================
  // SCENE 3 (10-15s): TAX & AUDIT PERCENTAGE EMBLEM
  // =========================================================================
  function drawScene3Percent(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    const floatY = Math.sin(range01(p, 0.14, 0.86) * Math.PI * 2) * 4.5 * u;

    ctx.save();
    ctx.translate(cx, cy + floatY + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    // Clean Rounded Emblem Card (258u x 258u, zero circular outer loop)
    const bS = 258 * u;
    const half = bS * 0.5;
    ctx.save();
    roundedRectPath(-half, -half, bS, bS, 38 * u);
    ctx.clip();

    ctx.fillStyle = C.surfaceMid;
    ctx.fillRect(-half, -half, bS, bS);
    ctx.fillStyle = C.surfaceDark;
    ctx.beginPath();
    ctx.moveTo(half, -half);
    ctx.lineTo(half, half);
    ctx.lineTo(-half, half);
    ctx.closePath();
    ctx.fill();

    // Diagonal Audit Light Sheen Sweep (0.42 -> 0.72)
    const sheenP = easeInOutCubic(range01(p, 0.42, 0.72));
    if (sheenP > 0 && sheenP < 1) {
      const sx = (-220 + sheenP * 440) * u;
      ctx.save();
      ctx.translate(sx, 0);
      ctx.rotate(Math.PI * 0.22);
      ctx.fillStyle = C.sheen;
      ctx.fillRect(-22 * u, -200 * u, 44 * u, 400 * u);
      ctx.restore();
    }
    ctx.restore();

    ctx.strokeStyle = C.trackStroke;
    ctx.lineWidth = 3.5 * u;
    roundedRectPath(-half, -half, bS, bS, 38 * u);
    ctx.stroke();

    // Bold Pure-Vector Percentage Sign (%) — strictly separated components, zero overlap!
    const slashP = easeOutCubic(range01(p, 0.14, 0.38));
    ctx.strokeStyle = C.ivory;
    ctx.lineWidth = 18 * u;
    ctx.lineCap = 'round';
    drawPartialPolyline(
      [
        [-64 * u, 64 * u],
        [64 * u, -64 * u]
      ],
      slashP
    );

    // Top-left Coral Rose Ring at (-54u, -54u), r = 28u (clean > 24u gap from diagonal slash!)
    const r1Sc = easeOutCubic(range01(p, 0.24, 0.44));
    if (r1Sc > 0.01) {
      ctx.strokeStyle = C.rose;
      ctx.lineWidth = 14 * u;
      ctx.beginPath();
      ctx.arc(-54 * u, -54 * u, 26 * u * r1Sc, 0, Math.PI * 2);
      ctx.stroke();
    }

    // Bottom-right Warm Apricot Ring at (+54u, +54u), r = 28u
    const r2Sc = easeOutCubic(range01(p, 0.32, 0.52));
    if (r2Sc > 0.01) {
      ctx.strokeStyle = C.apricot;
      ctx.lineWidth = 14 * u;
      ctx.beginPath();
      ctx.arc(54 * u, 54 * u, 26 * u * r2Sc, 0, Math.PI * 2);
      ctx.stroke();
    }

    ctx.restore();
  }

  // =========================================================================
  // SCENE 4 (15-20s): COMPLIANT ARCHIVE FOLDER
  // =========================================================================
  function drawScene4Folder(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    const floatY = Math.sin(range01(p, 0.14, 0.86) * Math.PI * 2) * 4.5 * u;

    ctx.save();
    ctx.translate(cx, cy + 12 * u + floatY + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    const fW = 296 * u;
    const fLeft = -fW * 0.5;
    const pocketTop = -44 * u;
    const pocketH = 166 * u;

    // Back Folder Plate with Classic Top-Left Tab
    ctx.fillStyle = C.roseDeep;
    ctx.beginPath();
    ctx.moveTo(fLeft + 18 * u, -112 * u);
    ctx.lineTo(fLeft + 98 * u, -112 * u);
    ctx.lineTo(fLeft + 122 * u, -82 * u);
    ctx.lineTo(fLeft + fW - 18 * u, -82 * u);
    ctx.arcTo(fLeft + fW, -82 * u, fLeft + fW, -64 * u, 18 * u);
    ctx.lineTo(fLeft + fW, pocketTop + pocketH - 18 * u);
    ctx.lineTo(fLeft, pocketTop + pocketH - 18 * u);
    ctx.lineTo(fLeft, -94 * u);
    ctx.arcTo(fLeft, -112 * u, fLeft + 18 * u, -112 * u, 18 * u);
    ctx.closePath();
    ctx.fill();

    // 2 Crisp Financial Sheets sliding smoothly DOWN into folder pocket (clipped strictly ABOVE pocketTop!)
    ctx.save();
    ctx.beginPath();
    ctx.rect(-160 * u, -210 * u, 320 * u, 168 * u);
    ctx.clip();

    const slip1 = easeInOutCubic(range01(p, 0.14, 0.44));
    const slip2 = easeInOutCubic(range01(p, 0.26, 0.56));

    // Back sheet
    const s2Y = (-168 + slip2 * 82) * u;
    ctx.fillStyle = C.ivoryShade;
    roundedRectPath(-106 * u, s2Y, 212 * u, 130 * u, 10 * u);
    ctx.fill();

    // Front sheet with neat summary lines
    const s1Y = (-156 + slip1 * 88) * u;
    ctx.fillStyle = C.ivory;
    roundedRectPath(-118 * u, s1Y, 236 * u, 130 * u, 10 * u);
    ctx.fill();

    ctx.fillStyle = C.trackStroke;
    roundedRectPath(-90 * u, s1Y + 22 * u, 118 * u, 8 * u, 4 * u);
    ctx.fill();
    ctx.fillStyle = C.apricotMid;
    roundedRectPath(-90 * u, s1Y + 42 * u, 76 * u, 8 * u, 4 * u);
    ctx.fill();

    ctx.restore();

    // Front Folder Pocket (flat duotone Coral Rose)
    ctx.save();
    roundedRectPath(fLeft, pocketTop, fW, pocketH, 22 * u);
    ctx.clip();
    ctx.fillStyle = C.rose;
    ctx.fillRect(fLeft, pocketTop, fW * 0.52, pocketH);
    ctx.fillStyle = C.roseMid;
    ctx.fillRect(fLeft + fW * 0.52, pocketTop, fW * 0.48, pocketH);
    ctx.restore();

    // Centered Compliance Seal Emblem appearing once sheets settle
    const sealSc = easeOutCubic(range01(p, 0.34, 0.46));
    if (sealSc > 0.01) {
      const sy = pocketTop + pocketH * 0.5;
      ctx.save();
      ctx.translate(0, sy);
      ctx.scale(sealSc, sealSc);

      ctx.fillStyle = C.surfaceDark;
      ctx.beginPath();
      ctx.arc(0, 0, 34 * u, 0, Math.PI * 2);
      ctx.fill();

      const chkP = easeOutCubic(range01(p, 0.42, 0.56));
      ctx.strokeStyle = C.apricot;
      ctx.lineWidth = 7.5 * u;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      drawPartialPolyline(
        [
          [-15 * u, 1 * u],
          [-4 * u, 12 * u],
          [17 * u, -11 * u]
        ],
        chkP
      );
      ctx.restore();
    }

    ctx.restore();
  }

  // =========================================================================
  // RENDER PIPELINE
  // =========================================================================
  ctx.save();
  drawBackground();
  drawSideTelemetry();

  if (currentScene === 0) {
    drawScene1Calculator(sceneProgress);
  } else if (currentScene === 1) {
    drawScene2Ledger(sceneProgress);
  } else if (currentScene === 2) {
    drawScene3Percent(sceneProgress);
  } else {
    drawScene4Folder(sceneProgress);
  }
  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const u = minSide / 1000;
  const cx = width * 0.5;
  const cy = height * 0.5;
  const loopPhase = (loopT / duration) * Math.PI * 2;
  const heroZoom = 1.22;

  // Color Palette — Deep Royal Sapphire + Platinum Silver & Warm Rose Gold
  const C = {
    bgTop: '#060E24',
    bgMid: '#0B183B',
    bgBot: '#112456',
    gridMark: 'rgba(226, 232, 240, 0.065)',
    trackMuted: '#162A5E',
    trackStroke: '#294791',
    surfaceDark: '#0A1533',
    surfaceMid: '#12224F',
    surfaceLight: '#1D3370',
    platinum: '#E2E8F0',
    platinumMid: '#CBD5E1',
    platinumDark: '#94A3B8',
    rose: '#F4A28C',
    roseMid: '#E0866E',
    roseDeep: '#C26751',
    champagne: '#FFEBE3'
  };

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function range01(p, start, end) {
    return clamp01((p - start) / (end - start));
  }

  function easeOutCubic(x) {
    const inv = 1 - clamp01(x);
    return 1 - inv * inv * inv;
  }

  function easeInCubic(x) {
    const v = clamp01(x);
    return v * v * v;
  }

  function easeInOutCubic(x) {
    const v = clamp01(x);
    return v < 0.5 ? 4 * v * v * v : 1 - Math.pow(-2 * v + 2, 3) / 2;
  }

  function lerpColor(hexA, hexB, f) {
    const k = clamp01(f);
    const a = parseInt(hexA.slice(1), 16);
    const b = parseInt(hexB.slice(1), 16);
    const ar = (a >> 16) & 255;
    const ag = (a >> 8) & 255;
    const ab = a & 255;
    const br = (b >> 16) & 255;
    const bg = (b >> 8) & 255;
    const bb = b & 255;
    const r = Math.round(ar + (br - ar) * k);
    const g = Math.round(ag + (bg - ag) * k);
    const bl = Math.round(ab + (bb - ab) * k);
    return 'rgb(' + r + ',' + g + ',' + bl + ')';
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function drawPartialPolyline(points, progress) {
    if (progress <= 0 || points.length < 2) return;
    let totalLen = 0;
    const segLens = [];
    for (let i = 0; i < points.length - 1; i++) {
      const len = Math.hypot(points[i + 1][0] - points[i][0], points[i + 1][1] - points[i][1]);
      segLens.push(len);
      totalLen += len;
    }
    let remaining = totalLen * clamp01(progress);
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 0; i < segLens.length; i++) {
      if (remaining <= 0) break;
      if (remaining >= segLens[i]) {
        ctx.lineTo(points[i + 1][0], points[i + 1][1]);
        remaining -= segLens[i];
      } else {
        const frac = remaining / segLens[i];
        ctx.lineTo(
          points[i][0] + (points[i + 1][0] - points[i][0]) * frac,
          points[i][1] + (points[i + 1][1] - points[i][1]) * frac
        );
        remaining = 0;
      }
    }
    ctx.stroke();
  }

  function drawBackground() {
    const bgGrad = ctx.createLinearGradient(0, 0, width, height);
    bgGrad.addColorStop(0, C.bgTop);
    bgGrad.addColorStop(0.5, C.bgMid);
    bgGrad.addColorStop(1, C.bgBot);
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, width, height);

    // Subtle uniform vertical architectural pin-dashes drifting smoothly
    const stepX = 64 * u;
    const stepY = 64 * u;
    const driftY = -(loopT / duration) * stepY;
    const cols = Math.ceil(width / stepX) + 2;
    const rows = Math.ceil(height / stepY) + 2;
    const startX = cx - Math.floor(cols * 0.5) * stepX;
    const startY = cy - Math.floor(rows * 0.5) * stepY + (((driftY % stepY) + stepY) % stepY) - stepY;

    ctx.strokeStyle = C.gridMark;
    ctx.lineWidth = 1.3 * u;
    ctx.lineCap = 'round';
    ctx.beginPath();
    for (let r = 0; r < rows; r++) {
      const py = startY + r * stepY;
      if (py < 24 * u || py > height - 24 * u) continue;
      for (let c = 0; c < cols; c++) {
        const px = startX + c * stepX;
        if (px < 24 * u || px > width - 24 * u) continue;
        ctx.moveTo(px, py - 3 * u);
        ctx.lineTo(px, py + 3 * u);
      }
    }
    ctx.stroke();
  }

  function drawSideTelemetry() {
    const minHalfW = 580 * u;
    if (width * 0.5 < minHalfW + 80 * u) return;

    const sideOffset = Math.min(620 * u, width * 0.5 - 110 * u);
    const lx = cx - sideOffset;
    const rx = cx + sideOffset;

    const capW = 6 * u;
    const capH = 40 * u;
    const capGap = 20 * u;
    const totalH = sceneCount * capH + (sceneCount - 1) * capGap;
    const topY = cy - totalH * 0.5;

    const activeFade = Math.min(
      easeOutCubic(range01(sceneProgress, 0.0, 0.08)),
      1 - easeInCubic(range01(sceneProgress, 0.90, 1.0))
    );

    for (let i = 0; i < sceneCount; i++) {
      const y = topY + i * (capH + capGap);
      ctx.fillStyle = C.trackMuted;
      roundedRectPath(lx - capW * 0.5, y, capW, capH, capW * 0.5);
      ctx.fill();

      if (i === currentScene && activeFade > 0.01) {
        const fillFrac = easeInOutCubic(range01(sceneProgress, 0.0, 0.90));
        const fillH = Math.max(capW, capH * fillFrac);
        ctx.fillStyle = lerpColor(C.trackMuted, C.rose, activeFade);
        roundedRectPath(lx - capW * 0.5, y, capW, fillH, capW * 0.5);
        ctx.fill();
      }
    }

    const barMaxW = 60 * u;
    const barH = 6 * u;
    for (let i = 0; i < 4; i++) {
      const y = topY + i * (capH + capGap) + (capH - barH) * 0.5;
      const wave = 0.5 + 0.5 * Math.sin(loopPhase * 2 - i * 0.95);
      const activeW = (20 + wave * 36) * u;

      ctx.fillStyle = C.trackMuted;
      roundedRectPath(rx - barMaxW * 0.5, y, barMaxW, barH, barH * 0.5);
      ctx.fill();

      const highlight = i === currentScene ? activeFade : 0;
      ctx.fillStyle = lerpColor(C.trackStroke, i % 2 === 0 ? C.rose : C.platinum, highlight);
      roundedRectPath(rx - barMaxW * 0.5, y, activeW, barH, barH * 0.5);
      ctx.fill();
    }
  }

  function getSceneEnvelope(p) {
    const enterP = range01(p, 0.0, 0.14);
    const exitP = range01(p, 0.86, 1.0);
    const enterEase = easeOutCubic(enterP);
    const exitEase = easeInCubic(exitP);
    const scale = p < 0.5 ? 0.86 + 0.14 * enterEase : 1 - 0.14 * exitEase;
    const liftY = p < 0.5 ? (1 - enterEase) * 18 * u : -exitEase * 18 * u;
    const alpha = p < 0.10
      ? easeOutCubic(range01(p, 0.0, 0.10))
      : p > 0.90
        ? 1 - easeInCubic(range01(p, 0.90, 1.0))
        : 1;
    return { scale, alpha, liftY };
  }

  // =========================================================================
  // SCENE 1 (0-5s): FINANCIAL BALANCE SCALE
  // =========================================================================
  function drawScene1Scale(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    ctx.save();
    ctx.translate(cx, cy + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    // Stepped Pedestal Base
    ctx.fillStyle = C.platinumMid;
    roundedRectPath(-90 * u, 128 * u, 180 * u, 22 * u, 8 * u);
    ctx.fill();

    ctx.fillStyle = C.rose;
    roundedRectPath(-58 * u, 112 * u, 116 * u, 16 * u, 6 * u);
    ctx.fill();

    // Central Vertical Column
    ctx.fillStyle = C.platinum;
    roundedRectPath(-9 * u, -110 * u, 18 * u, 224 * u, 6 * u);
    ctx.fill();

    // Smooth Damped Pendulum Equilibrium Tilt (+11 deg -> -5 deg -> 0 deg)
    const eqP = range01(p, 0.12, 0.72);
    const tiltDeg = eqP < 1
      ? Math.cos(eqP * Math.PI * 2.5) * Math.pow(1 - eqP, 1.7) * 11
      : 0;
    const tiltRad = (tiltDeg * Math.PI) / 180;
    const pivotY = -92 * u;
    const armLen = 114 * u;

    // Rotating Balance Beam
    ctx.save();
    ctx.translate(0, pivotY);
    ctx.rotate(tiltRad);
    ctx.fillStyle = C.platinum;
    roundedRectPath(-armLen - 12 * u, -7 * u, (armLen + 12 * u) * 2, 14 * u, 7 * u);
    ctx.fill();
    ctx.restore();

    // Central Fulcrum Jewel
    ctx.fillStyle = C.surfaceDark;
    ctx.beginPath();
    ctx.arc(0, pivotY, 20 * u, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = C.rose;
    ctx.beginPath();
    ctx.arc(0, pivotY, 12 * u, 0, Math.PI * 2);
    ctx.fill();

    // Two Suspended Horizontal Scale Pans (stay strictly level while translating with beam ends!)
    const cordH = 98 * u;
    for (let side = -1; side <= 1; side += 2) {
      const endX = Math.cos(tiltRad) * (side * armLen);
      const endY = pivotY + Math.sin(tiltRad) * (side * armLen);
      const panY = endY + cordH;

      // V-suspension struts
      ctx.strokeStyle = C.platinumDark;
      ctx.lineWidth = 3 * u;
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(endX, endY + 6 * u);
      ctx.lineTo(endX - 42 * u, panY);
      ctx.moveTo(endX, endY + 6 * u);
      ctx.lineTo(endX + 42 * u, panY);
      ctx.stroke();

      // Attachment ring dot
      ctx.fillStyle = C.rose;
      ctx.beginPath();
      ctx.arc(endX, endY, 6 * u, 0, Math.PI * 2);
      ctx.fill();

      // 3 Neat Flat Coin Bars resting cleanly ABOVE pan tray (strict 4u vertical gap)
      for (let k = 0; k < 3; k++) {
        const barSc = easeOutCubic(range01(p, 0.14 + k * 0.06, 0.28 + k * 0.06));
        if (barSc <= 0.01) continue;
        const bw = 56 * u * barSc;
        const bh = 11 * u;
        const by = panY - 6 * u - (k + 1) * (bh + 4 * u);
        ctx.fillStyle = k === 2 ? C.champagne : C.rose;
        roundedRectPath(endX - bw * 0.5, by, bw, bh, 5 * u);
        ctx.fill();
      }

      // Flat Crescent Scale Pan Bowl
      ctx.fillStyle = C.platinum;
      ctx.beginPath();
      ctx.moveTo(endX - 50 * u, panY);
      ctx.lineTo(endX + 50 * u, panY);
      ctx.quadraticCurveTo(endX + 42 * u, panY + 24 * u, endX, panY + 24 * u);
      ctx.quadraticCurveTo(endX - 42 * u, panY + 24 * u, endX - 50 * u, panY);
      ctx.closePath();
      ctx.fill();
    }

    ctx.restore();
  }

  // =========================================================================
  // SCENE 2 (5-10s): COMPOUND COIN STACK & EXPONENTIAL CURVE
  // =========================================================================
  function drawScene2Compound(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    const floatY = Math.sin(range01(p, 0.14, 0.86) * Math.PI * 2) * 4 * u;

    ctx.save();
    ctx.translate(cx, cy + floatY + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    const baseY = 120 * u;

    // Clean Horizontal Architectural Shelf
    ctx.fillStyle = C.trackStroke;
    roundedRectPath(-156 * u, baseY + 6 * u, 312 * u, 8 * u, 4 * u);
    ctx.fill();

    // 3 Cleanly Spaced Vertical Columns of Flat 2D Coin Bars (x = -96u, 0u, +96u; barW = 64u -> 32u pure gap!)
    const cols = [
      { x: -96, count: 3, colA: C.platinumMid, colB: C.platinum, start: 0.10 },
      { x: 0, count: 5, colA: C.roseMid, colB: C.rose, start: 0.18 },
      { x: 96, count: 8, colA: C.rose, colB: C.champagne, start: 0.26 }
    ];

    const barW = 64 * u;
    const barH = 15 * u;
    const barGap = 6 * u;
    const colTops = [];

    for (let c = 0; c < cols.length; c++) {
      const col = cols[c];
      for (let k = 0; k < col.count; k++) {
        const d0 = col.start + k * 0.032;
        const dropP = easeOutCubic(range01(p, d0, d0 + 0.12));
        if (dropP <= 0.01) continue;
        const targetY = baseY - (k + 1) * barH - k * barGap;
        const curY = targetY - (1 - dropP) * 26 * u;
        ctx.save();
        ctx.globalAlpha = env.alpha * dropP;
        ctx.fillStyle = k === col.count - 1 ? col.colB : col.colA;
        roundedRectPath(col.x * u - barW * 0.5, curY, barW, barH, 6 * u);
        ctx.fill();
        ctx.restore();
      }
      const peakY = baseY - col.count * barH - (col.count - 1) * barGap;
      colTops.push([col.x * u, peakY - 34 * u]);
    }

    // Smooth Exponential Compound Curve cleanly 34u ABOVE column peaks (zero overlap!)
    const curvePts = [];
    const steps = 28;
    for (let i = 0; i <= steps; i++) {
      const f = i / steps;
      const inv = 1 - f;
      const px = inv * inv * colTops[0][0] + 2 * inv * f * (14 * u) + f * f * colTops[2][0];
      const py = inv * inv * colTops[0][1] + 2 * inv * f * (colTops[1][1] + 22 * u) + f * f * colTops[2][1];
      curvePts.push([px, py]);
    }

    const curveP = easeInOutCubic(range01(p, 0.28, 0.54));
    ctx.strokeStyle = C.champagne;
    ctx.lineWidth = 5.5 * u;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    drawPartialPolyline(curvePts, curveP);

    // Arrowhead cleanly at final peak
    const headP = easeOutCubic(range01(p, 0.48, 0.58));
    if (headP > 0.01) {
      const last = curvePts[curvePts.length - 1];
      const prev = curvePts[curvePts.length - 2];
      const ang = Math.atan2(last[1] - prev[1], last[0] - prev[0]);
      const hs = 15 * u * headP;
      ctx.save();
      ctx.translate(last[0], last[1]);
      ctx.rotate(ang);
      ctx.strokeStyle = C.champagne;
      ctx.lineWidth = 5.5 * u;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.beginPath();
      ctx.moveTo(-hs, -hs * 0.65);
      ctx.lineTo(0, 0);
      ctx.lineTo(-hs, hs * 0.65);
      ctx.stroke();
      ctx.restore();
    }

    ctx.restore();
  }

  // =========================================================================
  // SCENE 3 (10-15s): TIME-VALUE HOURGLASS
  // =========================================================================
  function drawScene3Hourglass(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    // Smooth sand drain during 0.14 -> 0.58, then crisp 180-deg architectural flip during 0.62 -> 0.84
    const drain = easeInOutCubic(range01(p, 0.14, 0.58));
    const flipRad = easeInOutCubic(range01(p, 0.62, 0.84)) * Math.PI;

    ctx.save();
    ctx.translate(cx, cy + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.rotate(flipRad);
    ctx.globalAlpha = env.alpha;

    // Architectural Glass Chamber Silhouette Path
    function glassPath() {
      ctx.beginPath();
      ctx.moveTo(-84 * u, -124 * u);
      ctx.lineTo(84 * u, -124 * u);
      ctx.bezierCurveTo(84 * u, -52 * u, 14 * u, -24 * u, 12 * u, 0);
      ctx.bezierCurveTo(14 * u, 24 * u, 84 * u, 52 * u, 84 * u, 124 * u);
      ctx.lineTo(-84 * u, 124 * u);
      ctx.bezierCurveTo(-84 * u, 52 * u, -14 * u, 24 * u, -12 * u, 0);
      ctx.bezierCurveTo(-14 * u, -24 * u, -84 * u, -52 * u, -84 * u, -124 * u);
      ctx.closePath();
    }

    // Glass Fill & Clipped Sand Accumulation
    ctx.save();
    glassPath();
    ctx.clip();

    ctx.fillStyle = C.surfaceMid;
    ctx.fillRect(-90 * u, -130 * u, 180 * u, 260 * u);

    // Upper Sand Reservoir draining smoothly
    const topSandLevel = -24 * u - (1 - drain) * 76 * u;
    if (drain < 0.99) {
      ctx.fillStyle = C.rose;
      ctx.fillRect(-90 * u, topSandLevel, 180 * u, -topSandLevel + 2 * u);
    }

    // Crisp Vertical Falling Sand Stream through narrow waist during drain
    if (drain > 0.02 && drain < 0.98) {
      ctx.fillStyle = C.champagne;
      ctx.fillRect(-2.6 * u, -4 * u, 5.2 * u, 128 * u);
    }

    // Lower Growing Sand Mound (triangular pyramid filling cleanly to bottom)
    const botH = 12 * u + drain * 88 * u;
    ctx.fillStyle = C.rose;
    ctx.beginPath();
    ctx.moveTo(-90 * u, 126 * u);
    ctx.lineTo(90 * u, 126 * u);
    ctx.lineTo(90 * u, 126 * u - botH * 0.45);
    ctx.lineTo(0, 126 * u - botH);
    ctx.lineTo(-90 * u, 126 * u - botH * 0.45);
    ctx.closePath();
    ctx.fill();

    // Soft Champagne top highlight cap on accumulated lower sand
    ctx.fillStyle = C.champagne;
    ctx.beginPath();
    ctx.moveTo(-42 * u, 126 * u - botH * 0.55);
    ctx.lineTo(0, 126 * u - botH);
    ctx.lineTo(42 * u, 126 * u - botH * 0.55);
    ctx.lineTo(0, 126 * u - botH + 10 * u);
    ctx.closePath();
    ctx.fill();

    ctx.restore();

    // Crisp Platinum Glass Contour
    ctx.strokeStyle = C.platinum;
    ctx.lineWidth = 4.5 * u;
    glassPath();
    ctx.stroke();

    // Top & Bottom Rose Gold Structural Cap Plates
    ctx.fillStyle = C.rose;
    roundedRectPath(-102 * u, -144 * u, 204 * u, 22 * u, 10 * u);
    ctx.fill();
    roundedRectPath(-102 * u, 122 * u, 204 * u, 22 * u, 10 * u);
    ctx.fill();

    // Thin Platinum Cap Trim Bars
    ctx.fillStyle = C.champagne;
    roundedRectPath(-78 * u, -137 * u, 156 * u, 6 * u, 3 * u);
    ctx.fill();
    roundedRectPath(-78 * u, 130 * u, 156 * u, 6 * u, 3 * u);
    ctx.fill();

    ctx.restore();
  }

  // =========================================================================
  // SCENE 4 (15-20s): MODERN RESERVE BANK FACADE
  // =========================================================================
  function drawScene4Bank(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    const floatY = Math.sin(range01(p, 0.14, 0.86) * Math.PI * 2) * 4.5 * u;

    ctx.save();
    ctx.translate(cx, cy + floatY + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    // 2 Stepped Foundation Plinths (bottom foundation first)
    ctx.fillStyle = C.platinumMid;
    roundedRectPath(-152 * u, 108 * u, 304 * u, 22 * u, 7 * u);
    ctx.fill();

    ctx.fillStyle = C.rose;
    roundedRectPath(-134 * u, 88 * u, 268 * u, 20 * u, 6 * u);
    ctx.fill();

    // 3 Architectural Vertical Pillars extruding smoothly upward sequentially (x = -88u, 0u, +88u; 54u gap!)
    const pillarXs = [-88, 0, 88];
    const pBaseY = 88 * u;
    const pMaxH = 122 * u;
    for (let i = 0; i < 3; i++) {
      const grow = easeOutCubic(range01(p, 0.14 + i * 0.07, 0.34 + i * 0.07));
      if (grow <= 0.01) continue;
      const px = pillarXs[i] * u;
      const curH = pMaxH * grow;
      const topY = pBaseY - curH;

      // Pillar shaft (duotone flat split)
      ctx.fillStyle = C.platinum;
      ctx.fillRect(px - 17 * u, topY, 17 * u, curH);
      ctx.fillStyle = C.platinumMid;
      ctx.fillRect(px, topY, 17 * u, curH);

      // Pillar base & capital caps
      ctx.fillStyle = C.champagne;
      roundedRectPath(px - 23 * u, pBaseY - 12 * u, 46 * u, 12 * u, 3 * u);
      ctx.fill();
      if (grow > 0.85) {
        roundedRectPath(px - 23 * u, topY, 46 * u, 12 * u, 3 * u);
        ctx.fill();
      }
    }

    // Upper Architrave Beam & Triangular Pediment Roof settling cleanly atop pillars
    const roofP = easeOutCubic(range01(p, 0.24, 0.44));
    const roofDrop = (1 - roofP) * -18 * u;
    ctx.save();
    ctx.translate(0, roofDrop);
    ctx.globalAlpha = env.alpha * roofP;

    // Architrave Beam
    ctx.fillStyle = C.rose;
    roundedRectPath(-142 * u, -56 * u, 284 * u, 22 * u, 6 * u);
    ctx.fill();

    // Triangular Pediment Roof (flat duotone split)
    ctx.fillStyle = C.platinum;
    ctx.beginPath();
    ctx.moveTo(0, -134 * u);
    ctx.lineTo(-152 * u, -56 * u);
    ctx.lineTo(0, -56 * u);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = C.platinumMid;
    ctx.beginPath();
    ctx.moveTo(0, -134 * u);
    ctx.lineTo(152 * u, -56 * u);
    ctx.lineTo(0, -56 * u);
    ctx.closePath();
    ctx.fill();

    // Centered Rose Gold Pediment Medallion
    ctx.fillStyle = C.surfaceDark;
    ctx.beginPath();
    ctx.arc(0, -84 * u, 18 * u, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = C.rose;
    ctx.beginPath();
    ctx.arc(0, -84 * u, 11 * u, 0, Math.PI * 2);
    ctx.fill();

    ctx.restore();
    ctx.restore();
  }

  // =========================================================================
  // RENDER PIPELINE
  // =========================================================================
  ctx.save();
  drawBackground();
  drawSideTelemetry();

  if (currentScene === 0) {
    drawScene1Scale(sceneProgress);
  } else if (currentScene === 1) {
    drawScene2Compound(sceneProgress);
  } else if (currentScene === 2) {
    drawScene3Hourglass(sceneProgress);
  } else {
    drawScene4Bank(sceneProgress);
  }
  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const u = minSide / 1000;
  const cx = width * 0.5;
  const cy = height * 0.5;
  const loopPhase = (loopT / duration) * Math.PI * 2;
  const heroZoom = 1.22;

  // Color Palette — Dark Espresso Bronze + Burnished Luxury Gold & Champagne
  const C = {
    bgTop: '#140D09',
    bgMid: '#1F140E',
    bgBot: '#2C1B12',
    gridMark: 'rgba(245, 197, 66, 0.06)',
    trackMuted: '#362318',
    trackStroke: '#593B28',
    surfaceDark: '#1C120C',
    surfaceMid: '#291A11',
    surfaceLight: '#3B2619',
    gold: '#F5C542',
    goldMid: '#DDA520',
    goldDeep: '#B37E12',
    copper: '#E07A38',
    copperDeep: '#B85A22',
    champagne: '#FFF0B8',
    cream: '#FFF9E6',
    sheen: 'rgba(255, 249, 230, 0.22)'
  };

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function range01(p, start, end) {
    return clamp01((p - start) / (end - start));
  }

  function easeOutCubic(x) {
    const inv = 1 - clamp01(x);
    return 1 - inv * inv * inv;
  }

  function easeInCubic(x) {
    const v = clamp01(x);
    return v * v * v;
  }

  function easeInOutCubic(x) {
    const v = clamp01(x);
    return v < 0.5 ? 4 * v * v * v : 1 - Math.pow(-2 * v + 2, 3) / 2;
  }

  function lerpColor(hexA, hexB, f) {
    const k = clamp01(f);
    const a = parseInt(hexA.slice(1), 16);
    const b = parseInt(hexB.slice(1), 16);
    const ar = (a >> 16) & 255;
    const ag = (a >> 8) & 255;
    const ab = a & 255;
    const br = (b >> 16) & 255;
    const bg = (b >> 8) & 255;
    const bb = b & 255;
    const r = Math.round(ar + (br - ar) * k);
    const g = Math.round(ag + (bg - ag) * k);
    const bl = Math.round(ab + (bb - ab) * k);
    return 'rgb(' + r + ',' + g + ',' + bl + ')';
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function starPath(x, y, rOut, rIn, points) {
    ctx.beginPath();
    for (let i = 0; i < points * 2; i++) {
      const r = i % 2 === 0 ? rOut : rIn;
      const a = -Math.PI * 0.5 + (i * Math.PI) / points;
      const px = x + Math.cos(a) * r;
      const py = y + Math.sin(a) * r;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
  }

  function drawPartialPolyline(points, progress) {
    if (progress <= 0 || points.length < 2) return;
    let totalLen = 0;
    const segLens = [];
    for (let i = 0; i < points.length - 1; i++) {
      const len = Math.hypot(points[i + 1][0] - points[i][0], points[i + 1][1] - points[i][1]);
      segLens.push(len);
      totalLen += len;
    }
    let remaining = totalLen * clamp01(progress);
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 0; i < segLens.length; i++) {
      if (remaining <= 0) break;
      if (remaining >= segLens[i]) {
        ctx.lineTo(points[i + 1][0], points[i + 1][1]);
        remaining -= segLens[i];
      } else {
        const frac = remaining / segLens[i];
        ctx.lineTo(
          points[i][0] + (points[i + 1][0] - points[i][0]) * frac,
          points[i][1] + (points[i + 1][1] - points[i][1]) * frac
        );
        remaining = 0;
      }
    }
    ctx.stroke();
  }

  function drawBackground() {
    const bgGrad = ctx.createLinearGradient(0, 0, width, height);
    bgGrad.addColorStop(0, C.bgTop);
    bgGrad.addColorStop(0.5, C.bgMid);
    bgGrad.addColorStop(1, C.bgBot);
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, width, height);

    // Subtle uniform architectural gold micro-ticks drifting seamlessly
    const step = 64 * u;
    const driftY = (loopT / duration) * step;
    const cols = Math.ceil(width / step) + 2;
    const rows = Math.ceil(height / step) + 2;
    const startX = cx - Math.floor(cols * 0.5) * step;
    const startY = cy - Math.floor(rows * 0.5) * step + (driftY % step) - step;
    const r = 1.5 * u;

    ctx.fillStyle = C.gridMark;
    ctx.beginPath();
    for (let row = 0; row < rows; row++) {
      const py = startY + row * step;
      if (py < 24 * u || py > height - 24 * u) continue;
      for (let col = 0; col < cols; col++) {
        const px = startX + col * step;
        if (px < 24 * u || px > width - 24 * u) continue;
        ctx.moveTo(px + r, py);
        ctx.arc(px, py, r, 0, Math.PI * 2);
      }
    }
    ctx.fill();
  }

  function drawSideTelemetry() {
    const minHalfW = 580 * u;
    if (width * 0.5 < minHalfW + 80 * u) return;

    const sideOffset = Math.min(620 * u, width * 0.5 - 110 * u);
    const lx = cx - sideOffset;
    const rx = cx + sideOffset;

    const capW = 6 * u;
    const capH = 40 * u;
    const capGap = 20 * u;
    const totalH = sceneCount * capH + (sceneCount - 1) * capGap;
    const topY = cy - totalH * 0.5;

    const activeFade = Math.min(
      easeOutCubic(range01(sceneProgress, 0.0, 0.08)),
      1 - easeInCubic(range01(sceneProgress, 0.90, 1.0))
    );

    for (let i = 0; i < sceneCount; i++) {
      const y = topY + i * (capH + capGap);
      ctx.fillStyle = C.trackMuted;
      roundedRectPath(lx - capW * 0.5, y, capW, capH, capW * 0.5);
      ctx.fill();

      if (i === currentScene && activeFade > 0.01) {
        const fillFrac = easeInOutCubic(range01(sceneProgress, 0.0, 0.90));
        const fillH = Math.max(capW, capH * fillFrac);
        ctx.fillStyle = lerpColor(C.trackMuted, C.gold, activeFade);
        roundedRectPath(lx - capW * 0.5, y, capW, fillH, capW * 0.5);
        ctx.fill();
      }
    }

    const barMaxW = 60 * u;
    const barH = 6 * u;
    for (let i = 0; i < 4; i++) {
      const y = topY + i * (capH + capGap) + (capH - barH) * 0.5;
      const wave = 0.5 + 0.5 * Math.sin(loopPhase * 2 - i * 0.85);
      const activeW = (18 + wave * 38) * u;

      ctx.fillStyle = C.trackMuted;
      roundedRectPath(rx - barMaxW * 0.5, y, barMaxW, barH, barH * 0.5);
      ctx.fill();

      const highlight = i === currentScene ? activeFade : 0;
      ctx.fillStyle = lerpColor(C.trackStroke, C.gold, highlight);
      roundedRectPath(rx - barMaxW * 0.5, y, activeW, barH, barH * 0.5);
      ctx.fill();
    }
  }

  function getSceneEnvelope(p) {
    const enterP = range01(p, 0.0, 0.14);
    const exitP = range01(p, 0.86, 1.0);
    const enterEase = easeOutCubic(enterP);
    const exitEase = easeInCubic(exitP);
    const scale = p < 0.5 ? 0.86 + 0.14 * enterEase : 1 - 0.14 * exitEase;
    const liftY = p < 0.5 ? (1 - enterEase) * 18 * u : -exitEase * 18 * u;
    const alpha = p < 0.10
      ? easeOutCubic(range01(p, 0.0, 0.10))
      : p > 0.90
        ? 1 - easeInCubic(range01(p, 0.90, 1.0))
        : 1;
    return { scale, alpha, liftY };
  }

  // =========================================================================
  // SCENE 1 (0-5s): PRECISION BULLSEYE TARGET & DART ARROW
  // =========================================================================
  function drawScene1Target(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    const floatY = Math.sin(range01(p, 0.14, 0.86) * Math.PI * 2) * 4.5 * u;

    ctx.save();
    ctx.translate(cx, cy + floatY + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    // 4 Concentric Target Discs blooming sequentially from outside in
    const rings = [
      { r: 164, colL: C.gold, colR: C.goldMid, delay: 0.02 },
      { r: 124, colL: C.surfaceMid, colR: C.surfaceDark, delay: 0.06 },
      { r: 84, colL: C.copper, colR: C.copperDeep, delay: 0.10 },
      { r: 44, colL: C.champagne, colR: C.gold, delay: 0.14 }
    ];

    for (let i = 0; i < rings.length; i++) {
      const rg = rings[i];
      const sc = easeOutCubic(range01(p, rg.delay, rg.delay + 0.14));
      if (sc <= 0.01) continue;
      const rr = rg.r * u * sc;
      ctx.save();
      ctx.beginPath();
      ctx.arc(0, 0, rr, 0, Math.PI * 2);
      ctx.clip();
      ctx.fillStyle = rg.colL;
      ctx.fillRect(-rr, -rr, rr, rr * 2);
      ctx.fillStyle = rg.colR;
      ctx.fillRect(0, -rr, rr, rr * 2);
      ctx.restore();
    }

    // Center bullseye pin
    const pinSc = easeOutCubic(range01(p, 0.18, 0.28));
    if (pinSc > 0.01) {
      ctx.fillStyle = C.surfaceDark;
      ctx.beginPath();
      ctx.arc(0, 0, 15 * u * pinSc, 0, Math.PI * 2);
      ctx.fill();
    }

    // Crisp Precision Arrow flying smoothly into bullseye (0.24 -> 0.42) with subtle damped settle
    const flyP = range01(p, 0.24, 0.42);
    if (flyP > 0.01) {
      const approach = easeOutCubic(flyP);
      const dist = (1 - approach) * 185 * u;
      const hitT = range01(p, 0.42, 0.68);
      const dampedDeg = hitT > 0 && hitT < 1
        ? Math.sin(hitT * Math.PI * 4) * Math.exp(-hitT * 4.5) * 3.2
        : 0;
      const arrowAlpha = easeOutCubic(range01(flyP, 0, 0.25));

      ctx.save();
      ctx.globalAlpha = env.alpha * arrowAlpha;
      ctx.rotate((-45 + dampedDeg) * (Math.PI / 180));
      ctx.translate(dist, 0);

      // Clean shaft from tip (x = 8u) to tail (x = 176u)
      ctx.strokeStyle = C.cream;
      ctx.lineWidth = 7 * u;
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(10 * u, 0);
      ctx.lineTo(176 * u, 0);
      ctx.stroke();

      // Sharp dart head pointing precisely into bullseye center (0, 0)
      ctx.fillStyle = C.champagne;
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.lineTo(24 * u, -11 * u);
      ctx.lineTo(18 * u, 0);
      ctx.lineTo(24 * u, 11 * u);
      ctx.closePath();
      ctx.fill();

      // Symmetrical flat tail fletching feathers
      ctx.fillStyle = C.gold;
      ctx.beginPath();
      ctx.moveTo(132 * u, -4 * u);
      ctx.lineTo(156 * u, -24 * u);
      ctx.lineTo(186 * u, -24 * u);
      ctx.lineTo(168 * u, -4 * u);
      ctx.closePath();
      ctx.fill();

      ctx.fillStyle = C.copper;
      ctx.beginPath();
      ctx.moveTo(132 * u, 4 * u);
      ctx.lineTo(156 * u, 24 * u);
      ctx.lineTo(186 * u, 24 * u);
      ctx.lineTo(168 * u, 4 * u);
      ctx.closePath();
      ctx.fill();

      ctx.restore();
    }

    // 4 Clean Short Impact Ticks strictly outside outer ring (r = 182u .. 202u) on arrow hit
    const hitTickP = range01(p, 0.42, 0.68);
    if (hitTickP > 0 && hitTickP < 1) {
      const fade = Math.sin(hitTickP * Math.PI);
      const offset = easeOutCubic(hitTickP) * 14 * u;
      ctx.save();
      ctx.globalAlpha = env.alpha * fade * 0.85;
      ctx.strokeStyle = C.champagne;
      ctx.lineWidth = 3.2 * u;
      ctx.lineCap = 'round';
      for (let i = 0; i < 4; i++) {
        const a = i * (Math.PI * 0.5) + Math.PI * 0.25;
        if (i === 3) continue; // Keep arrow flight corridor unobstructed
        const r0 = 180 * u + offset;
        const r1 = r0 + 16 * u;
        ctx.beginPath();
        ctx.moveTo(Math.cos(a) * r0, Math.sin(a) * r0);
        ctx.lineTo(Math.cos(a) * r1, Math.sin(a) * r1);
        ctx.stroke();
      }
      ctx.restore();
    }

    ctx.restore();
  }

  // =========================================================================
  // SCENE 2 (5-10s): STRATEGIC BLUEPRINT BOARD
  // =========================================================================
  function drawScene2Blueprint(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    const floatY = Math.sin(range01(p, 0.14, 0.86) * Math.PI * 2) * 4.5 * u;

    ctx.save();
    ctx.translate(cx, cy + floatY + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    const bW = 340 * u;
    const bH = 262 * u;
    const left = -bW * 0.5;
    const top = -bH * 0.5;
    const rad = 22 * u;

    ctx.fillStyle = C.surfaceMid;
    roundedRectPath(left, top, bW, bH, rad);
    ctx.fill();

    // Subtle internal blueprint grid + header clipped cleanly inside board
    ctx.save();
    roundedRectPath(left, top, bW, bH, rad);
    ctx.clip();

    ctx.strokeStyle = 'rgba(245, 197, 66, 0.07)';
    ctx.lineWidth = 1.2 * u;
    for (let x = -136; x <= 136; x += 34) {
      ctx.beginPath();
      ctx.moveTo(x * u, top + 42 * u);
      ctx.lineTo(x * u, top + bH);
      ctx.stroke();
    }
    for (let y = -54; y <= 96; y += 34) {
      ctx.beginPath();
      ctx.moveTo(left, y * u);
      ctx.lineTo(left + bW, y * u);
      ctx.stroke();
    }

    ctx.fillStyle = C.surfaceDark;
    ctx.fillRect(left, top, bW, 42 * u);
    ctx.strokeStyle = C.trackStroke;
    ctx.lineWidth = 2 * u;
    ctx.beginPath();
    ctx.moveTo(left, top + 42 * u);
    ctx.lineTo(left + bW, top + 42 * u);
    ctx.stroke();
    ctx.restore();

    ctx.strokeStyle = C.trackStroke;
    ctx.lineWidth = 3 * u;
    roundedRectPath(left, top, bW, bH, rad);
    ctx.stroke();

    // Header accent bars
    const hy = top + 21 * u;
    ctx.fillStyle = C.gold;
    roundedRectPath(left + 22 * u, hy - 4.5 * u, 54 * u, 9 * u, 4.5 * u);
    ctx.fill();
    ctx.fillStyle = C.trackStroke;
    roundedRectPath(left + bW - 62 * u, hy - 4.5 * u, 40 * u, 9 * u, 4.5 * u);
    ctx.fill();

    // Smooth curved strategic path passing cleanly between 3 well-separated milestones
    // M1: (-100, +68), M2: (0, +18), M3: (+100, -34) — generous > 110u spacing!
    const m1 = [-100 * u, 68 * u];
    const m2 = [0, 18 * u];
    const m3 = [100 * u, -34 * u];

    const routePts = [];
    const segs = 28;
    for (let i = 0; i <= segs; i++) {
      const f = i / segs;
      let px, py;
      if (f <= 0.5) {
        const s = f * 2;
        const inv = 1 - s;
        px = inv * inv * m1[0] + 2 * inv * s * (-48 * u) + s * s * m2[0];
        py = inv * inv * m1[1] + 2 * inv * s * (68 * u) + s * s * m2[1];
      } else {
        const s = (f - 0.5) * 2;
        const inv = 1 - s;
        px = inv * inv * m2[0] + 2 * inv * s * (48 * u) + s * s * m3[0];
        py = inv * inv * m2[1] + 2 * inv * s * (-34 * u) + s * s * m3[1];
      }
      routePts.push([px, py]);
    }

    const pathP = easeInOutCubic(range01(p, 0.14, 0.52));
    ctx.strokeStyle = C.gold;
    ctx.lineWidth = 4.2 * u;
    ctx.lineCap = 'round';
    ctx.setLineDash([9 * u, 9 * u]);
    drawPartialPolyline(routePts, pathP);
    ctx.setLineDash([]);

    // Milestone 1: Crisp Circle Badge
    const m1Sc = easeOutCubic(range01(p, 0.10, 0.22));
    if (m1Sc > 0.01) {
      ctx.save();
      ctx.translate(m1[0], m1[1]);
      ctx.scale(m1Sc, m1Sc);
      ctx.fillStyle = C.surfaceDark;
      ctx.beginPath();
      ctx.arc(0, 0, 20 * u, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = C.copper;
      ctx.lineWidth = 4 * u;
      ctx.stroke();
      ctx.fillStyle = C.champagne;
      ctx.beginPath();
      ctx.arc(0, 0, 7 * u, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }

    // Milestone 2: Crisp Diamond Node
    const m2Sc = easeOutCubic(range01(p, 0.28, 0.40));
    if (m2Sc > 0.01) {
      ctx.save();
      ctx.translate(m2[0], m2[1]);
      ctx.scale(m2Sc, m2Sc);
      ctx.rotate(Math.PI * 0.25);
      ctx.fillStyle = C.surfaceDark;
      roundedRectPath(-16 * u, -16 * u, 32 * u, 32 * u, 5 * u);
      ctx.fill();
      ctx.strokeStyle = C.gold;
      ctx.lineWidth = 4 * u;
      ctx.stroke();
      ctx.fillStyle = C.cream;
      roundedRectPath(-6 * u, -6 * u, 12 * u, 12 * u, 2 * u);
      ctx.fill();
      ctx.restore();
    }

    // Milestone 3: Gleaming 5-Point Gold Target Star
    const m3Sc = easeOutCubic(range01(p, 0.44, 0.56));
    if (m3Sc > 0.01) {
      ctx.save();
      ctx.translate(m3[0], m3[1]);
      ctx.scale(m3Sc, m3Sc);
      ctx.fillStyle = C.surfaceDark;
      ctx.beginPath();
      ctx.arc(0, 0, 26 * u, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = C.gold;
      starPath(0, 0, 22 * u, 10 * u, 5);
      ctx.fill();
      ctx.fillStyle = C.cream;
      starPath(0, 0, 10 * u, 4.5 * u, 5);
      ctx.fill();
      ctx.restore();
    }

    ctx.restore();
  }

  // =========================================================================
  // SCENE 3 (10-15s): EXECUTIVE KPI PERFORMANCE GAUGE
  // =========================================================================
  function drawScene3Gauge(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    ctx.save();
    ctx.translate(cx, cy + 20 * u + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    const gaugeR = 154 * u;
    const deg = Math.PI / 180;
    const startDeg = 160; // Left-lower start (220 deg total arc sweep to 380 deg / +20 deg)
    const segSpan = 50;
    const gapDeg = 6;
    const segCols = [C.copperDeep, C.copper, C.goldMid, C.gold];

    // Background muted arc track
    ctx.strokeStyle = C.surfaceLight;
    ctx.lineWidth = 24 * u;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.arc(0, 0, gaugeR, startDeg * deg, (startDeg + 4 * segSpan + 3 * gapDeg) * deg);
    ctx.stroke();

    // 4 Segmented KPI Performance Zones filling smoothly with needle sweep
    const sweepP = easeInOutCubic(range01(p, 0.14, 0.64));
    const liveOsc = Math.sin(range01(p, 0.64, 0.86) * Math.PI * 2) * 0.03;
    const kpiLevel = clamp01(sweepP * 0.90 + liveOsc);

    ctx.lineCap = 'butt';
    ctx.lineWidth = 24 * u;
    for (let i = 0; i < 4; i++) {
      const a0 = (startDeg + i * (segSpan + gapDeg)) * deg;
      const a1 = a0 + segSpan * deg;
      const segFill = clamp01((kpiLevel * 4) - i);
      if (segFill <= 0.001) continue;
      ctx.strokeStyle = segCols[i];
      ctx.beginPath();
      ctx.arc(0, 0, gaugeR, a0, a0 + (a1 - a0) * segFill);
      ctx.stroke();
    }

    // Crisp inner precision ticks (r = 120u .. 130u; 12u gap inside gauge arc!)
    ctx.lineCap = 'round';
    for (let i = 0; i <= 12; i++) {
      const a = (startDeg + (i / 12) * 218) * deg;
      const active = i / 12 <= kpiLevel;
      ctx.strokeStyle = active ? C.champagne : C.trackStroke;
      ctx.lineWidth = (i % 3 === 0 ? 3 : 1.8) * u;
      ctx.beginPath();
      ctx.moveTo(Math.cos(a) * 120 * u, Math.sin(a) * 120 * u);
      ctx.lineTo(Math.cos(a) * 130 * u, Math.sin(a) * 130 * u);
      ctx.stroke();
    }

    // Sleek Tapered KPI Needle (tip at r = 108u; 12u clear of inner ticks!)
    const needleAng = (startDeg + kpiLevel * 218) * deg;
    ctx.save();
    ctx.rotate(needleAng);
    ctx.fillStyle = C.cream;
    ctx.beginPath();
    ctx.moveTo(108 * u, 0);
    ctx.lineTo(-14 * u, -10 * u);
    ctx.lineTo(-14 * u, 10 * u);
    ctx.closePath();
    ctx.fill();
    ctx.restore();

    // Central layered pivot hub
    ctx.fillStyle = C.surfaceDark;
    ctx.beginPath();
    ctx.arc(0, 0, 26 * u, 0, Math.PI * 2);
    ctx.fill();

    ctx.strokeStyle = C.gold;
    ctx.lineWidth = 5 * u;
    ctx.beginPath();
    ctx.arc(0, 0, 22 * u, 0, Math.PI * 2);
    ctx.stroke();

    ctx.fillStyle = C.champagne;
    ctx.beginPath();
    ctx.arc(0, 0, 8 * u, 0, Math.PI * 2);
    ctx.fill();

    // 3 Clean KPI Readout Pills strictly BELOW hub (y = +66u, zero overlap!)
    const pillW = 48 * u;
    const pillH = 10 * u;
    const pillGap = 16 * u;
    const pStart = -(3 * pillW + 2 * pillGap) * 0.5;
    for (let i = 0; i < 3; i++) {
      const lit = easeOutCubic(range01(kpiLevel, i * 0.28, i * 0.28 + 0.18));
      ctx.fillStyle = lerpColor(C.trackMuted, i === 2 ? C.gold : C.copper, lit);
      roundedRectPath(pStart + i * (pillW + pillGap), 66 * u, pillW, pillH, pillH * 0.5);
      ctx.fill();
    }

    ctx.restore();
  }

  // =========================================================================
  // SCENE 4 (15-20s): EXCELLENCE TROPHY CREST
  // =========================================================================
  function drawScene4Trophy(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    const floatY = Math.sin(range01(p, 0.14, 0.86) * Math.PI * 2) * 5 * u;

    ctx.save();
    ctx.translate(cx, cy + 16 * u + floatY + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    // Symmetrical Trophy Handles drawn cleanly BEHIND main cup body
    ctx.strokeStyle = C.goldMid;
    ctx.lineWidth = 14 * u;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    for (let side = -1; side <= 1; side += 2) {
      ctx.beginPath();
      ctx.moveTo(side * 72 * u, -78 * u);
      ctx.lineTo(side * 116 * u, -78 * u);
      ctx.quadraticCurveTo(side * 124 * u, -24 * u, side * 66 * u, -8 * u);
      ctx.stroke();
    }

    // Tapered Stem
    ctx.fillStyle = C.goldDeep;
    ctx.beginPath();
    ctx.moveTo(-22 * u, 36 * u);
    ctx.lineTo(22 * u, 36 * u);
    ctx.lineTo(30 * u, 82 * u);
    ctx.lineTo(-30 * u, 82 * u);
    ctx.closePath();
    ctx.fill();

    // Stepped Pedestal Base
    ctx.fillStyle = C.goldMid;
    roundedRectPath(-62 * u, 78 * u, 124 * u, 18 * u, 6 * u);
    ctx.fill();

    ctx.fillStyle = C.surfaceMid;
    roundedRectPath(-82 * u, 96 * u, 164 * u, 38 * u, 10 * u);
    ctx.fill();

    ctx.strokeStyle = C.trackStroke;
    ctx.lineWidth = 2.6 * u;
    roundedRectPath(-82 * u, 96 * u, 164 * u, 38 * u, 10 * u);
    ctx.stroke();

    // Pedestal Nameplate Bar
    ctx.fillStyle = C.champagne;
    roundedRectPath(-42 * u, 110 * u, 84 * u, 10 * u, 5 * u);
    ctx.fill();

    // Main Trophy Cup Bowl (flat duotone split + sheen clipped cleanly)
    ctx.save();
    ctx.beginPath();
    ctx.moveTo(-84 * u, -98 * u);
    ctx.lineTo(84 * u, -98 * u);
    ctx.lineTo(78 * u, -24 * u);
    ctx.quadraticCurveTo(68 * u, 42 * u, 0, 44 * u);
    ctx.quadraticCurveTo(-68 * u, 42 * u, -78 * u, -24 * u);
    ctx.closePath();
    ctx.clip();

    ctx.fillStyle = C.gold;
    ctx.fillRect(-90 * u, -102 * u, 90 * u, 152 * u);
    ctx.fillStyle = C.goldMid;
    ctx.fillRect(0, -102 * u, 90 * u, 152 * u);

    // Diagonal light sheen sweep (0.36 -> 0.66)
    const sheenP = easeInOutCubic(range01(p, 0.36, 0.66));
    if (sheenP > 0 && sheenP < 1) {
      const sx = (-150 + sheenP * 300) * u;
      ctx.save();
      ctx.translate(sx, -28 * u);
      ctx.rotate(Math.PI * 0.2);
      ctx.fillStyle = C.sheen;
      ctx.fillRect(-18 * u, -120 * u, 36 * u, 240 * u);
      ctx.restore();
    }
    ctx.restore();

    // Top Cup Rim Band
    ctx.fillStyle = C.champagne;
    roundedRectPath(-92 * u, -106 * u, 184 * u, 14 * u, 7 * u);
    ctx.fill();

    // Floating 5-Point Achievement Star cleanly 44u ABOVE cup rim (y = -152u)
    const starSc = easeOutCubic(range01(p, 0.20, 0.38));
    const starHover = Math.sin(range01(p, 0.28, 0.86) * Math.PI * 2) * 5 * u;
    if (starSc > 0.01) {
      ctx.save();
      ctx.translate(0, -152 * u + starHover);
      ctx.scale(starSc, starSc);
      ctx.fillStyle = C.champagne;
      starPath(0, 0, 26 * u, 11.5 * u, 5);
      ctx.fill();
      ctx.fillStyle = C.cream;
      starPath(0, 0, 12 * u, 5.5 * u, 5);
      ctx.fill();
      ctx.restore();
    }

    // 4 Clean Diagonal Celebration Dashes flanking upper trophy (strictly outside handles & star)
    const rayIn = easeOutCubic(range01(p, 0.32, 0.48));
    const rayOut = 1 - easeInCubic(range01(p, 0.70, 0.85));
    const rayAmt = Math.min(rayIn, rayOut);
    if (rayAmt > 0.01) {
      const rays = [
        [-144, -126, -162, -142],
        [144, -126, 162, -142],
        [-152, -46, -172, -46],
        [152, -46, 172, -46]
      ];
      ctx.strokeStyle = C.champagne;
      ctx.lineWidth = 3.6 * u;
      ctx.lineCap = 'round';
      for (let i = 0; i < rays.length; i++) {
        const r = rays[i];
        const x1 = r[0] + (r[2] - r[0]) * rayAmt;
        const y1 = r[1] + (r[3] - r[1]) * rayAmt;
        ctx.beginPath();
        ctx.moveTo(r[0] * u, r[1] * u);
        ctx.lineTo(x1 * u, y1 * u);
        ctx.stroke();
      }
    }

    ctx.restore();
  }

  // =========================================================================
  // RENDER PIPELINE
  // =========================================================================
  ctx.save();
  drawBackground();
  drawSideTelemetry();

  if (currentScene === 0) {
    drawScene1Target(sceneProgress);
  } else if (currentScene === 1) {
    drawScene2Blueprint(sceneProgress);
  } else if (currentScene === 2) {
    drawScene3Gauge(sceneProgress);
  } else {
    drawScene4Trophy(sceneProgress);
  }
  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const u = minSide / 1000;
  const cx = width * 0.5;
  const cy = height * 0.5;
  const loopPhase = (loopT / duration) * Math.PI * 2;
  const heroZoom = 1.22;

  // Color Palette — Dark Matte Graphite + Solar Citrine Yellow & Vivid Cerulean
  const C = {
    bgTop: '#0B0E11',
    bgMid: '#12181F',
    bgBot: '#1B232B',
    gridMark: 'rgba(250, 204, 21, 0.06)',
    trackMuted: '#222C38',
    trackStroke: '#37485C',
    surfaceDark: '#121921',
    surfaceMid: '#1C2632',
    surfaceLight: '#283647',
    citrine: '#FACC15',
    citrineMid: '#EAB308',
    cerulean: '#0EA5E9',
    ceruleanMid: '#0284C7',
    ceruleanDeep: '#0369A1',
    cream: '#FEFCE8',
    white: '#F8FAFC'
  };

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function range01(p, start, end) {
    return clamp01((p - start) / (end - start));
  }

  function easeOutCubic(x) {
    const inv = 1 - clamp01(x);
    return 1 - inv * inv * inv;
  }

  function easeInCubic(x) {
    const v = clamp01(x);
    return v * v * v;
  }

  function easeInOutCubic(x) {
    const v = clamp01(x);
    return v < 0.5 ? 4 * v * v * v : 1 - Math.pow(-2 * v + 2, 3) / 2;
  }

  function lerpColor(hexA, hexB, f) {
    const k = clamp01(f);
    const a = parseInt(hexA.slice(1), 16);
    const b = parseInt(hexB.slice(1), 16);
    const ar = (a >> 16) & 255;
    const ag = (a >> 8) & 255;
    const ab = a & 255;
    const br = (b >> 16) & 255;
    const bg = (b >> 8) & 255;
    const bb = b & 255;
    const r = Math.round(ar + (br - ar) * k);
    const g = Math.round(ag + (bg - ag) * k);
    const bl = Math.round(ab + (bb - ab) * k);
    return 'rgb(' + r + ',' + g + ',' + bl + ')';
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function drawBackground() {
    const bgGrad = ctx.createLinearGradient(0, 0, width, height);
    bgGrad.addColorStop(0, C.bgTop);
    bgGrad.addColorStop(0.5, C.bgMid);
    bgGrad.addColorStop(1, C.bgBot);
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, width, height);

    // Subtle uniform cloud-infrastructure micro-pills drifting seamlessly
    const stepX = 68 * u;
    const stepY = 58 * u;
    const driftX = (loopT / duration) * stepX;
    const cols = Math.ceil(width / stepX) + 2;
    const rows = Math.ceil(height / stepY) + 2;
    const startX = cx - Math.floor(cols * 0.5) * stepX + (driftX % stepX) - stepX;
    const startY = cy - Math.floor(rows * 0.5) * stepY;

    ctx.fillStyle = C.gridMark;
    for (let r = 0; r < rows; r++) {
      const py = startY + r * stepY;
      if (py < 24 * u || py > height - 24 * u) continue;
      for (let c = 0; c < cols; c++) {
        const px = startX + c * stepX;
        if (px < 24 * u || px > width - 24 * u) continue;
        ctx.fillRect(px - 2.5 * u, py - 1 * u, 5 * u, 2 * u);
      }
    }
  }

  function drawSideTelemetry() {
    const minHalfW = 580 * u;
    if (width * 0.5 < minHalfW + 80 * u) return;

    const sideOffset = Math.min(620 * u, width * 0.5 - 110 * u);
    const lx = cx - sideOffset;
    const rx = cx + sideOffset;

    const capW = 6 * u;
    const capH = 40 * u;
    const capGap = 20 * u;
    const totalH = sceneCount * capH + (sceneCount - 1) * capGap;
    const topY = cy - totalH * 0.5;

    const activeFade = Math.min(
      easeOutCubic(range01(sceneProgress, 0.0, 0.08)),
      1 - easeInCubic(range01(sceneProgress, 0.90, 1.0))
    );

    for (let i = 0; i < sceneCount; i++) {
      const y = topY + i * (capH + capGap);
      ctx.fillStyle = C.trackMuted;
      roundedRectPath(lx - capW * 0.5, y, capW, capH, capW * 0.5);
      ctx.fill();

      if (i === currentScene && activeFade > 0.01) {
        const fillFrac = easeInOutCubic(range01(sceneProgress, 0.0, 0.90));
        const fillH = Math.max(capW, capH * fillFrac);
        ctx.fillStyle = lerpColor(C.trackMuted, C.citrine, activeFade);
        roundedRectPath(lx - capW * 0.5, y, capW, fillH, capW * 0.5);
        ctx.fill();
      }
    }

    const barMaxW = 60 * u;
    const barH = 6 * u;
    for (let i = 0; i < 4; i++) {
      const y = topY + i * (capH + capGap) + (capH - barH) * 0.5;
      const wave = 0.5 + 0.5 * Math.sin(loopPhase * 2 + i * 1.05);
      const activeW = (18 + wave * 38) * u;

      ctx.fillStyle = C.trackMuted;
      roundedRectPath(rx - barMaxW * 0.5, y, barMaxW, barH, barH * 0.5);
      ctx.fill();

      const highlight = i === currentScene ? activeFade : 0;
      ctx.fillStyle = lerpColor(C.trackStroke, i % 2 === 0 ? C.citrine : C.cerulean, highlight);
      roundedRectPath(rx - barMaxW * 0.5, y, activeW, barH, barH * 0.5);
      ctx.fill();
    }
  }

  function getSceneEnvelope(p) {
    const enterP = range01(p, 0.0, 0.14);
    const exitP = range01(p, 0.86, 1.0);
    const enterEase = easeOutCubic(enterP);
    const exitEase = easeInCubic(exitP);
    const scale = p < 0.5 ? 0.86 + 0.14 * enterEase : 1 - 0.14 * exitEase;
    const liftY = p < 0.5 ? (1 - enterEase) * 18 * u : -exitEase * 18 * u;
    const alpha = p < 0.10
      ? easeOutCubic(range01(p, 0.0, 0.10))
      : p > 0.90
        ? 1 - easeInCubic(range01(p, 0.90, 1.0))
        : 1;
    return { scale, alpha, liftY };
  }

  // =========================================================================
  // SCENE 1 (0-5s): MODULAR FINOPS CLOUD
  // =========================================================================
  function cloudSilhouettePath() {
    // Smooth unified 2D flat vector cloud silhouette (width ~304u, y = -114u .. +56u)
    ctx.beginPath();
    ctx.moveTo(-102 * u, 56 * u);
    ctx.arc(-102 * u, 12 * u, 44 * u, Math.PI * 0.5, Math.PI * 1.42, false);
    ctx.arc(-44 * u, -42 * u, 58 * u, Math.PI * 1.02, Math.PI * 1.88, false);
    ctx.arc(46 * u, -34 * u, 50 * u, Math.PI * 1.18, Math.PI * 1.98, false);
    ctx.arc(104 * u, 14 * u, 42 * u, Math.PI * 1.56, Math.PI * 0.5, false);
    ctx.closePath();
  }

  function drawScene1Cloud(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    const floatY = Math.sin(range01(p, 0.14, 0.86) * Math.PI * 2) * 4.5 * u;

    ctx.save();
    ctx.translate(cx, cy - 8 * u + floatY + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    // 3 Vertical Synchronized Cloud Data Lanes strictly BELOW cloud (y = +82u .. +154u; 26u pure gap!)
    const laneXs = [-76, 0, 76];
    const laneDirs = [-1, 1, -1];
    const flowPhase = p * 2.2;
    for (let i = 0; i < 3; i++) {
      const lx = laneXs[i] * u;
      // Clean vertical guide rail
      ctx.strokeStyle = C.trackMuted;
      ctx.lineWidth = 3 * u;
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(lx, 84 * u);
      ctx.lineTo(lx, 150 * u);
      ctx.stroke();

      // Gliding data packet fading smoothly at top & bottom of rail
      const f = (flowPhase + i * 0.33) % 1;
      const py = laneDirs[i] < 0 ? (146 - f * 58) * u : (88 + f * 58) * u;
      const fade = Math.sin(f * Math.PI);
      ctx.save();
      ctx.globalAlpha = env.alpha * fade;
      ctx.fillStyle = i === 1 ? C.citrine : C.cerulean;
      roundedRectPath(lx - 4.5 * u, py - 10 * u, 9 * u, 20 * u, 4.5 * u);
      ctx.fill();
      ctx.restore();
    }

    // Unified Cloud Body with Clean Flat Duotone Split
    ctx.save();
    cloudSilhouettePath();
    ctx.clip();
    ctx.fillStyle = C.cerulean;
    ctx.fillRect(-165 * u, -125 * u, 165 * u, 195 * u);
    ctx.fillStyle = C.ceruleanMid;
    ctx.fillRect(0, -125 * u, 165 * u, 195 * u);
    ctx.restore();

    // Central FinOps Efficiency Lightning/Chevron Badge cleanly inside cloud center
    const boltSc = easeOutCubic(range01(p, 0.16, 0.34));
    if (boltSc > 0.01) {
      ctx.save();
      ctx.translate(0, -6 * u);
      ctx.scale(boltSc, boltSc);

      ctx.fillStyle = C.surfaceDark;
      ctx.beginPath();
      ctx.arc(0, 0, 36 * u, 0, Math.PI * 2);
      ctx.fill();

      // Sharp flat FinOps optimization bolt
      ctx.fillStyle = C.citrine;
      ctx.beginPath();
      ctx.moveTo(4 * u, -22 * u);
      ctx.lineTo(-14 * u, 2 * u);
      ctx.lineTo(-1 * u, 2 * u);
      ctx.lineTo(-5 * u, 22 * u);
      ctx.lineTo(15 * u, -3 * u);
      ctx.lineTo(2 * u, -3 * u);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    }

    ctx.restore();
  }

  // =========================================================================
  // SCENE 2 (5-10s): SAAS SERVER & MRR STACK
  // =========================================================================
  function drawScene2Servers(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    ctx.save();
    ctx.translate(cx, cy + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    // 3 Cleanly Stacked Horizontal Server Modules (296u x 66u, exact 20u air gap between modules!)
    const modW = 296 * u;
    const modH = 66 * u;
    const gap = 20 * u;
    const totalH = 3 * modH + 2 * gap;
    const topY = -totalH * 0.5;
    const wavePhase = p * Math.PI * 4;

    for (let i = 0; i < 3; i++) {
      const appear = easeOutCubic(range01(p, 0.06 + i * 0.06, 0.22 + i * 0.06));
      if (appear <= 0.01) continue;

      const my = topY + i * (modH + gap);
      const slideX = (1 - appear) * (i % 2 === 0 ? -24 : 24) * u;

      ctx.save();
      ctx.translate(slideX, 0);
      ctx.globalAlpha = env.alpha * appear;

      // Duotone Server Chassis
      ctx.save();
      roundedRectPath(-modW * 0.5, my, modW, modH, 16 * u);
      ctx.clip();
      ctx.fillStyle = C.surfaceMid;
      ctx.fillRect(-modW * 0.5, my, modW * 0.5, modH);
      ctx.fillStyle = C.surfaceDark;
      ctx.fillRect(0, my, modW * 0.5, modH);
      ctx.restore();

      ctx.strokeStyle = C.trackStroke;
      ctx.lineWidth = 2.8 * u;
      roundedRectPath(-modW * 0.5, my, modW, modH, 16 * u);
      ctx.stroke();

      // Left Status LED Pair (x = -114u & -90u, smooth sequential pulse)
      const rowMidY = my + modH * 0.5;
      const ledPulse = 0.5 + 0.5 * Math.sin(wavePhase - i * 1.4);
      ctx.fillStyle = lerpColor(C.ceruleanDeep, C.citrine, ledPulse);
      ctx.beginPath();
      ctx.arc(-114 * u, rowMidY, 7 * u, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = lerpColor(C.trackStroke, C.cerulean, 1 - ledPulse * 0.5);
      ctx.beginPath();
      ctx.arc(-88 * u, rowMidY, 5.5 * u, 0, Math.PI * 2);
      ctx.fill();

      // Right Dynamic MRR Capacity Progress Bar (x = -46u .. +118u; 36u clear gap from LEDs!)
      const barX = -46 * u;
      const barW = 164 * u;
      const barH = 12 * u;
      const load = 0.42 + 0.48 * (0.5 + 0.5 * Math.sin(wavePhase * 0.6 - i * 1.1));

      ctx.fillStyle = C.bgTop;
      roundedRectPath(barX, rowMidY - barH * 0.5, barW, barH, barH * 0.5);
      ctx.fill();

      ctx.fillStyle = i === 0 ? C.citrine : C.cerulean;
      roundedRectPath(barX, rowMidY - barH * 0.5, barW * load, barH, barH * 0.5);
      ctx.fill();

      ctx.restore();
    }

    ctx.restore();
  }

  // =========================================================================
  // SCENE 3 (10-15s): RECURRING REVENUE INFINITY LOOP (Parametric Lemniscate)
  // =========================================================================
  function lemniscatePoint(theta, scaleA) {
    const s = Math.sin(theta);
    const c = Math.cos(theta);
    const denom = 1 + s * s;
    return [
      (scaleA * c) / denom,
      (scaleA * s * c) / denom
    ];
  }

  function drawScene3Infinity(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    const floatY = Math.sin(range01(p, 0.14, 0.86) * Math.PI * 2) * 4 * u;

    ctx.save();
    ctx.translate(cx, cy + floatY + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    const scaleA = 166 * u;
    const steps = 160;

    function traceInfinity() {
      ctx.beginPath();
      for (let i = 0; i <= steps; i++) {
        const a = (i / steps) * Math.PI * 2;
        const pt = lemniscatePoint(a, scaleA);
        if (i === 0) ctx.moveTo(pt[0], pt[1]);
        else ctx.lineTo(pt[0], pt[1]);
      }
      ctx.closePath();
    }

    // Outer Structural Dark Track Ribbon
    ctx.strokeStyle = C.surfaceLight;
    ctx.lineWidth = 26 * u;
    ctx.lineJoin = 'round';
    traceInfinity();
    ctx.stroke();

    // Inner Crisp Cerulean Recurring Loop Track
    ctx.strokeStyle = C.cerulean;
    ctx.lineWidth = 11 * u;
    traceInfinity();
    ctx.stroke();

    // 3 Crisp Luminous Recurring-Revenue Packets gliding smoothly along the exact ∞ curve
    const baseTheta = p * Math.PI * 4;
    for (let k = 0; k < 3; k++) {
      const headA = baseTheta + k * ((Math.PI * 2) / 3);
      const col = k === 0 ? C.citrine : k === 1 ? C.cream : C.citrine;

      // Smooth tapered curve trail behind each packet
      ctx.strokeStyle = col;
      ctx.lineWidth = 9 * u;
      ctx.lineCap = 'round';
      ctx.beginPath();
      const trailSteps = 14;
      for (let s = 0; s <= trailSteps; s++) {
        const a = headA - (s / trailSteps) * 0.42;
        const pt = lemniscatePoint(a, scaleA);
        if (s === 0) ctx.moveTo(pt[0], pt[1]);
        else ctx.lineTo(pt[0], pt[1]);
      }
      ctx.stroke();

      // Leading Crisp Packet Head
      const headPt = lemniscatePoint(headA, scaleA);
      ctx.fillStyle = C.cream;
      ctx.beginPath();
      ctx.arc(headPt[0], headPt[1], 7.5 * u, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.restore();
  }

  // =========================================================================
  // SCENE 4 (15-20s): BUDGET OPTIMIZATION SLIDERS
  // =========================================================================
  function drawScene4Sliders(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    const floatY = Math.sin(range01(p, 0.14, 0.86) * Math.PI * 2) * 4 * u;

    ctx.save();
    ctx.translate(cx, cy + floatY + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    // Clean Rounded FinOps Control Deck Card (320u x 244u)
    const cW = 320 * u;
    const cH = 244 * u;
    ctx.fillStyle = C.surfaceMid;
    roundedRectPath(-cW * 0.5, -cH * 0.5, cW, cH, 24 * u);
    ctx.fill();

    ctx.strokeStyle = C.trackStroke;
    ctx.lineWidth = 3 * u;
    roundedRectPath(-cW * 0.5, -cH * 0.5, cW, cH, 24 * u);
    ctx.stroke();

    // 3 Synchronized Horizontal Budget Optimization Tracks (exact 64u vertical spacing!)
    const trackW = 236 * u;
    const trackH = 12 * u;
    const trackX = -trackW * 0.5;
    const sliderYs = [-64, 0, 64];
    const sliderSpecs = [
      { start: 0.22, mid: 0.78, end: 0.72, col: C.cerulean },
      { start: 0.76, mid: 0.30, end: 0.44, col: C.citrine },
      { start: 0.34, mid: 0.84, end: 0.80, col: C.cerulean }
    ];

    const move1 = easeInOutCubic(range01(p, 0.14, 0.48));
    const move2 = easeInOutCubic(range01(p, 0.52, 0.78));

    for (let i = 0; i < 3; i++) {
      const sy = sliderYs[i] * u;
      const sp = sliderSpecs[i];
      const val = sp.start + (sp.mid - sp.start) * move1 + (sp.end - sp.mid) * move2;
      const fillW = Math.max(trackH, trackW * val);
      const knobX = trackX + trackW * val;

      // Track background
      ctx.fillStyle = C.bgTop;
      roundedRectPath(trackX, sy - trackH * 0.5, trackW, trackH, trackH * 0.5);
      ctx.fill();

      // Active filled portion
      ctx.fillStyle = sp.col;
      roundedRectPath(trackX, sy - trackH * 0.5, fillW, trackH, trackH * 0.5);
      ctx.fill();

      // Crisp Layered Flat Slider Knob
      ctx.fillStyle = C.surfaceDark;
      ctx.beginPath();
      ctx.arc(knobX, sy, 21 * u, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = C.cream;
      ctx.beginPath();
      ctx.arc(knobX, sy, 16 * u, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = sp.col;
      ctx.beginPath();
      ctx.arc(knobX, sy, 7 * u, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.restore();
  }

  // =========================================================================
  // RENDER PIPELINE
  // =========================================================================
  ctx.save();
  drawBackground();
  drawSideTelemetry();

  if (currentScene === 0) {
    drawScene1Cloud(sceneProgress);
  } else if (currentScene === 1) {
    drawScene2Servers(sceneProgress);
  } else if (currentScene === 2) {
    drawScene3Infinity(sceneProgress);
  } else {
    drawScene4Sliders(sceneProgress);
  }
  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const u = minSide / 1000;
  const cx = width * 0.5;
  const cy = height * 0.5;
  const loopPhase = (loopT / duration) * Math.PI * 2;
  const heroZoom = 1.22;

  // Color Palette — Carbon Steel Black + Neon Acid Lime & Electric Cobalt
  const C = {
    bgTop: '#080C10',
    bgMid: '#0D141C',
    bgBot: '#141D26',
    gridMark: 'rgba(163, 255, 18, 0.06)',
    trackMuted: '#1B2735',
    trackStroke: '#2E435C',
    surfaceDark: '#0D151E',
    surfaceMid: '#152230',
    surfaceLight: '#213448',
    lime: '#A3FF12',
    limeMid: '#7DD608',
    cobalt: '#3B82F6',
    cobaltMid: '#2563EB',
    cobaltDeep: '#1D4ED8',
    silver: '#CBD5E1',
    white: '#F1F5F9'
  };

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function range01(p, start, end) {
    return clamp01((p - start) / (end - start));
  }

  function easeOutCubic(x) {
    const inv = 1 - clamp01(x);
    return 1 - inv * inv * inv;
  }

  function easeInCubic(x) {
    const v = clamp01(x);
    return v * v * v;
  }

  function easeInOutCubic(x) {
    const v = clamp01(x);
    return v < 0.5 ? 4 * v * v * v : 1 - Math.pow(-2 * v + 2, 3) / 2;
  }

  function lerpColor(hexA, hexB, f) {
    const k = clamp01(f);
    const a = parseInt(hexA.slice(1), 16);
    const b = parseInt(hexB.slice(1), 16);
    const ar = (a >> 16) & 255;
    const ag = (a >> 8) & 255;
    const ab = a & 255;
    const br = (b >> 16) & 255;
    const bg = (b >> 8) & 255;
    const bb = b & 255;
    const r = Math.round(ar + (br - ar) * k);
    const g = Math.round(ag + (bg - ag) * k);
    const bl = Math.round(ab + (bb - ab) * k);
    return 'rgb(' + r + ',' + g + ',' + bl + ')';
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function drawPartialPolyline(points, progress) {
    if (progress <= 0 || points.length < 2) return;
    let totalLen = 0;
    const segLens = [];
    for (let i = 0; i < points.length - 1; i++) {
      const len = Math.hypot(points[i + 1][0] - points[i][0], points[i + 1][1] - points[i][1]);
      segLens.push(len);
      totalLen += len;
    }
    let remaining = totalLen * clamp01(progress);
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 0; i < segLens.length; i++) {
      if (remaining <= 0) break;
      if (remaining >= segLens[i]) {
        ctx.lineTo(points[i + 1][0], points[i + 1][1]);
        remaining -= segLens[i];
      } else {
        const frac = remaining / segLens[i];
        ctx.lineTo(
          points[i][0] + (points[i + 1][0] - points[i][0]) * frac,
          points[i][1] + (points[i + 1][1] - points[i][1]) * frac
        );
        remaining = 0;
      }
    }
    ctx.stroke();
  }

  function drawBackground() {
    const bgGrad = ctx.createLinearGradient(0, 0, width, height);
    bgGrad.addColorStop(0, C.bgTop);
    bgGrad.addColorStop(0.5, C.bgMid);
    bgGrad.addColorStop(1, C.bgBot);
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, width, height);

    // Subtle uniform circuit micro-squares with seamless diagonal drift
    const step = 62 * u;
    const drift = (loopT / duration) * step;
    const cols = Math.ceil(width / step) + 2;
    const rows = Math.ceil(height / step) + 2;
    const startX = cx - Math.floor(cols * 0.5) * step + (drift % step) - step;
    const startY = cy - Math.floor(rows * 0.5) * step;
    const s = 2.6 * u;

    ctx.fillStyle = C.gridMark;
    for (let r = 0; r < rows; r++) {
      const py = startY + r * step;
      if (py < 24 * u || py > height - 24 * u) continue;
      for (let c = 0; c < cols; c++) {
        const px = startX + c * step;
        if (px < 24 * u || px > width - 24 * u) continue;
        ctx.fillRect(px - s * 0.5, py - s * 0.5, s, s);
      }
    }
  }

  function drawSideTelemetry() {
    const minHalfW = 580 * u;
    if (width * 0.5 < minHalfW + 80 * u) return;

    const sideOffset = Math.min(620 * u, width * 0.5 - 110 * u);
    const lx = cx - sideOffset;
    const rx = cx + sideOffset;

    const capW = 6 * u;
    const capH = 40 * u;
    const capGap = 20 * u;
    const totalH = sceneCount * capH + (sceneCount - 1) * capGap;
    const topY = cy - totalH * 0.5;

    const activeFade = Math.min(
      easeOutCubic(range01(sceneProgress, 0.0, 0.08)),
      1 - easeInCubic(range01(sceneProgress, 0.90, 1.0))
    );

    for (let i = 0; i < sceneCount; i++) {
      const y = topY + i * (capH + capGap);
      ctx.fillStyle = C.trackMuted;
      roundedRectPath(lx - capW * 0.5, y, capW, capH, capW * 0.5);
      ctx.fill();

      if (i === currentScene && activeFade > 0.01) {
        const fillFrac = easeInOutCubic(range01(sceneProgress, 0.0, 0.90));
        const fillH = Math.max(capW, capH * fillFrac);
        ctx.fillStyle = lerpColor(C.trackMuted, C.lime, activeFade);
        roundedRectPath(lx - capW * 0.5, y, capW, fillH, capW * 0.5);
        ctx.fill();
      }
    }

    const totalW = 60 * u;
    const barH = 6 * u;
    for (let i = 0; i < 4; i++) {
      const y = topY + i * (capH + capGap) + (capH - barH) * 0.5;
      const wave = 0.5 + 0.5 * Math.sin(loopPhase * 2 + i * 1.2);
      const activeW = (18 + wave * 38) * u;

      ctx.fillStyle = C.trackMuted;
      roundedRectPath(rx - totalW * 0.5, y, totalW, barH, barH * 0.5);
      ctx.fill();

      const highlight = i === currentScene ? activeFade : 0;
      ctx.fillStyle = lerpColor(C.trackStroke, i % 2 === 0 ? C.lime : C.cobalt, highlight);
      roundedRectPath(rx - totalW * 0.5, y, activeW, barH, barH * 0.5);
      ctx.fill();
    }
  }

  function getSceneEnvelope(p) {
    const enterP = range01(p, 0.0, 0.14);
    const exitP = range01(p, 0.86, 1.0);
    const enterEase = easeOutCubic(enterP);
    const exitEase = easeInCubic(exitP);
    const scale = p < 0.5 ? 0.86 + 0.14 * enterEase : 1 - 0.14 * exitEase;
    const liftY = p < 0.5 ? (1 - enterEase) * 18 * u : -exitEase * 18 * u;
    const alpha = p < 0.10
      ? easeOutCubic(range01(p, 0.0, 0.10))
      : p > 0.90
        ? 1 - easeInCubic(range01(p, 0.90, 1.0))
        : 1;
    return { scale, alpha, liftY };
  }

  // =========================================================================
  // SCENE 1 (0-5s): AI FINANCE MICROCHIP
  // =========================================================================
  function drawScene1Chip(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    const floatY = Math.sin(range01(p, 0.14, 0.86) * Math.PI * 2) * 4.5 * u;

    ctx.save();
    ctx.translate(cx, cy + floatY + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    const chipS = 180 * u;
    const half = chipS * 0.5;

    // 4 Symmetrical Pin Arrays on all 4 sides drawn cleanly BEHIND chip package
    const pinOffsets = [-54, -18, 18, 54];
    const pinWave = p * Math.PI * 4;
    for (let side = 0; side < 4; side++) {
      ctx.save();
      ctx.rotate(side * Math.PI * 0.5);
      for (let i = 0; i < pinOffsets.length; i++) {
        const ext = easeOutCubic(range01(p, 0.10 + i * 0.03, 0.26 + i * 0.03));
        const pinLen = 40 * u * ext;
        if (pinLen <= 1 * u) continue;
        const pulse = 0.5 + 0.5 * Math.sin(pinWave - side * 1.1 - i * 0.7);
        ctx.fillStyle = lerpColor(C.cobalt, C.lime, pulse * 0.85);
        roundedRectPath(pinOffsets[i] * u - 5 * u, -half - pinLen, 10 * u, pinLen + 8 * u, 4 * u);
        ctx.fill();
      }
      ctx.restore();
    }

    // Main Processor Package (flat duotone split)
    ctx.save();
    roundedRectPath(-half, -half, chipS, chipS, 24 * u);
    ctx.clip();
    ctx.fillStyle = C.surfaceMid;
    ctx.fillRect(-half, -half, chipS, chipS);
    ctx.fillStyle = C.surfaceDark;
    ctx.beginPath();
    ctx.moveTo(half, -half);
    ctx.lineTo(half, half);
    ctx.lineTo(-half, half);
    ctx.closePath();
    ctx.fill();
    ctx.restore();

    ctx.strokeStyle = C.cobalt;
    ctx.lineWidth = 4 * u;
    roundedRectPath(-half, -half, chipS, chipS, 24 * u);
    ctx.stroke();

    // Inner Recessed Die Chamber (118u x 118u)
    const inS = 118 * u;
    ctx.fillStyle = C.bgTop;
    roundedRectPath(-inS * 0.5, -inS * 0.5, inS, inS, 14 * u);
    ctx.fill();

    ctx.strokeStyle = C.trackStroke;
    ctx.lineWidth = 2.2 * u;
    roundedRectPath(-inS * 0.5, -inS * 0.5, inS, inS, 14 * u);
    ctx.stroke();

    // 4 Corner Micro-Pads cleanly inside die chamber
    const padOff = 38 * u;
    for (let sx = -1; sx <= 1; sx += 2) {
      for (let sy = -1; sy <= 1; sy += 2) {
        ctx.fillStyle = C.cobalt;
        roundedRectPath(sx * padOff - 5 * u, sy * padOff - 5 * u, 10 * u, 10 * u, 3 * u);
        ctx.fill();
      }
    }

    // Pulsing Central AI Core Square (48u x 48u)
    const corePulse = 1 + 0.07 * Math.sin(p * Math.PI * 6);
    const coreS = 48 * u * corePulse;
    ctx.fillStyle = C.lime;
    roundedRectPath(-coreS * 0.5, -coreS * 0.5, coreS, coreS, 10 * u);
    ctx.fill();

    ctx.fillStyle = C.surfaceDark;
    roundedRectPath(-coreS * 0.24, -coreS * 0.24, coreS * 0.48, coreS * 0.48, 4 * u);
    ctx.fill();

    ctx.restore();
  }

  // =========================================================================
  // SCENE 2 (5-10s): MARKET DATA MAGNIFIER
  // =========================================================================
  function drawScene2Magnifier(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    const floatY = Math.sin(range01(p, 0.14, 0.86) * Math.PI * 2) * 4.5 * u;

    ctx.save();
    ctx.translate(cx, cy + floatY + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    const lensX = -26 * u;
    const lensY = -26 * u;
    const outerR = 128 * u;
    const innerR = 108 * u;

    // Angled Handle drawn cleanly BEHIND lens bezel (+45 deg down-right)
    ctx.save();
    ctx.translate(lensX, lensY);
    ctx.rotate(Math.PI * 0.25);
    ctx.fillStyle = C.cobalt;
    roundedRectPath(112 * u, -16 * u, 108 * u, 32 * u, 16 * u);
    ctx.fill();
    // Clean accent grip ring on handle
    ctx.fillStyle = C.lime;
    roundedRectPath(136 * u, -16 * u, 16 * u, 32 * u, 2 * u);
    ctx.fill();
    ctx.restore();

    // Lens outer housing
    ctx.fillStyle = C.silver;
    ctx.beginPath();
    ctx.arc(lensX, lensY, outerR, 0, Math.PI * 2);
    ctx.fill();

    // Inner dark glass scope clipped strictly to innerR
    ctx.save();
    ctx.beginPath();
    ctx.arc(lensX, lensY, innerR, 0, Math.PI * 2);
    ctx.clip();

    ctx.fillStyle = C.surfaceDark;
    ctx.fillRect(lensX - innerR, lensY - innerR, innerR * 2, innerR * 2);

    // Subtle internal grid
    ctx.strokeStyle = 'rgba(59, 130, 246, 0.18)';
    ctx.lineWidth = 1.4 * u;
    for (let g = -72; g <= 72; g += 36) {
      ctx.beginPath();
      ctx.moveTo(lensX + g * u, lensY - innerR);
      ctx.lineTo(lensX + g * u, lensY + innerR);
      ctx.moveTo(lensX - innerR, lensY + g * u);
      ctx.lineTo(lensX + innerR, lensY + g * u);
      ctx.stroke();
    }

    // Animated Financial Signal Waveform strictly inside lens
    const waveShift = p * Math.PI * 3;
    const waveReveal = easeOutCubic(range01(p, 0.10, 0.36));
    const wavePts = [];
    const steps = 44;
    for (let i = 0; i <= steps; i++) {
      const f = i / steps;
      const wx = lensX - 96 * u + f * 192 * u;
      const wy = lensY + (Math.sin(f * Math.PI * 2.5 - waveShift) * 28 + Math.cos(f * Math.PI * 5 - waveShift) * 10) * u;
      wavePts.push([wx, wy]);
    }

    ctx.strokeStyle = C.cobalt;
    ctx.lineWidth = 5 * u;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    drawPartialPolyline(wavePts, waveReveal);

    // Highlighted live target point smoothly riding the waveform
    const targetF = 0.28 + 0.44 * easeInOutCubic(range01(p, 0.24, 0.78));
    const tx = lensX - 96 * u + targetF * 192 * u;
    const ty = lensY + (Math.sin(targetF * Math.PI * 2.5 - waveShift) * 28 + Math.cos(targetF * Math.PI * 5 - waveShift) * 10) * u;

    // Reticle lock-on indicator around tracked data point
    ctx.strokeStyle = C.lime;
    ctx.lineWidth = 2.6 * u;
    ctx.beginPath();
    ctx.arc(tx, ty, 16 * u, 0, Math.PI * 2);
    ctx.stroke();

    ctx.fillStyle = C.lime;
    ctx.beginPath();
    ctx.arc(tx, ty, 6 * u, 0, Math.PI * 2);
    ctx.fill();

    ctx.restore();

    // Crisp inner rim highlight
    ctx.strokeStyle = C.cobalt;
    ctx.lineWidth = 4 * u;
    ctx.beginPath();
    ctx.arc(lensX, lensY, innerR, 0, Math.PI * 2);
    ctx.stroke();

    ctx.restore();
  }

  // =========================================================================
  // SCENE 3 (10-15s): SYNCHRONIZED AUTOMATION GEARS (Mathematically Meshed!)
  // =========================================================================
  function drawGear(gx, gy, teeth, rRoot, rTip, rHole, angle, bodyCol, rimCol) {
    ctx.save();
    ctx.translate(gx, gy);
    ctx.rotate(angle);

    const step = (Math.PI * 2) / teeth;
    ctx.fillStyle = bodyCol;
    ctx.beginPath();
    for (let i = 0; i < teeth; i++) {
      const a0 = i * step;
      const a1 = a0 + step * 0.20;
      const a2 = a0 + step * 0.30;
      const a3 = a0 + step * 0.56;
      const a4 = a0 + step * 0.66;
      if (i === 0) ctx.moveTo(Math.cos(a0) * rRoot, Math.sin(a0) * rRoot);
      else ctx.lineTo(Math.cos(a0) * rRoot, Math.sin(a0) * rRoot);
      ctx.lineTo(Math.cos(a1) * rRoot, Math.sin(a1) * rRoot);
      ctx.lineTo(Math.cos(a2) * rTip, Math.sin(a2) * rTip);
      ctx.lineTo(Math.cos(a3) * rTip, Math.sin(a3) * rTip);
      ctx.lineTo(Math.cos(a4) * rRoot, Math.sin(a4) * rRoot);
    }
    ctx.closePath();
    ctx.fill();

    // Inner precision recess ring
    ctx.fillStyle = C.surfaceDark;
    ctx.beginPath();
    ctx.arc(0, 0, rRoot * 0.72, 0, Math.PI * 2);
    ctx.fill();

    // 4 Clean Inner Spokes
    ctx.strokeStyle = bodyCol;
    ctx.lineWidth = Math.max(8 * u, rRoot * 0.14);
    for (let s = 0; s < 4; s++) {
      const sa = s * Math.PI * 0.5;
      ctx.beginPath();
      ctx.moveTo(Math.cos(sa) * rHole, Math.sin(sa) * rHole);
      ctx.lineTo(Math.cos(sa) * rRoot * 0.74, Math.sin(sa) * rRoot * 0.74);
      ctx.stroke();
    }

    // Center hub
    ctx.fillStyle = rimCol;
    ctx.beginPath();
    ctx.arc(0, 0, rHole, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = C.surfaceDark;
    ctx.beginPath();
    ctx.arc(0, 0, rHole * 0.48, 0, Math.PI * 2);
    ctx.fill();

    ctx.restore();
  }

  function drawScene3Gears(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    ctx.save();
    ctx.translate(cx, cy + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    // Stepped smooth mechanical torque rotation
    const step1 = easeInOutCubic(range01(p, 0.12, 0.44));
    const step2 = easeInOutCubic(range01(p, 0.50, 0.82));
    const theta1 = (step1 + step2) * (Math.PI * 0.5);

    // Exact non-overlapping meshed geometry:
    // Gear 1: N1 = 12, rRoot = 86u, rTip = 110u, pitchR = 98u
    // Gear 2: N2 = 8, rRoot = 54u, rTip = 78u, pitchR = 66u
    // Center distance = 98 + 66 + 6 = 170u along angle -30 deg
    // Check max tip + opposite root: 110 + 54 = 164u < 170u (6u pure clearance!)
    const g1x = -56 * u;
    const g1y = 26 * u;
    const linkAng = (-30 * Math.PI) / 180;
    const dist = 170 * u;
    const g2x = g1x + Math.cos(linkAng) * dist;
    const g2y = g1y + Math.sin(linkAng) * dist;

    // Exact phase alignment along linkAng so Gear 1 tooth enters Gear 2 valley cleanly
    const ratio = 12 / 8;
    const theta2 = linkAng + Math.PI - (theta1 - linkAng) * ratio + Math.PI / 8;

    drawGear(g1x, g1y, 12, 86 * u, 110 * u, 30 * u, theta1, C.cobalt, C.white);
    drawGear(g2x, g2y, 8, 54 * u, 78 * u, 22 * u, theta2, C.lime, C.surfaceMid);

    ctx.restore();
  }

  // =========================================================================
  // SCENE 4 (15-20s): SMART FINANCIAL INSIGHT BULB
  // =========================================================================
  function drawScene4Bulb(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    const floatY = Math.sin(range01(p, 0.14, 0.86) * Math.PI * 2) * 5 * u;

    ctx.save();
    ctx.translate(cx, cy + 8 * u + floatY + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    const domeCy = -40 * u;
    const domeR = 98 * u;

    // 7 Symmetrical Upper Insight Rays cleanly outside glass dome (r = 126u .. 154u)
    const rayIn = easeOutCubic(range01(p, 0.36, 0.54));
    const rayOut = 1 - easeInCubic(range01(p, 0.74, 0.86));
    const rayAmt = Math.min(rayIn, rayOut);
    if (rayAmt > 0.01) {
      ctx.strokeStyle = C.lime;
      ctx.lineWidth = 4.2 * u;
      ctx.lineCap = 'round';
      const deg = Math.PI / 180;
      const angles = [-165, -140, -115, -90, -65, -40, -15];
      for (let i = 0; i < angles.length; i++) {
        const a = angles[i] * deg;
        const r0 = (126 + (1 - rayAmt) * 8) * u;
        const r1 = r0 + 22 * u * rayAmt;
        ctx.beginPath();
        ctx.moveTo(Math.cos(a) * r0, domeCy + Math.sin(a) * r0);
        ctx.lineTo(Math.cos(a) * r1, domeCy + Math.sin(a) * r1);
        ctx.stroke();
      }
    }

    // Bulb Glass Silhouette (flat duotone split)
    ctx.save();
    ctx.beginPath();
    ctx.arc(0, domeCy, domeR, Math.PI * 0.72, Math.PI * 2.28, false);
    ctx.quadraticCurveTo(54 * u, 42 * u, 48 * u, 76 * u);
    ctx.lineTo(-48 * u, 76 * u);
    ctx.quadraticCurveTo(-54 * u, 42 * u, Math.cos(Math.PI * 0.72) * domeR, domeCy + Math.sin(Math.PI * 0.72) * domeR);
    ctx.closePath();
    ctx.clip();

    ctx.fillStyle = C.surfaceMid;
    ctx.fillRect(-110 * u, -150 * u, 110 * u, 240 * u);
    ctx.fillStyle = C.surfaceDark;
    ctx.fillRect(0, -150 * u, 110 * u, 240 * u);
    ctx.restore();

    // Crisp outer glass contour
    ctx.strokeStyle = C.cobalt;
    ctx.lineWidth = 5 * u;
    ctx.lineJoin = 'round';
    ctx.beginPath();
    ctx.arc(0, domeCy, domeR, Math.PI * 0.72, Math.PI * 2.28, false);
    ctx.quadraticCurveTo(54 * u, 42 * u, 48 * u, 76 * u);
    ctx.lineTo(-48 * u, 76 * u);
    ctx.quadraticCurveTo(-54 * u, 42 * u, Math.cos(Math.PI * 0.72) * domeR, domeCy + Math.sin(Math.PI * 0.72) * domeR);
    ctx.closePath();
    ctx.stroke();

    // Financial Growth Zig-Zag Filament illuminating cleanly inside bulb
    const filP = easeOutCubic(range01(p, 0.16, 0.44));
    const filPts = [
      [-46 * u, -10 * u],
      [-16 * u, -42 * u],
      [10 * u, -20 * u],
      [44 * u, -62 * u]
    ];
    ctx.strokeStyle = C.lime;
    ctx.lineWidth = 7 * u;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    drawPartialPolyline(filPts, filP);

    // Arrowhead at filament peak
    const tipP = easeOutCubic(range01(p, 0.38, 0.48));
    if (tipP > 0.01) {
      const tipX = filPts[3][0];
      const tipY = filPts[3][1];
      const ang = Math.atan2(filPts[3][1] - filPts[2][1], filPts[3][0] - filPts[2][0]);
      const hs = 14 * u * tipP;
      ctx.save();
      ctx.translate(tipX, tipY);
      ctx.rotate(ang);
      ctx.strokeStyle = C.lime;
      ctx.lineWidth = 7 * u;
      ctx.beginPath();
      ctx.moveTo(-hs, -hs * 0.65);
      ctx.lineTo(0, 0);
      ctx.lineTo(-hs, hs * 0.65);
      ctx.stroke();
      ctx.restore();
    }

    // 3 Cleanly Separated Screw-Base Pills below bulb neck (8u vertical gap each!)
    const baseBars = [
      { y: 88, w: 86, col: C.silver },
      { y: 108, w: 74, col: C.cobalt },
      { y: 128, w: 48, col: C.silver }
    ];
    for (let i = 0; i < baseBars.length; i++) {
      const bb = baseBars[i];
      ctx.fillStyle = bb.col;
      roundedRectPath(-bb.w * 0.5 * u, bb.y * u, bb.w * u, 12 * u, 6 * u);
      ctx.fill();
    }

    ctx.restore();
  }

  // =========================================================================
  // RENDER PIPELINE
  // =========================================================================
  ctx.save();
  drawBackground();
  drawSideTelemetry();

  if (currentScene === 0) {
    drawScene1Chip(sceneProgress);
  } else if (currentScene === 1) {
    drawScene2Magnifier(sceneProgress);
  } else if (currentScene === 2) {
    drawScene3Gears(sceneProgress);
  } else {
    drawScene4Bulb(sceneProgress);
  }
  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const u = minSide / 1000;
  const cx = width * 0.5;
  const cy = height * 0.5;
  const loopPhase = (loopT / duration) * Math.PI * 2;
  const heroZoom = 1.22;

  // Color Palette — Abyssal Deep Teal + Luminous Aqua Cyan & Arctic Sky
  const C = {
    bgTop: '#041418',
    bgMid: '#072129',
    bgBot: '#0B2F3A',
    gridMark: 'rgba(125, 226, 232, 0.065)',
    trackMuted: '#123A47',
    trackStroke: '#215B6E',
    surfaceDark: '#082028',
    surfaceMid: '#0F3340',
    surfaceLight: '#174859',
    aqua: '#06E5D8',
    aquaMid: '#04B8B0',
    aquaDeep: '#038A85',
    sky: '#60A5FA',
    skyMid: '#3B82F6',
    ice: '#E6FCFF',
    iceSoft: '#A5F3FC'
  };

  // Smooth, Controlled Math & Color Utilities
  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function range01(p, start, end) {
    return clamp01((p - start) / (end - start));
  }

  function easeOutCubic(x) {
    const inv = 1 - clamp01(x);
    return 1 - inv * inv * inv;
  }

  function easeInCubic(x) {
    const v = clamp01(x);
    return v * v * v;
  }

  function easeInOutCubic(x) {
    const v = clamp01(x);
    return v < 0.5 ? 4 * v * v * v : 1 - Math.pow(-2 * v + 2, 3) / 2;
  }

  function easeOutSoftBack(x) {
    const v = clamp01(x);
    const c1 = 0.78;
    const c3 = c1 + 1;
    return 1 + c3 * Math.pow(v - 1, 3) + c1 * Math.pow(v - 1, 2);
  }

  function lerpColor(hexA, hexB, f) {
    const k = clamp01(f);
    const a = parseInt(hexA.slice(1), 16);
    const b = parseInt(hexB.slice(1), 16);
    const ar = (a >> 16) & 255;
    const ag = (a >> 8) & 255;
    const ab = a & 255;
    const br = (b >> 16) & 255;
    const bg = (b >> 8) & 255;
    const bb = b & 255;
    const r = Math.round(ar + (br - ar) * k);
    const g = Math.round(ag + (bg - ag) * k);
    const bl = Math.round(ab + (bb - ab) * k);
    return 'rgb(' + r + ',' + g + ',' + bl + ')';
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function drawBackground() {
    // Pure Modern Dark Aesthetic Linear Gradient — ZERO background glow
    const bgGrad = ctx.createLinearGradient(0, 0, width, height);
    bgGrad.addColorStop(0, C.bgTop);
    bgGrad.addColorStop(0.5, C.bgMid);
    bgGrad.addColorStop(1, C.bgBot);
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, width, height);

    // Subtle uniform precision latitude micro-dashes with seamless 1-cell rightward drift
    const stepX = 68 * u;
    const stepY = 56 * u;
    const driftX = (loopT / duration) * stepX;
    const cols = Math.ceil(width / stepX) + 2;
    const rows = Math.ceil(height / stepY) + 2;
    const startX = cx - Math.floor(cols * 0.5) * stepX + (driftX % stepX) - stepX;
    const startY = cy - Math.floor(rows * 0.5) * stepY;
    const halfDash = 3.2 * u;

    ctx.strokeStyle = C.gridMark;
    ctx.lineWidth = 1.3 * u;
    ctx.lineCap = 'round';
    ctx.beginPath();
    for (let r = 0; r < rows; r++) {
      const py = startY + r * stepY;
      if (py < 26 * u || py > height - 26 * u) continue;
      for (let c = 0; c < cols; c++) {
        const px = startX + c * stepX;
        if (px < 26 * u || px > width - 26 * u) continue;
        ctx.moveTo(px - halfDash, py);
        ctx.lineTo(px + halfDash, py);
      }
    }
    ctx.stroke();
  }

  function drawSideTelemetry() {
    const minHalfW = 580 * u;
    if (width * 0.5 < minHalfW + 80 * u) return;

    const sideOffset = Math.min(620 * u, width * 0.5 - 110 * u);
    const lx = cx - sideOffset;
    const rx = cx + sideOffset;

    const capW = 6 * u;
    const capH = 40 * u;
    const capGap = 20 * u;
    const totalH = sceneCount * capH + (sceneCount - 1) * capGap;
    const topY = cy - totalH * 0.5;

    const activeFade = Math.min(
      easeOutCubic(range01(sceneProgress, 0.0, 0.08)),
      1 - easeInCubic(range01(sceneProgress, 0.90, 1.0))
    );

    // Left column: 4 Scene Stage Progress Capsules
    for (let i = 0; i < sceneCount; i++) {
      const y = topY + i * (capH + capGap);
      ctx.fillStyle = C.trackMuted;
      roundedRectPath(lx - capW * 0.5, y, capW, capH, capW * 0.5);
      ctx.fill();

      if (i === currentScene && activeFade > 0.01) {
        const fillFrac = easeInOutCubic(range01(sceneProgress, 0.0, 0.90));
        const fillH = Math.max(capW, capH * fillFrac);
        ctx.fillStyle = lerpColor(C.trackMuted, C.aqua, activeFade);
        roundedRectPath(lx - capW * 0.5, y, capW, fillH, capW * 0.5);
        ctx.fill();
      }
    }

    // Right column: 4 Symmetrical Cross-Border Flow Sliders
    const trackW = 60 * u;
    const trackH = 4 * u;
    const nodeW = 14 * u;
    const nodeH = 7 * u;
    for (let i = 0; i < 4; i++) {
      const rowY = topY + i * (capH + capGap) + capH * 0.5;
      const x0 = rx - trackW * 0.5;
      const slide = 0.5 + 0.5 * Math.sin(loopPhase * 2 + i * 1.15);
      const nodeX = x0 + slide * (trackW - nodeW);
      const highlight = i === currentScene ? activeFade : 0;

      ctx.fillStyle = C.trackMuted;
      roundedRectPath(x0, rowY - trackH * 0.5, trackW, trackH, trackH * 0.5);
      ctx.fill();

      ctx.fillStyle = lerpColor(C.trackStroke, i % 2 === 0 ? C.aqua : C.sky, 0.35 + 0.65 * highlight);
      roundedRectPath(nodeX, rowY - nodeH * 0.5, nodeW, nodeH, nodeH * 0.5);
      ctx.fill();
    }
  }

  function getSceneEnvelope(p) {
    const enterP = range01(p, 0.0, 0.14);
    const exitP = range01(p, 0.86, 1.0);
    const enterEase = easeOutCubic(enterP);
    const exitEase = easeInCubic(exitP);
    const scale = p < 0.5 ? 0.86 + 0.14 * enterEase : 1 - 0.14 * exitEase;
    const liftY = p < 0.5 ? (1 - enterEase) * 18 * u : -exitEase * 18 * u;
    const alpha = p < 0.10
      ? easeOutCubic(range01(p, 0.0, 0.10))
      : p > 0.90
        ? 1 - easeInCubic(range01(p, 0.90, 1.0))
        : 1;
    return { scale, alpha, liftY };
  }

  // =========================================================================
  // SCENE 1 (0-5s): 2D MERIDIAN GLOBE (Pure Globe Icon, ZERO Outer Orbit Ring)
  // =========================================================================
  function drawScene1Globe(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    const floatY = Math.sin(range01(p, 0.14, 0.86) * Math.PI * 2) * 5 * u;

    ctx.save();
    ctx.translate(cx, cy + floatY + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    const globeR = 178 * u;

    // Globe sphere body clipped cleanly inside globeR
    ctx.save();
    ctx.beginPath();
    ctx.arc(0, 0, globeR, 0, Math.PI * 2);
    ctx.clip();

    // Flat duotone deep ocean fill
    ctx.fillStyle = C.surfaceMid;
    ctx.fillRect(-globeR, -globeR, globeR, globeR * 2);
    ctx.fillStyle = C.surfaceDark;
    ctx.fillRect(0, -globeR, globeR, globeR * 2);

    // 3 Crisp Horizontal Latitude Lines
    const latYs = [-86 * u, 0, 86 * u];
    for (let i = 0; i < latYs.length; i++) {
      ctx.strokeStyle = i === 1 ? '#29728A' : '#1A4E60';
      ctx.lineWidth = (i === 1 ? 2.8 : 2.2) * u;
      ctx.beginPath();
      ctx.moveTo(-globeR, latYs[i]);
      ctx.lineTo(globeR, latYs[i]);
      ctx.stroke();
    }

    // 4 Smoothly Gliding 2D Meridian Ellipses
    const rotShift = p * Math.PI * 1.5;
    ctx.lineWidth = 2.6 * u;
    for (let i = 0; i < 4; i++) {
      const phi = (rotShift + i * (Math.PI * 0.25)) % Math.PI;
      const sinP = Math.sin(phi);
      const cosP = Math.cos(phi);
      const rx = Math.abs(cosP) * globeR;
      const visibility = Math.pow(sinP, 0.45);
      ctx.save();
      ctx.globalAlpha = env.alpha * (0.35 + 0.65 * visibility);
      ctx.strokeStyle = i % 2 === 0 ? C.aqua : C.sky;
      ctx.beginPath();
      if (rx < 1.5 * u) {
        ctx.moveTo(0, -globeR);
        ctx.lineTo(0, globeR);
      } else {
        const startA = cosP >= 0 ? -Math.PI * 0.5 : Math.PI * 0.5;
        const endA = cosP >= 0 ? Math.PI * 0.5 : Math.PI * 1.5;
        ctx.ellipse(0, 0, rx, globeR, 0, startA, endA);
      }
      ctx.stroke();
      ctx.restore();
    }

    // 3 Crisp Market Hub Nodes gliding smoothly along the 3 latitude tracks
    const nodeSpecs = [
      { y: -86, phaseOff: 0.15, col: C.aqua },
      { y: 0, phaseOff: 0.50, col: C.ice },
      { y: 86, phaseOff: 0.82, col: C.sky }
    ];
    for (let i = 0; i < nodeSpecs.length; i++) {
      const ns = nodeSpecs[i];
      const ny = ns.y * u;
      const maxX = Math.sqrt(Math.max(0, globeR * globeR - ny * ny)) - 28 * u;
      const ang = (p * 1.2 + ns.phaseOff) * Math.PI;
      const nx = Math.cos(ang) * maxX;
      const edgeFade = easeOutCubic(range01(Math.abs(Math.sin(ang)), 0.05, 0.35));
      if (edgeFade <= 0.02) continue;

      ctx.save();
      ctx.globalAlpha = env.alpha * edgeFade;
      ctx.fillStyle = C.surfaceDark;
      ctx.beginPath();
      ctx.arc(nx, ny, 11 * u, 0, Math.PI * 2);
      ctx.fill();

      ctx.strokeStyle = ns.col;
      ctx.lineWidth = 2.6 * u;
      ctx.beginPath();
      ctx.arc(nx, ny, 10 * u, 0, Math.PI * 2);
      ctx.stroke();

      ctx.fillStyle = C.ice;
      ctx.beginPath();
      ctx.arc(nx, ny, 4.2 * u, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }

    ctx.restore();

    // Outer crisp globe perimeter ring
    ctx.strokeStyle = C.aqua;
    ctx.lineWidth = 5.5 * u;
    ctx.beginPath();
    ctx.arc(0, 0, globeR, 0, Math.PI * 2);
    ctx.stroke();

    ctx.restore();
  }

  // =========================================================================
  // SCENE 2 (5-10s): CIRCULAR CURRENCY EXCHANGE (FX Flow)
  // =========================================================================
  function drawCurrencyGlyph(index, color) {
    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth = 8.5 * u;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    if (index === 0) {
      // Geometric Dollar ($)
      ctx.beginPath();
      ctx.moveTo(0, -42 * u);
      ctx.lineTo(0, 42 * u);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(20 * u, -20 * u);
      ctx.bezierCurveTo(18 * u, -34 * u, -20 * u, -34 * u, -20 * u, -15 * u);
      ctx.bezierCurveTo(-20 * u, 0, 21 * u, 0, 21 * u, 16 * u);
      ctx.bezierCurveTo(21 * u, 34 * u, -18 * u, 34 * u, -21 * u, 19 * u);
      ctx.stroke();
    } else if (index === 1) {
      // Geometric Euro (€)
      ctx.beginPath();
      ctx.arc(8 * u, 0, 31 * u, 0.24 * Math.PI, 1.76 * Math.PI, false);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(-32 * u, -9 * u);
      ctx.lineTo(12 * u, -9 * u);
      ctx.moveTo(-32 * u, 9 * u);
      ctx.lineTo(12 * u, 9 * u);
      ctx.stroke();
    } else if (index === 2) {
      // Geometric Pound (£)
      ctx.beginPath();
      ctx.arc(4 * u, -16 * u, 17 * u, Math.PI, -0.15 * Math.PI, false);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(-13 * u, -16 * u);
      ctx.lineTo(-13 * u, 31 * u);
      ctx.moveTo(-22 * u, 31 * u);
      ctx.lineTo(24 * u, 31 * u);
      ctx.moveTo(-24 * u, 5 * u);
      ctx.lineTo(11 * u, 5 * u);
      ctx.stroke();
    } else {
      // Geometric Yen (¥)
      ctx.beginPath();
      ctx.moveTo(-24 * u, -34 * u);
      ctx.lineTo(0, -2 * u);
      ctx.lineTo(24 * u, -34 * u);
      ctx.moveTo(0, -2 * u);
      ctx.lineTo(0, 36 * u);
      ctx.moveTo(-20 * u, 9 * u);
      ctx.lineTo(20 * u, 9 * u);
      ctx.moveTo(-20 * u, 22 * u);
      ctx.lineTo(20 * u, 22 * u);
      ctx.stroke();
    }
    ctx.restore();
  }

  function drawCurvedArrow(radius, startA, endA, color) {
    ctx.strokeStyle = color;
    ctx.lineWidth = 13 * u;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.arc(0, 0, radius, startA, endA, false);
    ctx.stroke();

    const tipX = Math.cos(endA) * radius;
    const tipY = Math.sin(endA) * radius;
    const tangentA = endA + Math.PI * 0.5;

    ctx.save();
    ctx.translate(tipX, tipY);
    ctx.rotate(tangentA);
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(22 * u, 0);
    ctx.lineTo(-10 * u, -18 * u);
    ctx.lineTo(-10 * u, 18 * u);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  function drawScene2FX(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    ctx.save();
    ctx.translate(cx, cy + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    const step1 = easeInOutCubic(range01(p, 0.20, 0.34));
    const step2 = easeInOutCubic(range01(p, 0.42, 0.56));
    const step3 = easeInOutCubic(range01(p, 0.64, 0.78));
    const arrowRot = (step1 + step2 + step3) * (Math.PI * 0.5);

    ctx.save();
    ctx.rotate(arrowRot - Math.PI * 0.68);
    const sweep = (118 * Math.PI) / 180;
    drawCurvedArrow(166 * u, 0, sweep, C.aqua);
    drawCurvedArrow(166 * u, Math.PI, Math.PI + sweep, C.sky);
    ctx.restore();

    ctx.fillStyle = C.surfaceMid;
    ctx.beginPath();
    ctx.arc(0, 0, 104 * u, 0, Math.PI * 2);
    ctx.fill();

    ctx.strokeStyle = C.sky;
    ctx.lineWidth = 4 * u;
    ctx.beginPath();
    ctx.arc(0, 0, 104 * u, 0, Math.PI * 2);
    ctx.stroke();

    ctx.fillStyle = C.surfaceDark;
    ctx.beginPath();
    ctx.arc(0, 0, 86 * u, 0, Math.PI * 2);
    ctx.fill();

    ctx.save();
    ctx.beginPath();
    ctx.arc(0, 0, 82 * u, 0, Math.PI * 2);
    ctx.clip();

    const slideDist = 184 * u;
    let idxA = 0;
    let idxB = 0;
    let frac = 0;

    if (p < 0.34) {
      idxA = 0;
      idxB = 1;
      frac = step1;
    } else if (p < 0.56) {
      idxA = 1;
      idxB = 2;
      frac = step2;
    } else {
      idxA = 2;
      idxB = 3;
      frac = step3;
    }

    if (frac <= 0.001) {
      drawCurrencyGlyph(idxA, idxA % 2 === 0 ? C.ice : C.aqua);
    } else if (frac >= 0.999) {
      drawCurrencyGlyph(idxB, idxB % 2 === 0 ? C.ice : C.aqua);
    } else {
      const outA = 1 - easeInCubic(range01(frac, 0.0, 0.52));
      const inB = easeOutCubic(range01(frac, 0.48, 1.0));

      if (outA > 0.01) {
        ctx.save();
        ctx.globalAlpha = env.alpha * outA;
        ctx.translate(0, -frac * slideDist);
        drawCurrencyGlyph(idxA, idxA % 2 === 0 ? C.ice : C.aqua);
        ctx.restore();
      }
      if (inB > 0.01) {
        ctx.save();
        ctx.globalAlpha = env.alpha * inB;
        ctx.translate(0, (1 - frac) * slideDist);
        drawCurrencyGlyph(idxB, idxB % 2 === 0 ? C.ice : C.aqua);
        ctx.restore();
      }
    }

    ctx.restore();
    ctx.restore();
  }

  // =========================================================================
  // SCENE 3 (10-15s): GLOBAL TRADE COMPASS
  // =========================================================================
  function drawScene3Compass(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    ctx.save();
    ctx.translate(cx, cy + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    ctx.fillStyle = C.surfaceMid;
    ctx.beginPath();
    ctx.arc(0, 0, 192 * u, 0, Math.PI * 2);
    ctx.fill();

    ctx.strokeStyle = C.aqua;
    ctx.lineWidth = 4.5 * u;
    ctx.beginPath();
    ctx.arc(0, 0, 192 * u, 0, Math.PI * 2);
    ctx.stroke();

    ctx.fillStyle = C.surfaceDark;
    ctx.beginPath();
    ctx.arc(0, 0, 170 * u, 0, Math.PI * 2);
    ctx.fill();

    ctx.strokeStyle = '#184A5C';
    ctx.lineWidth = 2 * u;
    ctx.beginPath();
    ctx.arc(0, 0, 132 * u, 0, Math.PI * 2);
    ctx.stroke();

    const routeP = easeOutCubic(range01(p, 0.50, 0.72));
    if (routeP > 0.01) {
      const span = ((48 * Math.PI) / 180) * routeP;
      ctx.strokeStyle = C.aqua;
      ctx.lineWidth = 4 * u;
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.arc(0, 0, 132 * u, -Math.PI * 0.5 - span, -Math.PI * 0.5 + span);
      ctx.stroke();
    }

    for (let i = 0; i < 4; i++) {
      const a = i * (Math.PI * 0.5) - Math.PI * 0.5;
      ctx.save();
      ctx.rotate(a);
      ctx.fillStyle = i === 0 ? C.aqua : C.sky;
      ctx.beginPath();
      ctx.moveTo(164 * u, 0);
      ctx.lineTo(148 * u, -8 * u);
      ctx.lineTo(148 * u, 8 * u);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    }

    for (let i = 0; i < 12; i++) {
      if (i % 3 === 0) continue;
      const a = (i * Math.PI) / 6;
      ctx.fillStyle = C.trackStroke;
      ctx.beginPath();
      ctx.arc(Math.cos(a) * 154 * u, Math.sin(a) * 154 * u, 3.2 * u, 0, Math.PI * 2);
      ctx.fill();
    }

    const swing1 = easeInOutCubic(range01(p, 0.14, 0.40));
    const swing2 = easeInOutCubic(range01(p, 0.40, 0.62));
    const deg = Math.PI / 180;
    const needleDeg = -52 + swing1 * 66 - swing2 * 14;
    const gentleHover = Math.sin(range01(p, 0.62, 0.86) * Math.PI * 2) * 1.5;

    ctx.save();
    ctx.rotate((needleDeg + gentleHover) * deg);

    const tipLen = 118 * u;
    const halfW = 21 * u;

    ctx.fillStyle = C.aqua;
    ctx.beginPath();
    ctx.moveTo(0, -tipLen);
    ctx.lineTo(-halfW, 0);
    ctx.lineTo(0, 0);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = C.aquaMid;
    ctx.beginPath();
    ctx.moveTo(0, -tipLen);
    ctx.lineTo(halfW, 0);
    ctx.lineTo(0, 0);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = C.ice;
    ctx.beginPath();
    ctx.moveTo(0, tipLen);
    ctx.lineTo(-halfW, 0);
    ctx.lineTo(0, 0);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = C.sky;
    ctx.beginPath();
    ctx.moveTo(0, tipLen);
    ctx.lineTo(halfW, 0);
    ctx.lineTo(0, 0);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = C.surfaceDark;
    ctx.beginPath();
    ctx.arc(0, 0, 18 * u, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = C.ice;
    ctx.beginPath();
    ctx.arc(0, 0, 10 * u, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = C.aqua;
    ctx.beginPath();
    ctx.arc(0, 0, 4.5 * u, 0, Math.PI * 2);
    ctx.fill();

    ctx.restore();
    ctx.restore();
  }

  // =========================================================================
  // SCENE 4 (15-20s): EXECUTIVE COMMERCE BRIEFCASE
  // =========================================================================
  function drawScene4Briefcase(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    const floatY = Math.sin(range01(p, 0.14, 0.86) * Math.PI * 2) * 5 * u;

    ctx.save();
    ctx.translate(cx, cy + floatY + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    const bW = 312 * u;
    const bH = 212 * u;
    const bLeft = -bW * 0.5;
    const bTop = -74 * u;
    const bRad = 22 * u;

    // Top Handle drawn cleanly BEHIND main case body
    const hW = 112 * u;
    const hTop = bTop - 54 * u;
    ctx.strokeStyle = C.sky;
    ctx.lineWidth = 17 * u;
    ctx.lineCap = 'butt';
    ctx.lineJoin = 'round';
    ctx.beginPath();
    ctx.moveTo(-hW * 0.5, bTop + 12 * u);
    ctx.lineTo(-hW * 0.5, hTop + 18 * u);
    ctx.arcTo(-hW * 0.5, hTop, -hW * 0.5 + 18 * u, hTop, 18 * u);
    ctx.lineTo(hW * 0.5 - 18 * u, hTop);
    ctx.arcTo(hW * 0.5, hTop, hW * 0.5, hTop + 18 * u, 18 * u);
    ctx.lineTo(hW * 0.5, bTop + 12 * u);
    ctx.stroke();

    ctx.strokeStyle = C.ice;
    ctx.lineWidth = 3.5 * u;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(-hW * 0.5 + 22 * u, hTop - 4 * u);
    ctx.lineTo(hW * 0.5 - 22 * u, hTop - 4 * u);
    ctx.stroke();

    // Main Briefcase Body
    ctx.save();
    roundedRectPath(bLeft, bTop, bW, bH, bRad);
    ctx.clip();

    ctx.fillStyle = C.surfaceMid;
    ctx.fillRect(bLeft, bTop, bW * 0.5, bH);
    ctx.fillStyle = C.surfaceDark;
    ctx.fillRect(0, bTop, bW * 0.5, bH);

    const flapClose = easeOutCubic(range01(p, 0.16, 0.34));
    const flapLift = (1 - flapClose) * -14 * u;
    const flapH = 92 * u;

    ctx.fillStyle = C.bgTop;
    ctx.fillRect(bLeft, bTop + flapH + flapLift, bW, 8 * u);

    ctx.fillStyle = C.aqua;
    ctx.fillRect(bLeft, bTop + flapLift, bW * 0.5, flapH);
    ctx.fillStyle = C.aquaMid;
    ctx.fillRect(0, bTop + flapLift, bW * 0.5, flapH);

    ctx.restore();

    ctx.strokeStyle = C.trackStroke;
    ctx.lineWidth = 3.2 * u;
    roundedRectPath(bLeft, bTop, bW, bH, bRad);
    ctx.stroke();

    // Two Symmetrical Vertical Straps & Locking Clasps
    const latchLock = easeOutCubic(range01(p, 0.34, 0.50));
    const claspY = bTop + 92 * u + (1 - flapClose) * -14 * u;
    const strapXs = [-76 * u, 76 * u];

    for (let i = 0; i < 2; i++) {
      const sx = strapXs[i];

      ctx.fillStyle = C.surfaceDark;
      ctx.fillRect(sx - 10 * u, bTop + 2 * u, 20 * u, Math.max(0, claspY - bTop - 16 * u));

      const cw = 36 * u;
      const ch = 40 * u;
      ctx.fillStyle = C.ice;
      roundedRectPath(sx - cw * 0.5, claspY - ch * 0.5, cw, ch, 8 * u);
      ctx.fill();

      ctx.fillStyle = C.surfaceDark;
      roundedRectPath(sx - 10 * u, claspY - 11 * u, 20 * u, 22 * u, 4 * u);
      ctx.fill();

      const pinY = claspY - 4 * u + (1 - latchLock) * 6 * u;
      ctx.fillStyle = lerpColor(C.sky, C.aqua, latchLock);
      roundedRectPath(sx - 6 * u, pinY, 12 * u, 8 * u, 3 * u);
      ctx.fill();
    }

    // Horizontal Bottom Trade Status Bar
    const barY = bTop + bH - 42 * u;
    const barW = 216 * u;
    const barH = 10 * u;
    ctx.fillStyle = C.trackMuted;
    roundedRectPath(-barW * 0.5, barY, barW, barH, barH * 0.5);
    ctx.fill();

    const barFill = easeOutCubic(range01(p, 0.44, 0.72));
    if (barFill > 0.01) {
      const activeW = Math.max(barH, barW * barFill);
      ctx.fillStyle = C.aqua;
      roundedRectPath(-activeW * 0.5, barY, activeW, barH, barH * 0.5);
      ctx.fill();
    }

    ctx.restore();
  }

  // =========================================================================
  // RENDER PIPELINE
  // =========================================================================
  ctx.save();
  drawBackground();
  drawSideTelemetry();

  if (currentScene === 0) {
    drawScene1Globe(sceneProgress);
  } else if (currentScene === 1) {
    drawScene2FX(sceneProgress);
  } else if (currentScene === 2) {
    drawScene3Compass(sceneProgress);
  } else {
    drawScene4Briefcase(sceneProgress);
  }
  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const u = minSide / 1000;
  const cx = width * 0.5;
  const cy = height * 0.5;
  const loopPhase = (loopT / duration) * Math.PI * 2;
  const heroZoom = 1.22;

  // Color Palette — Warm Charcoal Slate + Vibrant Tangerine Coral & Warm Amber
  const C = {
    bgTop: '#101216',
    bgMid: '#171B22',
    bgBot: '#212630',
    gridMark: 'rgba(255, 206, 158, 0.06)',
    trackMuted: '#2B3342',
    trackStroke: '#424E63',
    surfaceDark: '#1A1F28',
    surfaceMid: '#252C38',
    surfaceLight: '#323B4C',
    coral: '#FF6B35',
    coralMid: '#E85A27',
    coralDeep: '#C94418',
    amber: '#FFB703',
    amberMid: '#E5A100',
    peach: '#FFD699',
    cream: '#FFF4E0',
    creamShade: '#F2DFC2',
    sheen: 'rgba(255, 244, 224, 0.22)'
  };

  // Smooth, Controlled Math & Color Utilities
  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function range01(p, start, end) {
    return clamp01((p - start) / (end - start));
  }

  function easeOutCubic(x) {
    const inv = 1 - clamp01(x);
    return 1 - inv * inv * inv;
  }

  function easeInCubic(x) {
    const v = clamp01(x);
    return v * v * v;
  }

  function easeInOutCubic(x) {
    const v = clamp01(x);
    return v < 0.5 ? 4 * v * v * v : 1 - Math.pow(-2 * v + 2, 3) / 2;
  }

  function easeOutSoftBack(x) {
    const v = clamp01(x);
    const c1 = 0.78;
    const c3 = c1 + 1;
    return 1 + c3 * Math.pow(v - 1, 3) + c1 * Math.pow(v - 1, 2);
  }

  function lerpColor(hexA, hexB, f) {
    const k = clamp01(f);
    const a = parseInt(hexA.slice(1), 16);
    const b = parseInt(hexB.slice(1), 16);
    const ar = (a >> 16) & 255;
    const ag = (a >> 8) & 255;
    const ab = a & 255;
    const br = (b >> 16) & 255;
    const bg = (b >> 8) & 255;
    const bb = b & 255;
    const r = Math.round(ar + (br - ar) * k);
    const g = Math.round(ag + (bg - ag) * k);
    const bl = Math.round(ab + (bb - ab) * k);
    return 'rgb(' + r + ',' + g + ',' + bl + ')';
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function drawPartialPolyline(points, progress) {
    if (progress <= 0 || points.length < 2) return;
    let totalLen = 0;
    const segLens = [];
    for (let i = 0; i < points.length - 1; i++) {
      const len = Math.hypot(points[i + 1][0] - points[i][0], points[i + 1][1] - points[i][1]);
      segLens.push(len);
      totalLen += len;
    }
    let remaining = totalLen * clamp01(progress);
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 0; i < segLens.length; i++) {
      if (remaining <= 0) break;
      if (remaining >= segLens[i]) {
        ctx.lineTo(points[i + 1][0], points[i + 1][1]);
        remaining -= segLens[i];
      } else {
        const frac = remaining / segLens[i];
        ctx.lineTo(
          points[i][0] + (points[i + 1][0] - points[i][0]) * frac,
          points[i][1] + (points[i + 1][1] - points[i][1]) * frac
        );
        remaining = 0;
      }
    }
    ctx.stroke();
  }

  function drawBackground() {
    // Pure Modern Dark Aesthetic Linear Gradient — ZERO background glow
    const bgGrad = ctx.createLinearGradient(0, 0, width, height);
    bgGrad.addColorStop(0, C.bgTop);
    bgGrad.addColorStop(0.5, C.bgMid);
    bgGrad.addColorStop(1, C.bgBot);
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, width, height);

    // Subtle uniform precision micro-diamond grid with seamless 1-cell horizontal drift
    const step = 60 * u;
    const driftX = (loopT / duration) * step;
    const cols = Math.ceil(width / step) + 2;
    const rows = Math.ceil(height / step) + 2;
    const startX = cx - Math.floor(cols * 0.5) * step + (driftX % step) - step;
    const startY = cy - Math.floor(rows * 0.5) * step;
    const d = 2.4 * u;

    ctx.fillStyle = C.gridMark;
    ctx.beginPath();
    for (let r = 0; r < rows; r++) {
      const py = startY + r * step;
      if (py < 26 * u || py > height - 26 * u) continue;
      for (let c = 0; c < cols; c++) {
        const px = startX + c * step;
        if (px < 26 * u || px > width - 26 * u) continue;
        ctx.moveTo(px, py - d);
        ctx.lineTo(px + d, py);
        ctx.lineTo(px, py + d);
        ctx.lineTo(px - d, py);
        ctx.closePath();
      }
    }
    ctx.fill();
  }

  function drawSideTelemetry() {
    const minHalfW = 580 * u;
    if (width * 0.5 < minHalfW + 80 * u) return;

    const sideOffset = Math.min(620 * u, width * 0.5 - 110 * u);
    const lx = cx - sideOffset;
    const rx = cx + sideOffset;

    const capW = 6 * u;
    const capH = 40 * u;
    const capGap = 20 * u;
    const totalH = sceneCount * capH + (sceneCount - 1) * capGap;
    const topY = cy - totalH * 0.5;

    const activeFade = Math.min(
      easeOutCubic(range01(sceneProgress, 0.0, 0.08)),
      1 - easeInCubic(range01(sceneProgress, 0.90, 1.0))
    );

    // Left column: 4 Scene Stage Progress Capsules
    for (let i = 0; i < sceneCount; i++) {
      const y = topY + i * (capH + capGap);
      ctx.fillStyle = C.trackMuted;
      roundedRectPath(lx - capW * 0.5, y, capW, capH, capW * 0.5);
      ctx.fill();

      if (i === currentScene && activeFade > 0.01) {
        const fillFrac = easeInOutCubic(range01(sceneProgress, 0.0, 0.90));
        const fillH = Math.max(capW, capH * fillFrac);
        ctx.fillStyle = lerpColor(C.trackMuted, C.coral, activeFade);
        roundedRectPath(lx - capW * 0.5, y, capW, fillH, capW * 0.5);
        ctx.fill();
      }
    }

    // Right column: 4 Symmetrical Tap-Status Dot + Capsule Rows (clean 10u gap)
    const totalW = 60 * u;
    const barH = 6 * u;
    const dotR = 3.2 * u;
    for (let i = 0; i < 4; i++) {
      const rowCenterY = topY + i * (capH + capGap) + capH * 0.5;
      const x0 = rx - totalW * 0.5;
      const highlight = i === currentScene ? activeFade : 0;

      ctx.fillStyle = lerpColor(C.trackStroke, C.amber, highlight);
      ctx.beginPath();
      ctx.arc(x0 + dotR, rowCenterY, dotR, 0, Math.PI * 2);
      ctx.fill();

      const barStart = x0 + dotR * 2 + 10 * u;
      const barMaxW = totalW - (dotR * 2 + 10 * u);
      const wave = 0.35 + 0.65 * (0.5 + 0.5 * Math.sin(loopPhase * 2 - i * 1.05));
      const curW = Math.max(barH, barMaxW * wave);

      ctx.fillStyle = C.trackMuted;
      roundedRectPath(barStart, rowCenterY - barH * 0.5, barMaxW, barH, barH * 0.5);
      ctx.fill();

      ctx.fillStyle = lerpColor(C.trackStroke, C.coral, highlight);
      roundedRectPath(barStart, rowCenterY - barH * 0.5, curW, barH, barH * 0.5);
      ctx.fill();
    }
  }

  function getSceneEnvelope(p) {
    const enterP = range01(p, 0.0, 0.14);
    const exitP = range01(p, 0.86, 1.0);
    const enterEase = easeOutCubic(enterP);
    const exitEase = easeInCubic(exitP);
    const scale = p < 0.5 ? 0.86 + 0.14 * enterEase : 1 - 0.14 * exitEase;
    const liftY = p < 0.5 ? (1 - enterEase) * 18 * u : -exitEase * 18 * u;
    const alpha = p < 0.10
      ? easeOutCubic(range01(p, 0.0, 0.10))
      : p > 0.90
        ? 1 - easeInCubic(range01(p, 0.90, 1.0))
        : 1;
    return { scale, alpha, liftY };
  }

  // =========================================================================
  // SCENE 1 (0-5s): CONTACTLESS SMART CARD
  // =========================================================================
  function drawScene1Card(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    const floatY = Math.sin(range01(p, 0.14, 0.86) * Math.PI * 2) * 5 * u;
    const cardSlideY = (1 - easeOutCubic(range01(p, 0.04, 0.22))) * 22 * u;

    ctx.save();
    ctx.translate(cx, cy + floatY + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    // 3 Contactless NFC Signal Waves strictly ABOVE card top (-68u), zero overlap!
    const waveShow = Math.min(
      easeOutCubic(range01(p, 0.22, 0.34)),
      1 - easeInCubic(range01(p, 0.78, 0.88))
    );
    if (waveShow > 0.01) {
      const waveCy = -86 * u;
      const wavePhase = range01(p, 0.22, 0.86) * Math.PI * 4;
      const radii = [32, 56, 80];
      const halfSpan = (36 * Math.PI) / 180;

      ctx.lineWidth = 5.5 * u;
      ctx.lineCap = 'round';
      for (let i = 0; i < 3; i++) {
        const pulse = 0.5 + 0.5 * Math.sin(wavePhase - i * 1.15);
        const col = lerpColor('#5A6780', i === 1 ? C.amber : C.coral, 0.35 + 0.65 * pulse);
        ctx.save();
        ctx.globalAlpha = env.alpha * waveShow * (0.62 + 0.38 * pulse);
        ctx.strokeStyle = col;
        ctx.beginPath();
        ctx.arc(0, waveCy, radii[i] * u, -Math.PI * 0.5 - halfSpan, -Math.PI * 0.5 + halfSpan);
        ctx.stroke();
        ctx.restore();
      }
    }

    // Smart Card Body (310u x 192u)
    ctx.save();
    ctx.translate(0, cardSlideY);

    const cardW = 310 * u;
    const cardH = 192 * u;
    const cLeft = -cardW * 0.5;
    const cTop = -68 * u;
    const cRad = 22 * u;

    ctx.save();
    roundedRectPath(cLeft, cTop, cardW, cardH, cRad);
    ctx.clip();

    ctx.fillStyle = C.surfaceMid;
    ctx.fillRect(cLeft, cTop, cardW, cardH);

    ctx.fillStyle = C.surfaceDark;
    ctx.beginPath();
    ctx.moveTo(cLeft + cardW, cTop);
    ctx.lineTo(cLeft + cardW, cTop + cardH);
    ctx.lineTo(cLeft, cTop + cardH);
    ctx.closePath();
    ctx.fill();

    // Accent dual-tone horizontal header stripe
    ctx.fillStyle = C.coral;
    ctx.fillRect(cLeft, cTop + 30 * u, cardW * 0.65, 24 * u);
    ctx.fillStyle = C.amber;
    ctx.fillRect(cLeft + cardW * 0.65, cTop + 30 * u, cardW * 0.35, 24 * u);

    // Diagonal light sheen sweep (0.42 -> 0.70)
    const sheenP = easeInOutCubic(range01(p, 0.42, 0.70));
    if (sheenP > 0 && sheenP < 1) {
      const sx = (-260 + sheenP * 520) * u;
      ctx.save();
      ctx.translate(sx, cTop + cardH * 0.5);
      ctx.rotate(Math.PI * 0.2);
      ctx.fillStyle = C.sheen;
      ctx.fillRect(-24 * u, -180 * u, 48 * u, 360 * u);
      ctx.restore();
    }
    ctx.restore();

    ctx.strokeStyle = C.trackStroke;
    ctx.lineWidth = 3 * u;
    roundedRectPath(cLeft, cTop, cardW, cardH, cRad);
    ctx.stroke();

    // EMV Smart Chip cleanly positioned at left-mid
    const chipX = -124 * u;
    const chipY = 8 * u;
    const chipW = 52 * u;
    const chipH = 38 * u;
    ctx.fillStyle = C.amber;
    roundedRectPath(chipX, chipY, chipW, chipH, 7 * u);
    ctx.fill();

    ctx.save();
    roundedRectPath(chipX, chipY, chipW, chipH, 7 * u);
    ctx.clip();
    ctx.strokeStyle = C.surfaceDark;
    ctx.lineWidth = 2.2 * u;
    ctx.beginPath();
    ctx.moveTo(chipX + chipW * 0.33, chipY);
    ctx.lineTo(chipX + chipW * 0.33, chipY + chipH);
    ctx.moveTo(chipX + chipW * 0.67, chipY);
    ctx.lineTo(chipX + chipW * 0.67, chipY + chipH);
    ctx.moveTo(chipX, chipY + chipH * 0.5);
    ctx.lineTo(chipX + chipW * 0.33, chipY + chipH * 0.5);
    ctx.moveTo(chipX + chipW * 0.67, chipY + chipH * 0.5);
    ctx.lineTo(chipX + chipW, chipY + chipH * 0.5);
    ctx.stroke();
    ctx.restore();

    // Clean contactless mini badge on right-mid
    ctx.fillStyle = C.surfaceLight;
    roundedRectPath(62 * u, 18 * u, 62 * u, 18 * u, 9 * u);
    ctx.fill();
    const badgeFill = easeOutCubic(range01(p, 0.24, 0.54));
    ctx.fillStyle = C.coral;
    roundedRectPath(66 * u, 22 * u, Math.max(10 * u, 54 * u * badgeFill), 10 * u, 5 * u);
    ctx.fill();

    // 4 evenly spaced abstract card number bar pills
    const pillY = 78 * u;
    const pillW = 50 * u;
    const pillH = 11 * u;
    const pillGap = 16 * u;
    const pillStart = -(4 * pillW + 3 * pillGap) * 0.5;
    for (let i = 0; i < 4; i++) {
      const reveal = easeOutCubic(range01(p, 0.16 + i * 0.05, 0.30 + i * 0.05));
      if (reveal <= 0.01) continue;
      const px = pillStart + i * (pillW + pillGap);
      ctx.fillStyle = i === 3 ? C.cream : C.trackStroke;
      roundedRectPath(px, pillY, pillW * reveal, pillH, pillH * 0.5);
      ctx.fill();
    }

    ctx.restore();
    ctx.restore();
  }

  // =========================================================================
  // SCENE 2 (5-10s): MODULAR E-WALLET
  // =========================================================================
  function drawScene2Wallet(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    const floatY = Math.sin(range01(p, 0.14, 0.86) * Math.PI * 2) * 5 * u;

    ctx.save();
    ctx.translate(cx, cy + floatY + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    const wW = 292 * u;
    const wH = 184 * u;
    const wLeft = -wW * 0.5;
    const wTop = -44 * u;
    const wRad = 24 * u;

    // Back pocket rim behind main wallet body
    ctx.fillStyle = C.coralDeep;
    roundedRectPath(wLeft + 16 * u, wTop - 28 * u, wW - 32 * u, 44 * u, 16 * u);
    ctx.fill();

    // 2 Geometric Payment Tokens gliding cleanly into the top slot (clipped ABOVE wTop)
    ctx.save();
    ctx.beginPath();
    ctx.rect(-160 * u, -210 * u, 320 * u, 166 * u);
    ctx.clip();

    const tokens = [
      { x: -34, start: 0.14, end: 0.42 },
      { x: 34, start: 0.32, end: 0.60 }
    ];
    for (let i = 0; i < tokens.length; i++) {
      const tk = tokens[i];
      const tp = range01(p, tk.start, tk.end);
      if (tp <= 0 || tp >= 1) continue;
      const appear = easeOutCubic(range01(tp, 0.0, 0.25));
      const drop = easeInOutCubic(range01(tp, 0.15, 1.0));
      const ty = (-158 + drop * 144) * u;
      const tr = 23 * u * appear;

      ctx.fillStyle = C.amber;
      ctx.beginPath();
      ctx.arc(tk.x * u, ty, tr, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = C.surfaceDark;
      ctx.beginPath();
      ctx.arc(tk.x * u, ty, tr * 0.68, 0, Math.PI * 2);
      ctx.fill();

      const td = tr * 0.34;
      ctx.fillStyle = C.cream;
      ctx.beginPath();
      ctx.moveTo(tk.x * u, ty - td);
      ctx.lineTo(tk.x * u + td, ty);
      ctx.lineTo(tk.x * u, ty + td);
      ctx.lineTo(tk.x * u - td, ty);
      ctx.closePath();
      ctx.fill();
    }
    ctx.restore();

    // Main Wallet Front Body (flat duotone split)
    ctx.save();
    roundedRectPath(wLeft, wTop, wW, wH, wRad);
    ctx.clip();

    ctx.fillStyle = C.coral;
    ctx.fillRect(wLeft, wTop, wW * 0.52, wH);
    ctx.fillStyle = C.coralMid;
    ctx.fillRect(wLeft + wW * 0.52, wTop, wW * 0.48, wH);
    ctx.restore();

    // Subtle crisp inner stitched border
    ctx.strokeStyle = 'rgba(255, 244, 224, 0.28)';
    ctx.lineWidth = 2 * u;
    ctx.setLineDash([7 * u, 7 * u]);
    roundedRectPath(wLeft + 14 * u, wTop + 14 * u, wW - 28 * u, wH - 28 * u, 14 * u);
    ctx.stroke();
    ctx.setLineDash([]);

    // Left-face balance meter cleanly positioned
    const balX = -112 * u;
    const balW = 130 * u;
    const balH = 12 * u;
    const balY1 = wTop + 64 * u;
    const balY2 = wTop + 94 * u;

    const dep1 = easeOutCubic(range01(p, 0.34, 0.46)) * 0.48;
    const dep2 = easeOutCubic(range01(p, 0.52, 0.66)) * 0.52;
    const totalFill = 0.16 + 0.84 * (dep1 + dep2);

    ctx.fillStyle = C.coralDeep;
    roundedRectPath(balX, balY1, balW, balH, balH * 0.5);
    ctx.fill();

    ctx.fillStyle = C.cream;
    roundedRectPath(balX, balY1, balW * totalFill, balH, balH * 0.5);
    ctx.fill();

    ctx.fillStyle = C.coralDeep;
    roundedRectPath(balX, balY2, balW * 0.68, 9 * u, 4.5 * u);
    ctx.fill();
    ctx.fillStyle = C.peach;
    roundedRectPath(balX, balY2, balW * 0.68 * (0.35 + 0.65 * totalFill), 9 * u, 4.5 * u);
    ctx.fill();

    // Magnetic Side Clasp Tab on Right Side
    const claspUnlock = Math.sin(range01(p, 0.14, 0.62) * Math.PI);
    const claspShiftX = claspUnlock * 8 * u;
    const clX = 56 * u + claspShiftX;
    const clY = wTop + (wH - 64 * u) * 0.5;
    const clW = 98 * u;
    const clH = 64 * u;

    ctx.fillStyle = C.surfaceDark;
    roundedRectPath(clX, clY, clW, clH, 16 * u);
    ctx.fill();

    ctx.strokeStyle = C.trackStroke;
    ctx.lineWidth = 2.6 * u;
    roundedRectPath(clX, clY, clW, clH, 16 * u);
    ctx.stroke();

    const lockGlow = easeOutCubic(range01(p, 0.58, 0.72));
    ctx.fillStyle = lerpColor(C.peach, C.amber, lockGlow);
    ctx.beginPath();
    ctx.arc(clX + 30 * u, clY + clH * 0.5, 13 * u, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = C.surfaceDark;
    ctx.beginPath();
    ctx.arc(clX + 30 * u, clY + clH * 0.5, 5 * u, 0, Math.PI * 2);
    ctx.fill();

    ctx.restore();
  }

  // =========================================================================
  // SCENE 3 (10-15s): SMART QR PAYMENT TERMINAL (Clean Rounded Module, ZERO Corner L-Brackets!)
  // =========================================================================
  function drawScene3QR(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    const floatY = Math.sin(range01(p, 0.14, 0.86) * Math.PI * 2) * 4.5 * u;

    ctx.save();
    ctx.translate(cx, cy + floatY + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    const modS = 272 * u;
    const modHalf = modS * 0.5;
    ctx.fillStyle = C.surfaceDark;
    roundedRectPath(-modHalf, -modHalf, modS, modS, 28 * u);
    ctx.fill();

    ctx.strokeStyle = C.trackStroke;
    ctx.lineWidth = 3.2 * u;
    roundedRectPath(-modHalf, -modHalf, modS, modS, 28 * u);
    ctx.stroke();

    const bezS = 240 * u;
    const bezHalf = bezS * 0.5;
    ctx.fillStyle = C.surfaceMid;
    roundedRectPath(-bezHalf, -bezHalf, bezS, bezS, 20 * u);
    ctx.fill();

    const gridN = 7;
    const cellPitch = 28 * u;
    const tileS = 20 * u;
    const gridOrigin = -((gridN - 1) * cellPitch) * 0.5;

    const scanP = range01(p, 0.24, 0.78);
    const tri = scanP < 0.5 ? easeInOutCubic(scanP * 2) : easeInOutCubic((1 - scanP) * 2);
    const scanY = (-104 + tri * 208) * u;

    function drawFinder(col0, row0) {
      const fx = gridOrigin + col0 * cellPitch - tileS * 0.5;
      const fy = gridOrigin + row0 * cellPitch - tileS * 0.5;
      const fSize = cellPitch + tileS;

      ctx.fillStyle = C.cream;
      roundedRectPath(fx, fy, fSize, fSize, 10 * u);
      ctx.fill();

      ctx.fillStyle = C.surfaceMid;
      roundedRectPath(fx + 9 * u, fy + 9 * u, fSize - 18 * u, fSize - 18 * u, 5 * u);
      ctx.fill();

      ctx.fillStyle = C.coral;
      roundedRectPath(fx + 16 * u, fy + 16 * u, fSize - 32 * u, fSize - 32 * u, 4 * u);
      ctx.fill();
    }

    drawFinder(0, 0);
    drawFinder(5, 0);
    drawFinder(0, 5);

    const dataCells = [
      [3, 0], [3, 1],
      [0, 3], [1, 3], [2, 2], [3, 3], [4, 2], [5, 3], [6, 3],
      [2, 4], [4, 4], [5, 4],
      [3, 5], [4, 5], [6, 5],
      [3, 6], [5, 6], [6, 6]
    ];

    for (let i = 0; i < dataCells.length; i++) {
      const col = dataCells[i][0];
      const row = dataCells[i][1];
      const mx = gridOrigin + col * cellPitch;
      const my = gridOrigin + row * cellPitch;
      const appear = easeOutCubic(range01(p, 0.12 + (col + row) * 0.015, 0.24 + (col + row) * 0.015));
      if (appear <= 0.01) continue;

      const distY = Math.abs(my - scanY);
      const scanActive = scanP > 0 && scanP < 1 ? easeOutCubic(range01(48 * u - distY, 0, 48 * u)) : 0;
      const baseCol = (col + row) % 3 === 0 ? C.cream : C.peach;
      ctx.fillStyle = lerpColor(baseCol, C.amber, scanActive);

      const curS = tileS * appear;
      roundedRectPath(mx - curS * 0.5, my - curS * 0.5, curS, curS, 5 * u);
      ctx.fill();
    }

    if (scanP > 0 && scanP < 1) {
      const scanAlpha = Math.min(range01(scanP, 0, 0.09), 1 - range01(scanP, 0.91, 1));
      const goingDown = scanP < 0.5;
      ctx.save();
      roundedRectPath(-bezHalf + 2 * u, -bezHalf + 2 * u, bezS - 4 * u, bezS - 4 * u, 18 * u);
      ctx.clip();
      ctx.globalAlpha = env.alpha * scanAlpha;

      const trailH = 22 * u;
      const gy0 = goingDown ? scanY - trailH : scanY;
      const gy1 = goingDown ? scanY : scanY + trailH;
      const tGrad = ctx.createLinearGradient(0, gy0, 0, gy1);
      if (goingDown) {
        tGrad.addColorStop(0, 'rgba(255, 107, 53, 0)');
        tGrad.addColorStop(1, 'rgba(255, 107, 53, 0.26)');
      } else {
        tGrad.addColorStop(0, 'rgba(255, 107, 53, 0.26)');
        tGrad.addColorStop(1, 'rgba(255, 107, 53, 0)');
      }
      ctx.fillStyle = tGrad;
      ctx.fillRect(-bezHalf, gy0, bezS, trailH);

      ctx.strokeStyle = C.coral;
      ctx.lineWidth = 3.4 * u;
      ctx.beginPath();
      ctx.moveTo(-bezHalf + 14 * u, scanY);
      ctx.lineTo(bezHalf - 14 * u, scanY);
      ctx.stroke();
      ctx.restore();
    }

    ctx.restore();
  }

  // =========================================================================
  // SCENE 4 (15-20s): INSTANT DIGITAL RECEIPT
  // =========================================================================
  function receiptPath(w, h, topR, teeth) {
    const halfW = w * 0.5;
    const top = -h * 0.5;
    const botBase = h * 0.5 - 14 * u;
    const toothAmp = 14 * u;
    const toothW = w / teeth;

    ctx.beginPath();
    ctx.moveTo(-halfW + topR, top);
    ctx.lineTo(halfW - topR, top);
    ctx.arcTo(halfW, top, halfW, top + topR, topR);
    ctx.lineTo(halfW, botBase);

    for (let i = teeth - 1; i >= 0; i--) {
      const xRight = -halfW + (i + 1) * toothW;
      const xMid = xRight - toothW * 0.5;
      const xLeft = -halfW + i * toothW;
      ctx.lineTo(xMid, botBase + toothAmp);
      ctx.lineTo(xLeft, botBase);
    }

    ctx.lineTo(-halfW, top + topR);
    ctx.arcTo(-halfW, top, -halfW + topR, top, topR);
    ctx.closePath();
  }

  function drawScene4Receipt(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    const floatY = Math.sin(range01(p, 0.14, 0.86) * Math.PI * 2) * 5 * u;
    const printSlide = (1 - easeOutCubic(range01(p, 0.02, 0.20))) * 24 * u;

    ctx.save();
    ctx.translate(cx, cy + floatY + printSlide + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    const rW = 240 * u;
    const rH = 316 * u;

    ctx.save();
    receiptPath(rW, rH, 18 * u, 6);
    ctx.clip();
    ctx.fillStyle = C.cream;
    ctx.fillRect(-rW * 0.5, -rH * 0.5, rW * 0.54, rH);
    ctx.fillStyle = C.creamShade;
    ctx.fillRect(rW * 0.04, -rH * 0.5, rW * 0.46, rH);
    ctx.restore();

    // Top Success Checkmark Emblem
    const badgeScale = easeOutCubic(range01(p, 0.14, 0.28));
    if (badgeScale > 0.01) {
      ctx.save();
      ctx.translate(0, -96 * u);
      ctx.scale(badgeScale, badgeScale);
      ctx.fillStyle = C.coral;
      ctx.beginPath();
      ctx.arc(0, 0, 32 * u, 0, Math.PI * 2);
      ctx.fill();

      const chkP = easeOutCubic(range01(p, 0.24, 0.42));
      ctx.strokeStyle = C.cream;
      ctx.lineWidth = 7 * u;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      drawPartialPolyline(
        [
          [-14 * u, 1 * u],
          [-4 * u, 11 * u],
          [16 * u, -10 * u]
        ],
        chkP
      );
      ctx.restore();
    }

    // Perforated divider dashes
    ctx.fillStyle = '#C9B393';
    const dashCount = 9;
    const dashW = 12 * u;
    const dashGap = 9 * u;
    const dashSpan = dashCount * dashW + (dashCount - 1) * dashGap;
    const dashStart = -dashSpan * 0.5;
    for (let i = 0; i < dashCount; i++) {
      roundedRectPath(dashStart + i * (dashW + dashGap), -46 * u, dashW, 3.5 * u, 1.75 * u);
      ctx.fill();
    }

    // 3 Itemized Transaction Rows
    const rows = [
      { y: -16, lw: 82, rw: 44, delay: 0.18 },
      { y: 18, lw: 64, rw: 44, delay: 0.24 },
      { y: 52, lw: 92, rw: 44, delay: 0.30 }
    ];
    for (let i = 0; i < rows.length; i++) {
      const row = rows[i];
      const rp = easeOutCubic(range01(p, row.delay, row.delay + 0.12));
      if (rp <= 0.01) continue;

      ctx.fillStyle = C.surfaceLight;
      roundedRectPath(-90 * u, row.y * u - 5 * u, row.lw * u * rp, 10 * u, 5 * u);
      ctx.fill();

      const curRW = row.rw * u * rp;
      ctx.fillStyle = '#6A778E';
      roundedRectPath(90 * u - curRW, row.y * u - 5 * u, curRW, 10 * u, 5 * u);
      ctx.fill();
    }

    // Solid subtotal divider
    const divP = easeOutCubic(range01(p, 0.36, 0.44));
    if (divP > 0.01) {
      ctx.fillStyle = '#C9B393';
      roundedRectPath(-90 * u, 77 * u, 180 * u * divP, 2.5 * u, 1.25 * u);
      ctx.fill();
    }

    // Final Total Highlight Row
    const totP = easeOutCubic(range01(p, 0.42, 0.54));
    if (totP > 0.01) {
      ctx.fillStyle = C.surfaceDark;
      roundedRectPath(-90 * u, 98 * u, 68 * u * totP, 13 * u, 6.5 * u);
      ctx.fill();

      const totRW = 66 * u * totP;
      ctx.fillStyle = C.coral;
      roundedRectPath(90 * u - totRW, 98 * u, totRW, 13 * u, 6.5 * u);
      ctx.fill();
    }

    ctx.restore();
  }

  // =========================================================================
  // RENDER PIPELINE
  // =========================================================================
  ctx.save();
  drawBackground();
  drawSideTelemetry();

  if (currentScene === 0) {
    drawScene1Card(sceneProgress);
  } else if (currentScene === 1) {
    drawScene2Wallet(sceneProgress);
  } else if (currentScene === 2) {
    drawScene3QR(sceneProgress);
  } else {
    drawScene4Receipt(sceneProgress);
  }
  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const u = minSide / 1000;
  const cx = width * 0.5;
  const cy = height * 0.5;
  const loopPhase = (loopT / duration) * Math.PI * 2;
  const heroZoom = 1.22;

  // Color Palette — Obsidian Deep Purple + Royal Violet & Neon Magenta
  const C = {
    bgTop: '#0B0718',
    bgMid: '#120B26',
    bgBot: '#190F36',
    gridMark: 'rgba(196, 181, 253, 0.065)',
    trackMuted: '#281C4F',
    trackStroke: '#463385',
    surfaceDark: '#140D2C',
    surfaceMid: '#1F1542',
    surfaceLight: '#2E205E',
    violet: '#8B5CF6',
    violetMid: '#7C3AED',
    violetDeep: '#5B21B6',
    magenta: '#F43F9E',
    magentaMid: '#DB2777',
    lavender: '#DDD6FE',
    lavenderWhite: '#F5F0FF'
  };

  // Smooth, Controlled Math & Color Utilities
  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function range01(p, start, end) {
    return clamp01((p - start) / (end - start));
  }

  function easeOutCubic(x) {
    const inv = 1 - clamp01(x);
    return 1 - inv * inv * inv;
  }

  function easeInCubic(x) {
    const v = clamp01(x);
    return v * v * v;
  }

  function easeInOutCubic(x) {
    const v = clamp01(x);
    return v < 0.5 ? 4 * v * v * v : 1 - Math.pow(-2 * v + 2, 3) / 2;
  }

  function easeOutSoftBack(x) {
    const v = clamp01(x);
    const c1 = 0.78;
    const c3 = c1 + 1;
    return 1 + c3 * Math.pow(v - 1, 3) + c1 * Math.pow(v - 1, 2);
  }

  function lerpColor(hexA, hexB, f) {
    const k = clamp01(f);
    const a = parseInt(hexA.slice(1), 16);
    const b = parseInt(hexB.slice(1), 16);
    const ar = (a >> 16) & 255;
    const ag = (a >> 8) & 255;
    const ab = a & 255;
    const br = (b >> 16) & 255;
    const bg = (b >> 8) & 255;
    const bb = b & 255;
    const r = Math.round(ar + (br - ar) * k);
    const g = Math.round(ag + (bg - ag) * k);
    const bl = Math.round(ab + (bb - ab) * k);
    return 'rgb(' + r + ',' + g + ',' + bl + ')';
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function hexagonPath(x, y, radius, rot) {
    ctx.beginPath();
    for (let i = 0; i < 6; i++) {
      const a = rot + (i * Math.PI) / 3;
      const px = x + Math.cos(a) * radius;
      const py = y + Math.sin(a) * radius;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
  }

  function drawPartialPolyline(points, progress) {
    if (progress <= 0 || points.length < 2) return;
    let totalLen = 0;
    const segLens = [];
    for (let i = 0; i < points.length - 1; i++) {
      const len = Math.hypot(points[i + 1][0] - points[i][0], points[i + 1][1] - points[i][1]);
      segLens.push(len);
      totalLen += len;
    }
    let remaining = totalLen * clamp01(progress);
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 0; i < segLens.length; i++) {
      if (remaining <= 0) break;
      if (remaining >= segLens[i]) {
        ctx.lineTo(points[i + 1][0], points[i + 1][1]);
        remaining -= segLens[i];
      } else {
        const frac = remaining / segLens[i];
        ctx.lineTo(
          points[i][0] + (points[i + 1][0] - points[i][0]) * frac,
          points[i][1] + (points[i + 1][1] - points[i][1]) * frac
        );
        remaining = 0;
      }
    }
    ctx.stroke();
  }

  function drawBackground() {
    // Pure Modern Dark Aesthetic Linear Gradient — ZERO background glow
    const bgGrad = ctx.createLinearGradient(0, 0, width, height);
    bgGrad.addColorStop(0, C.bgTop);
    bgGrad.addColorStop(0.5, C.bgMid);
    bgGrad.addColorStop(1, C.bgBot);
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, width, height);

    // Subtle uniform precision micro-crosshair pattern with seamless 1-cell upward drift
    const step = 64 * u;
    const driftY = -(loopT / duration) * step;
    const cols = Math.ceil(width / step) + 2;
    const rows = Math.ceil(height / step) + 2;
    const startX = cx - Math.floor(cols * 0.5) * step;
    const startY = cy - Math.floor(rows * 0.5) * step + (((driftY % step) + step) % step) - step;
    const arm = 3.2 * u;

    ctx.strokeStyle = C.gridMark;
    ctx.lineWidth = 1.2 * u;
    ctx.lineCap = 'round';
    ctx.beginPath();
    for (let r = 0; r < rows; r++) {
      const py = startY + r * step;
      if (py < 28 * u || py > height - 28 * u) continue;
      for (let c = 0; c < cols; c++) {
        const px = startX + c * step;
        if (px < 28 * u || px > width - 28 * u) continue;
        ctx.moveTo(px - arm, py);
        ctx.lineTo(px + arm, py);
        ctx.moveTo(px, py - arm);
        ctx.lineTo(px, py + arm);
      }
    }
    ctx.stroke();
  }

  function drawSideTelemetry() {
    const minHalfW = 580 * u;
    if (width * 0.5 < minHalfW + 80 * u) return;

    const sideOffset = Math.min(620 * u, width * 0.5 - 110 * u);
    const lx = cx - sideOffset;
    const rx = cx + sideOffset;

    const capW = 6 * u;
    const capH = 40 * u;
    const capGap = 20 * u;
    const totalH = sceneCount * capH + (sceneCount - 1) * capGap;
    const topY = cy - totalH * 0.5;

    const activeFade = Math.min(
      easeOutCubic(range01(sceneProgress, 0.0, 0.08)),
      1 - easeInCubic(range01(sceneProgress, 0.90, 1.0))
    );

    // Left column: 4 Scene Stage Progress Capsules
    for (let i = 0; i < sceneCount; i++) {
      const y = topY + i * (capH + capGap);
      ctx.fillStyle = C.trackMuted;
      roundedRectPath(lx - capW * 0.5, y, capW, capH, capW * 0.5);
      ctx.fill();

      if (i === currentScene && activeFade > 0.01) {
        const fillFrac = easeInOutCubic(range01(sceneProgress, 0.0, 0.90));
        const fillH = Math.max(capW, capH * fillFrac);
        ctx.fillStyle = lerpColor(C.trackMuted, C.magenta, activeFade);
        roundedRectPath(lx - capW * 0.5, y, capW, fillH, capW * 0.5);
        ctx.fill();
      }
    }

    // Right column: 4 Symmetrical Split Encryption Bar Pairs (strictly separated by 8u gap)
    const totalW = 60 * u;
    const gapW = 8 * u;
    const barH = 6 * u;
    for (let i = 0; i < 4; i++) {
      const y = topY + i * (capH + capGap) + (capH - barH) * 0.5;
      const ratio = 0.28 + 0.44 * (0.5 + 0.5 * Math.sin(loopPhase * 2 + i * 1.1));
      const leftW = (totalW - gapW) * ratio;
      const rightW = (totalW - gapW) * (1 - ratio);
      const x0 = rx - totalW * 0.5;

      const highlight = i === currentScene ? activeFade : 0;
      ctx.fillStyle = lerpColor(C.trackStroke, C.violet, highlight);
      roundedRectPath(x0, y, leftW, barH, barH * 0.5);
      ctx.fill();

      ctx.fillStyle = lerpColor(C.trackMuted, C.magenta, highlight);
      roundedRectPath(x0 + leftW + gapW, y, rightW, barH, barH * 0.5);
      ctx.fill();
    }
  }

  function getSceneEnvelope(p) {
    const enterP = range01(p, 0.0, 0.14);
    const exitP = range01(p, 0.86, 1.0);
    const enterEase = easeOutCubic(enterP);
    const exitEase = easeInCubic(exitP);
    const scale = p < 0.5 ? 0.86 + 0.14 * enterEase : 1 - 0.14 * exitEase;
    const liftY = p < 0.5 ? (1 - enterEase) * 18 * u : -exitEase * 18 * u;
    const alpha = p < 0.10
      ? easeOutCubic(range01(p, 0.0, 0.10))
      : p > 0.90
        ? 1 - easeInCubic(range01(p, 0.90, 1.0))
        : 1;
    return { scale, alpha, liftY };
  }

  // =========================================================================
  // SCENE 1 (0-5s): MULTI-LAYER DIGITAL SHIELD
  // =========================================================================
  function shieldPath(s) {
    ctx.beginPath();
    ctx.moveTo(0, -158 * s);
    ctx.lineTo(136 * s, -112 * s);
    ctx.lineTo(136 * s, -10 * s);
    ctx.bezierCurveTo(136 * s, 84 * s, 68 * s, 134 * s, 0, 158 * s);
    ctx.bezierCurveTo(-68 * s, 134 * s, -136 * s, 84 * s, -136 * s, -10 * s);
    ctx.lineTo(-136 * s, -112 * s);
    ctx.closePath();
  }

  function drawScene1Shield(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    const floatY = Math.sin(range01(p, 0.14, 0.86) * Math.PI * 2) * 5 * u;
    const splitOffset = (1 - easeOutCubic(range01(p, 0.04, 0.22))) * 22 * u;

    ctx.save();
    ctx.translate(cx, cy + floatY + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    // Symmetrical left & right halves clipped cleanly at x = 0 (zero center overlap)
    for (let side = -1; side <= 1; side += 2) {
      ctx.save();
      ctx.translate(side * splitOffset, 0);
      ctx.beginPath();
      if (side < 0) ctx.rect(-200 * u, -200 * u, 200 * u, 400 * u);
      else ctx.rect(0, -200 * u, 200 * u, 400 * u);
      ctx.clip();

      ctx.fillStyle = side < 0 ? C.violet : C.violetMid;
      shieldPath(u);
      ctx.fill();

      ctx.fillStyle = C.bgTop;
      shieldPath(u * 0.88);
      ctx.fill();

      ctx.fillStyle = side < 0 ? C.surfaceMid : C.surfaceDark;
      shieldPath(u * 0.82);
      ctx.fill();

      ctx.restore();
    }

    const lockP = easeOutCubic(range01(p, 0.20, 0.40));
    if (lockP > 0.01) {
      const traces = [
        [[-28 * u, -24 * u], [-62 * u, -58 * u], [-62 * u, -78 * u]],
        [[28 * u, -24 * u], [62 * u, -58 * u], [62 * u, -78 * u]],
        [[-36 * u, 8 * u], [-76 * u, 8 * u], [-76 * u, 38 * u]],
        [[36 * u, 8 * u], [76 * u, 8 * u], [76 * u, 38 * u]],
        [[0, 36 * u], [0, 84 * u]]
      ];

      ctx.strokeStyle = C.trackStroke;
      ctx.lineWidth = 3.2 * u;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      for (let i = 0; i < traces.length; i++) {
        drawPartialPolyline(traces[i], lockP);
      }

      const nodeP = easeOutCubic(range01(p, 0.34, 0.46));
      if (nodeP > 0.01) {
        const endPts = [
          [-62 * u, -78 * u],
          [62 * u, -78 * u],
          [-76 * u, 38 * u],
          [76 * u, 38 * u],
          [0, 84 * u]
        ];
        for (let i = 0; i < endPts.length; i++) {
          ctx.fillStyle = C.lavender;
          ctx.beginPath();
          ctx.arc(endPts[i][0], endPts[i][1], 4.8 * u * nodeP, 0, Math.PI * 2);
          ctx.fill();
        }
      }

      // Clean Flat Laser Scanner strictly clipped inside inner shield core
      const scanP = range01(p, 0.30, 0.78);
      if (scanP > 0 && scanP < 1) {
        const tri = scanP < 0.5 ? easeInOutCubic(scanP * 2) : easeInOutCubic((1 - scanP) * 2);
        const scanY = (-100 + tri * 198) * u;
        const goingDown = scanP < 0.5;
        const scanAlpha = Math.min(range01(scanP, 0, 0.1), 1 - range01(scanP, 0.9, 1));

        ctx.save();
        shieldPath(u * 0.81);
        ctx.clip();
        ctx.globalAlpha = env.alpha * scanAlpha;

        const trailH = 24 * u;
        const gradY0 = goingDown ? scanY - trailH : scanY;
        const gradY1 = goingDown ? scanY : scanY + trailH;
        const trailGrad = ctx.createLinearGradient(0, gradY0, 0, gradY1);
        if (goingDown) {
          trailGrad.addColorStop(0, 'rgba(244, 63, 158, 0)');
          trailGrad.addColorStop(1, 'rgba(244, 63, 158, 0.24)');
        } else {
          trailGrad.addColorStop(0, 'rgba(244, 63, 158, 0.24)');
          trailGrad.addColorStop(1, 'rgba(244, 63, 158, 0)');
        }
        ctx.fillStyle = trailGrad;
        ctx.fillRect(-130 * u, gradY0, 260 * u, trailH);

        ctx.strokeStyle = C.magenta;
        ctx.lineWidth = 3 * u;
        ctx.beginPath();
        ctx.moveTo(-125 * u, scanY);
        ctx.lineTo(125 * u, scanY);
        ctx.stroke();
        ctx.restore();
      }

      // Central Hex Security Core Emblem
      const coreScale = easeOutCubic(range01(p, 0.20, 0.36));
      ctx.save();
      ctx.scale(coreScale, coreScale);

      ctx.fillStyle = C.surfaceDark;
      hexagonPath(0, 0, 34 * u, -Math.PI * 0.5);
      ctx.fill();

      ctx.strokeStyle = C.magenta;
      ctx.lineWidth = 4 * u;
      ctx.lineJoin = 'round';
      hexagonPath(0, 0, 28 * u, -Math.PI * 0.5);
      ctx.stroke();

      ctx.fillStyle = C.lavenderWhite;
      hexagonPath(0, 0, 13 * u, -Math.PI * 0.5);
      ctx.fill();
      ctx.restore();
    }

    ctx.restore();
  }

  // =========================================================================
  // SCENE 2 (5-10s): PRECISION SMART PADLOCK
  // =========================================================================
  function drawScene2Padlock(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    const antic = Math.sin(range01(p, 0.20, 0.28) * Math.PI) * -5 * u;
    const lockClose = easeInOutCubic(range01(p, 0.26, 0.42));
    const shackleOffsetY = (1 - lockClose) * -26 * u + antic;

    const settleP = range01(p, 0.40, 0.54);
    const bodySettleY = Math.sin(settleP * Math.PI) * 4 * u;
    const floatY = Math.sin(range01(p, 0.16, 0.86) * Math.PI * 2) * 4 * u;

    ctx.save();
    ctx.translate(cx, cy + floatY + bodySettleY + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    const bodyW = 236 * u;
    const bodyH = 176 * u;
    const bodyX = -bodyW * 0.5;
    const bodyY = -22 * u;
    const bodyR = 26 * u;

    // Clean Linear Vertical Flank Confirmation Bars (strictly outside lock body, zero curves/loops)
    const pulseP = range01(p, 0.42, 0.72);
    if (pulseP > 0 && pulseP < 1) {
      const shiftX = (142 + 28 * easeOutCubic(pulseP)) * u;
      const barH = (86 - 18 * pulseP) * u;
      const barCy = bodyY + bodyH * 0.5;
      ctx.save();
      ctx.globalAlpha = env.alpha * (1 - pulseP) * 0.85;
      ctx.fillStyle = C.magenta;
      roundedRectPath(-shiftX - 4 * u, barCy - barH * 0.5, 4 * u, barH, 2 * u);
      ctx.fill();
      roundedRectPath(shiftX, barCy - barH * 0.5, 4 * u, barH, 2 * u);
      ctx.fill();
      ctx.restore();
    }

    // Curved U-Shackle drawn cleanly BEHIND lock body (zero joint overlap)
    const shR = 60 * u;
    const shThick = 22 * u;
    const shArcY = -88 * u + shackleOffsetY;
    const leftLegBot = bodyY + 18 * u;
    const rightLegBot = bodyY - 16 * u + lockClose * 34 * u;

    ctx.strokeStyle = C.lavender;
    ctx.lineWidth = shThick;
    ctx.lineCap = 'butt';
    ctx.beginPath();
    ctx.moveTo(-shR, leftLegBot);
    ctx.lineTo(-shR, shArcY);
    ctx.arc(0, shArcY, shR, Math.PI, 0, false);
    ctx.lineTo(shR, rightLegBot);
    ctx.stroke();

    ctx.strokeStyle = C.lavenderWhite;
    ctx.lineWidth = 4 * u;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.arc(0, shArcY, shR + 5 * u, Math.PI * 1.12, Math.PI * 1.55, false);
    ctx.stroke();

    // Main Padlock Body (flat duotone split)
    ctx.save();
    roundedRectPath(bodyX, bodyY, bodyW, bodyH, bodyR);
    ctx.clip();

    ctx.fillStyle = C.violet;
    ctx.fillRect(bodyX, bodyY, bodyW * 0.5, bodyH);
    ctx.fillStyle = C.violetMid;
    ctx.fillRect(0, bodyY, bodyW * 0.5, bodyH);
    ctx.restore();

    // Recessed Dark Inner Panel
    const panW = 188 * u;
    const panH = 128 * u;
    const panX = -panW * 0.5;
    const panY = bodyY + (bodyH - panH) * 0.5;
    ctx.fillStyle = C.surfaceDark;
    roundedRectPath(panX, panY, panW, panH, 16 * u);
    ctx.fill();

    // Centered Flat Keyhole Emblem with smooth color transition on lock
    const khY = panY + 48 * u;
    const lockColorBlend = easeOutCubic(range01(p, 0.39, 0.49));
    ctx.fillStyle = lerpColor(C.magenta, C.lavenderWhite, lockColorBlend);

    ctx.beginPath();
    ctx.arc(0, khY, 19 * u, 0, Math.PI * 2);
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(-9 * u, khY + 8 * u);
    ctx.lineTo(9 * u, khY + 8 * u);
    ctx.lineTo(13 * u, khY + 46 * u);
    ctx.lineTo(-13 * u, khY + 46 * u);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = C.surfaceDark;
    ctx.beginPath();
    ctx.arc(0, khY, 6 * u, 0, Math.PI * 2);
    ctx.fill();

    // Flanking Vertical Status LED Columns
    const ledBaseY = panY + panH * 0.5;
    for (let side = -1; side <= 1; side += 2) {
      for (let i = 0; i < 3; i++) {
        const ly = ledBaseY + (i - 1) * 22 * u;
        const litStart = 0.42 + i * 0.06;
        const litBlend = easeOutCubic(range01(p, litStart, litStart + 0.08));
        ctx.fillStyle = lerpColor(C.trackMuted, C.magenta, litBlend);
        ctx.beginPath();
        ctx.arc(side * 64 * u, ly, 4.5 * u, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    ctx.restore();
  }

  // =========================================================================
  // SCENE 3 (10-15s): BANK VAULT WHEEL
  // =========================================================================
  function drawScene3Vault(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    ctx.save();
    ctx.translate(cx, cy + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    // Two stepped mechanical precision turns: 0 -> 90 deg, detent hold, 90 -> 180 deg
    const turn1 = easeInOutCubic(range01(p, 0.16, 0.38));
    const turn2 = easeInOutCubic(range01(p, 0.46, 0.68));
    const wheelAngle = (turn1 + turn2) * (Math.PI * 0.5);

    // 8 Retractable Locking Bolts drawn cleanly BEHIND outer vault ring
    for (let i = 0; i < 8; i++) {
      const ang = (i * Math.PI) / 4;
      const pairIdx = i % 4;
      const extendIn = easeOutCubic(range01(p, 0.42 + pairIdx * 0.04, 0.56 + pairIdx * 0.04));
      const extendOut = 1 - easeInCubic(range01(p, 0.78, 0.88));
      const boltExt = Math.min(extendIn, extendOut);

      ctx.save();
      ctx.rotate(ang);
      const bx = (164 + boltExt * 26) * u;
      ctx.fillStyle = lerpColor(C.lavender, C.magenta, boltExt);
      roundedRectPath(bx, -7 * u, 28 * u, 14 * u, 4 * u);
      ctx.fill();
      ctx.restore();
    }

    // Outer Vault Door Ring (r = 186u)
    ctx.fillStyle = C.surfaceLight;
    ctx.beginPath();
    ctx.arc(0, 0, 186 * u, 0, Math.PI * 2);
    ctx.fill();

    ctx.strokeStyle = C.violet;
    ctx.lineWidth = 3.5 * u;
    ctx.beginPath();
    ctx.arc(0, 0, 186 * u, 0, Math.PI * 2);
    ctx.stroke();

    // Inner Recessed Dark Drum (r = 166u)
    ctx.fillStyle = C.surfaceDark;
    ctx.beginPath();
    ctx.arc(0, 0, 166 * u, 0, Math.PI * 2);
    ctx.fill();

    // 12 Crisp Index Pips at r = 148u
    for (let i = 0; i < 12; i++) {
      const a = (i * Math.PI) / 6;
      const isCardinal = i % 3 === 0;
      ctx.fillStyle = isCardinal ? C.lavender : C.trackStroke;
      ctx.beginPath();
      ctx.arc(Math.cos(a) * 148 * u, Math.sin(a) * 148 * u, (isCardinal ? 4.5 : 3) * u, 0, Math.PI * 2);
      ctx.fill();
    }

    // Rotating Central Vault Wheel
    ctx.save();
    ctx.rotate(wheelAngle);

    for (let i = 0; i < 4; i++) {
      ctx.save();
      ctx.rotate(i * (Math.PI * 0.5) + Math.PI * 0.25);
      ctx.fillStyle = C.lavender;
      roundedRectPath(34 * u, -7 * u, 72 * u, 14 * u, 4 * u);
      ctx.fill();
      ctx.restore();
    }

    ctx.strokeStyle = C.violet;
    ctx.lineWidth = 16 * u;
    ctx.beginPath();
    ctx.arc(0, 0, 108 * u, 0, Math.PI * 2);
    ctx.stroke();

    ctx.strokeStyle = C.magenta;
    ctx.lineWidth = 16 * u;
    ctx.lineCap = 'butt';
    for (let i = 0; i < 4; i++) {
      const a0 = i * (Math.PI * 0.5) + Math.PI * 0.17;
      ctx.beginPath();
      ctx.arc(0, 0, 108 * u, a0, a0 + Math.PI * 0.16);
      ctx.stroke();
    }

    ctx.fillStyle = C.lavenderWhite;
    ctx.beginPath();
    ctx.arc(0, 0, 40 * u, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = C.surfaceMid;
    ctx.beginPath();
    ctx.arc(0, 0, 26 * u, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = C.magenta;
    ctx.beginPath();
    ctx.arc(0, 0, 11 * u, 0, Math.PI * 2);
    ctx.fill();

    ctx.restore();
    ctx.restore();
  }

  // =========================================================================
  // SCENE 4 (15-20s): VERIFIED SECURITY SEAL (Checkmark Badge)
  // =========================================================================
  function sealPath(baseR, amp, lobes) {
    const steps = 144;
    ctx.beginPath();
    for (let i = 0; i <= steps; i++) {
      const a = (i / steps) * Math.PI * 2;
      const r = baseR + amp * Math.cos(lobes * a);
      const px = Math.cos(a) * r;
      const py = Math.sin(a) * r;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
  }

  function drawScene4Badge(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    const floatY = Math.sin(range01(p, 0.14, 0.86) * Math.PI * 2) * 5 * u;
    const sealRot = easeInOutCubic(range01(p, 0.08, 0.88)) * (Math.PI / 6);

    ctx.save();
    ctx.translate(cx, cy + floatY + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    // 12-Lobed Crisp Geometric Seal Silhouette
    ctx.save();
    ctx.rotate(sealRot);
    sealPath(168 * u, 13 * u, 12);
    ctx.clip();

    ctx.fillStyle = C.violet;
    ctx.fillRect(-190 * u, -190 * u, 190 * u, 380 * u);
    ctx.fillStyle = C.violetMid;
    ctx.fillRect(0, -190 * u, 190 * u, 380 * u);
    ctx.restore();

    // Recessed Inner Dark Circle
    ctx.fillStyle = C.surfaceDark;
    ctx.beginPath();
    ctx.arc(0, 0, 132 * u, 0, Math.PI * 2);
    ctx.fill();

    // Progressive Crisp Lavender Inner Ring
    const ringP = easeOutCubic(range01(p, 0.14, 0.36));
    if (ringP > 0.01) {
      ctx.strokeStyle = C.lavender;
      ctx.lineWidth = 3.2 * u;
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.arc(0, 0, 116 * u, -Math.PI * 0.5, -Math.PI * 0.5 + Math.PI * 2 * ringP);
      ctx.stroke();
    }

    // Bold Centered Verification Checkmark
    const checkP = easeOutCubic(range01(p, 0.28, 0.54));
    if (checkP > 0.01) {
      const checkPts = [
        [-48 * u, 4 * u],
        [-12 * u, 40 * u],
        [54 * u, -32 * u]
      ];
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';

      ctx.strokeStyle = C.magenta;
      ctx.lineWidth = 24 * u;
      drawPartialPolyline(checkPts, checkP);

      ctx.strokeStyle = C.lavenderWhite;
      ctx.lineWidth = 8 * u;
      drawPartialPolyline(checkPts, checkP);
    }

    // 12 Symmetrical Outer Radial Accent Ticks
    const burstIn = easeOutCubic(range01(p, 0.48, 0.64));
    const burstOut = 1 - easeInCubic(range01(p, 0.72, 0.86));
    const burstAmt = Math.min(burstIn, burstOut);

    if (burstAmt > 0.01) {
      ctx.save();
      ctx.rotate(sealRot);
      ctx.lineCap = 'round';
      ctx.lineWidth = 3.8 * u;
      for (let i = 0; i < 12; i++) {
        const a = (i * Math.PI) / 6;
        const r0 = (198 + (1 - burstAmt) * 8) * u;
        const r1 = r0 + 20 * u * burstAmt;
        ctx.strokeStyle = i % 2 === 0 ? C.magenta : C.lavender;
        ctx.beginPath();
        ctx.moveTo(Math.cos(a) * r0, Math.sin(a) * r0);
        ctx.lineTo(Math.cos(a) * r1, Math.sin(a) * r1);
        ctx.stroke();
      }
      ctx.restore();
    }

    ctx.restore();
  }

  // =========================================================================
  // RENDER PIPELINE
  // =========================================================================
  ctx.save();
  drawBackground();
  drawSideTelemetry();

  if (currentScene === 0) {
    drawScene1Shield(sceneProgress);
  } else if (currentScene === 1) {
    drawScene2Padlock(sceneProgress);
  } else if (currentScene === 2) {
    drawScene3Vault(sceneProgress);
  } else {
    drawScene4Badge(sceneProgress);
  }
  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const u = minSide / 1000;
  const cx = width * 0.5;
  const cy = height * 0.5;
  const loopPhase = (loopT / duration) * Math.PI * 2;
  const heroZoom = 1.22;

  // Color Palette — Deep Midnight Navy + Electric Emerald & Bright Mint
  const C = {
    bgTop: '#060D1C',
    bgMid: '#0A162E',
    bgBot: '#0F2042',
    gridDot: 'rgba(148, 197, 255, 0.065)',
    trackMuted: '#1B3159',
    trackStroke: '#264478',
    surfaceDark: '#0D1C38',
    surfaceMid: '#13264A',
    surfaceLight: '#1A3463',
    emerald: '#00E599',
    emeraldMid: '#00C484',
    emeraldDeep: '#009666',
    emeraldDark: '#00734E',
    mint: '#8FFFD6',
    mintSoft: '#5AE8B7',
    ice: '#E8FFF7',
    sheen: 'rgba(232, 255, 247, 0.22)'
  };

  // Smooth, Controlled Math & Color Utilities
  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function range01(p, start, end) {
    return clamp01((p - start) / (end - start));
  }

  function easeOutCubic(x) {
    const inv = 1 - clamp01(x);
    return 1 - inv * inv * inv;
  }

  function easeInCubic(x) {
    const v = clamp01(x);
    return v * v * v;
  }

  function easeInOutCubic(x) {
    const v = clamp01(x);
    return v < 0.5 ? 4 * v * v * v : 1 - Math.pow(-2 * v + 2, 3) / 2;
  }

  function easeOutQuint(x) {
    const inv = 1 - clamp01(x);
    return 1 - inv * inv * inv * inv * inv;
  }

  function easeOutSoftBack(x) {
    const v = clamp01(x);
    const c1 = 0.78;
    const c3 = c1 + 1;
    return 1 + c3 * Math.pow(v - 1, 3) + c1 * Math.pow(v - 1, 2);
  }

  function lerpColor(hexA, hexB, f) {
    const k = clamp01(f);
    const a = parseInt(hexA.slice(1), 16);
    const b = parseInt(hexB.slice(1), 16);
    const ar = (a >> 16) & 255;
    const ag = (a >> 8) & 255;
    const ab = a & 255;
    const br = (b >> 16) & 255;
    const bg = (b >> 8) & 255;
    const bb = b & 255;
    const r = Math.round(ar + (br - ar) * k);
    const g = Math.round(ag + (bg - ag) * k);
    const bl = Math.round(ab + (bb - ab) * k);
    return 'rgb(' + r + ',' + g + ',' + bl + ')';
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function drawPartialPolyline(points, progress) {
    if (progress <= 0 || points.length < 2) return;
    let totalLen = 0;
    const segLens = [];
    for (let i = 0; i < points.length - 1; i++) {
      const dx = points[i + 1][0] - points[i][0];
      const dy = points[i + 1][1] - points[i][1];
      const len = Math.hypot(dx, dy);
      segLens.push(len);
      totalLen += len;
    }
    let remaining = totalLen * clamp01(progress);
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 0; i < segLens.length; i++) {
      if (remaining <= 0) break;
      if (remaining >= segLens[i]) {
        ctx.lineTo(points[i + 1][0], points[i + 1][1]);
        remaining -= segLens[i];
      } else {
        const frac = remaining / segLens[i];
        ctx.lineTo(
          points[i][0] + (points[i + 1][0] - points[i][0]) * frac,
          points[i][1] + (points[i + 1][1] - points[i][1]) * frac
        );
        remaining = 0;
      }
    }
    ctx.stroke();
  }

  function drawBackground() {
    // Pure Modern Dark Aesthetic Linear Gradient — ZERO background glow
    const bgGrad = ctx.createLinearGradient(0, 0, width, height);
    bgGrad.addColorStop(0, C.bgTop);
    bgGrad.addColorStop(0.52, C.bgMid);
    bgGrad.addColorStop(1, C.bgBot);
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, width, height);

    // Subtle uniform architectural dot matrix with seamless 1-cell periodic drift (no circular hole)
    const step = 58 * u;
    const driftX = (loopT / duration) * step;
    const driftY = (loopT / duration) * step;
    const cols = Math.ceil(width / step) + 2;
    const rows = Math.ceil(height / step) + 2;
    const startX = cx - Math.floor(cols * 0.5) * step + (driftX % step) - step;
    const startY = cy - Math.floor(rows * 0.5) * step + (driftY % step) - step;
    const dotR = 1.45 * u;

    ctx.fillStyle = C.gridDot;
    ctx.beginPath();
    for (let r = 0; r < rows; r++) {
      const py = startY + r * step;
      if (py < 24 * u || py > height - 24 * u) continue;
      for (let c = 0; c < cols; c++) {
        const px = startX + c * step;
        if (px < 24 * u || px > width - 24 * u) continue;
        ctx.moveTo(px + dotR, py);
        ctx.arc(px, py, dotR, 0, Math.PI * 2);
      }
    }
    ctx.fill();
  }

  function drawSideTelemetry() {
    const minHalfW = 580 * u;
    if (width * 0.5 < minHalfW + 80 * u) return;

    const sideOffset = Math.min(620 * u, width * 0.5 - 110 * u);
    const lx = cx - sideOffset;
    const rx = cx + sideOffset;

    const capW = 6 * u;
    const capH = 40 * u;
    const capGap = 20 * u;
    const totalH = sceneCount * capH + (sceneCount - 1) * capGap;
    const topY = cy - totalH * 0.5;

    const activeFade = Math.min(
      easeOutCubic(range01(sceneProgress, 0.0, 0.08)),
      1 - easeInCubic(range01(sceneProgress, 0.90, 1.0))
    );

    // Left column: 4 Scene Phase Capsules
    for (let i = 0; i < sceneCount; i++) {
      const y = topY + i * (capH + capGap);
      ctx.fillStyle = C.trackMuted;
      roundedRectPath(lx - capW * 0.5, y, capW, capH, capW * 0.5);
      ctx.fill();

      if (i === currentScene && activeFade > 0.01) {
        const fillFrac = easeInOutCubic(range01(sceneProgress, 0.0, 0.90));
        const fillH = Math.max(capW, capH * fillFrac);
        ctx.fillStyle = lerpColor(C.trackMuted, C.emerald, activeFade);
        roundedRectPath(lx - capW * 0.5, y, capW, fillH, capW * 0.5);
        ctx.fill();
      }
    }

    // Right column: 4 Symmetrical Horizontal Harmonic Metric Bars
    const barMaxW = 60 * u;
    const barH = 6 * u;
    for (let i = 0; i < 4; i++) {
      const y = topY + i * (capH + capGap) + (capH - barH) * 0.5;
      const wave = 0.5 + 0.5 * Math.sin(loopPhase * 2 - i * 0.9);
      const activeW = (20 + wave * 36) * u;

      ctx.fillStyle = C.trackMuted;
      roundedRectPath(rx - barMaxW * 0.5, y, barMaxW, barH, barH * 0.5);
      ctx.fill();

      const highlight = i === currentScene ? activeFade : 0;
      ctx.fillStyle = lerpColor(C.trackStroke, C.emerald, highlight);
      roundedRectPath(rx - barMaxW * 0.5, y, activeW, barH, barH * 0.5);
      ctx.fill();
    }
  }

  function getSceneEnvelope(p) {
    const enterP = range01(p, 0.0, 0.14);
    const exitP = range01(p, 0.86, 1.0);
    const enterEase = easeOutCubic(enterP);
    const exitEase = easeInCubic(exitP);
    const scale = p < 0.5 ? 0.86 + 0.14 * enterEase : 1 - 0.14 * exitEase;
    const liftY = p < 0.5 ? (1 - enterEase) * 18 * u : -exitEase * 18 * u;
    const alpha = p < 0.10
      ? easeOutCubic(range01(p, 0.0, 0.10))
      : p > 0.90
        ? 1 - easeInCubic(range01(p, 0.90, 1.0))
        : 1;
    return { scale, alpha, liftY };
  }

  // =========================================================================
  // SCENE 1 (0-5s): LAYERED TOKEN COIN (Portfolio Asset Coin)
  // =========================================================================
  function drawScene1Coin(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    const floatY = Math.sin(range01(p, 0.14, 0.86) * Math.PI * 2) * 6 * u;

    ctx.save();
    ctx.translate(cx, cy + floatY + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    // Outer emerald coin rim (r = 178u) with clean flat bevel split
    ctx.fillStyle = C.emerald;
    ctx.beginPath();
    ctx.arc(0, 0, 178 * u, 0, Math.PI * 2);
    ctx.fill();

    ctx.save();
    ctx.beginPath();
    ctx.arc(0, 0, 178 * u, 0, Math.PI * 2);
    ctx.clip();
    ctx.fillStyle = C.emeraldMid;
    ctx.beginPath();
    ctx.moveTo(178 * u, -178 * u);
    ctx.lineTo(178 * u, 178 * u);
    ctx.lineTo(-178 * u, 178 * u);
    ctx.closePath();
    ctx.fill();
    ctx.restore();

    // Crisp dark separator channel (r = 160u)
    ctx.fillStyle = C.bgTop;
    ctx.beginPath();
    ctx.arc(0, 0, 160 * u, 0, Math.PI * 2);
    ctx.fill();

    // Inner coin face with clean flat duotone split (r = 152u)
    ctx.save();
    ctx.beginPath();
    ctx.arc(0, 0, 152 * u, 0, Math.PI * 2);
    ctx.clip();

    ctx.fillStyle = C.surfaceMid;
    ctx.fillRect(-155 * u, -155 * u, 310 * u, 310 * u);

    ctx.fillStyle = C.surfaceDark;
    ctx.beginPath();
    ctx.moveTo(155 * u, -155 * u);
    ctx.lineTo(155 * u, 155 * u);
    ctx.lineTo(-155 * u, 155 * u);
    ctx.closePath();
    ctx.fill();

    // Diagonal light sheen sweep (0.44 -> 0.72)
    const sheenP = easeInOutCubic(range01(p, 0.44, 0.72));
    if (sheenP > 0 && sheenP < 1) {
      const sx = (-260 + sheenP * 520) * u;
      ctx.save();
      ctx.translate(sx, 0);
      ctx.rotate(Math.PI * 0.22);
      ctx.fillStyle = C.sheen;
      ctx.fillRect(-26 * u, -220 * u, 52 * u, 440 * u);
      ctx.restore();
    }
    ctx.restore();

    // Inner milled coin ridge ring (static refined coin engraving detail)
    ctx.strokeStyle = C.trackStroke;
    ctx.lineWidth = 2.6 * u;
    ctx.lineCap = 'round';
    ctx.setLineDash([8 * u, 12 * u]);
    ctx.beginPath();
    ctx.arc(0, 0, 134 * u, 0, Math.PI * 2);
    ctx.stroke();
    ctx.setLineDash([]);

    // 3 evenly spaced mini growth bars (x = -48u, 0u, +48u; width = 24u; gap = 24u)
    const baseY = 66 * u;
    const barW = 24 * u;
    const barSpecs = [
      { x: -48, h: 46, delay: 0.14, color: C.emeraldDeep },
      { x: 0, h: 72, delay: 0.21, color: C.emeraldMid },
      { x: 48, h: 98, delay: 0.28, color: C.emerald }
    ];

    ctx.strokeStyle = C.trackStroke;
    ctx.lineWidth = 3 * u;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(-76 * u, baseY + 8 * u);
    ctx.lineTo(76 * u, baseY + 8 * u);
    ctx.stroke();

    const barTops = [];
    const breathPhase = range01(p, 0.46, 0.84) * Math.PI * 2;
    for (let i = 0; i < barSpecs.length; i++) {
      const spec = barSpecs[i];
      const grow = easeOutCubic(range01(p, spec.delay, spec.delay + 0.18));
      const breathEnv = Math.sin(range01(p, 0.46, 0.84) * Math.PI);
      const breath = Math.sin(breathPhase + i * 0.8) * 3 * u * breathEnv;
      const curH = Math.max(0, spec.h * u * grow + breath);
      const bx = spec.x * u - barW * 0.5;
      const by = baseY - curH;
      barTops.push([spec.x * u, by]);

      if (curH > 1 * u) {
        ctx.fillStyle = spec.color;
        roundedRectPath(bx, by, barW, curH, 6 * u);
        ctx.fill();
      }
    }

    // Upward trend polyline cleanly 24u ABOVE bar tops (zero overlap)
    const arrowP = easeOutCubic(range01(p, 0.30, 0.52));
    const trendPts = [
      [barTops[0][0], barTops[0][1] - 24 * u],
      [barTops[1][0], barTops[1][1] - 24 * u],
      [barTops[2][0], barTops[2][1] - 24 * u]
    ];

    ctx.strokeStyle = C.ice;
    ctx.lineWidth = 5.5 * u;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    drawPartialPolyline(trendPts, arrowP);

    const headP = easeOutCubic(range01(p, 0.46, 0.56));
    if (headP > 0.01) {
      const tipX = trendPts[2][0];
      const tipY = trendPts[2][1];
      const ang = Math.atan2(trendPts[2][1] - trendPts[1][1], trendPts[2][0] - trendPts[1][0]);
      const hs = 14 * u * headP;
      ctx.save();
      ctx.translate(tipX, tipY);
      ctx.rotate(ang);
      ctx.strokeStyle = C.ice;
      ctx.lineWidth = 5.5 * u;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.beginPath();
      ctx.moveTo(-hs, -hs * 0.65);
      ctx.lineTo(0, 0);
      ctx.lineTo(-hs, hs * 0.65);
      ctx.stroke();
      ctx.restore();
    }

    ctx.restore();
  }

  // =========================================================================
  // SCENE 2 (5-10s): DYNAMIC BAR & TREND CHART (Analytics Card)
  // =========================================================================
  function drawScene2Chart(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    const floatY = Math.sin(range01(p, 0.14, 0.86) * Math.PI * 2) * 5 * u;

    ctx.save();
    ctx.translate(cx, cy + floatY + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    const cardW = 344 * u;
    const cardH = 268 * u;
    const left = -cardW * 0.5;
    const top = -cardH * 0.5;
    const cardR = 22 * u;

    ctx.fillStyle = C.surfaceMid;
    roundedRectPath(left, top, cardW, cardH, cardR);
    ctx.fill();

    // Header band cleanly clipped inside card
    const headerH = 44 * u;
    ctx.save();
    roundedRectPath(left, top, cardW, cardH, cardR);
    ctx.clip();
    ctx.fillStyle = C.surfaceDark;
    ctx.fillRect(left, top, cardW, headerH);

    ctx.strokeStyle = C.trackStroke;
    ctx.lineWidth = 2 * u;
    ctx.beginPath();
    ctx.moveTo(left, top + headerH);
    ctx.lineTo(left + cardW, top + headerH);
    ctx.stroke();
    ctx.restore();

    ctx.strokeStyle = C.trackStroke;
    ctx.lineWidth = 3 * u;
    roundedRectPath(left, top, cardW, cardH, cardR);
    ctx.stroke();

    // Header details: 3 status dots on left + clean progress pill on right
    const hy = top + headerH * 0.5;
    const dotColors = [C.emerald, C.mintSoft, C.trackStroke];
    for (let i = 0; i < 3; i++) {
      ctx.fillStyle = dotColors[i];
      ctx.beginPath();
      ctx.arc(left + (28 + i * 18) * u, hy, 5 * u, 0, Math.PI * 2);
      ctx.fill();
    }

    const pillW = 76 * u;
    const pillH = 10 * u;
    const pillX = left + cardW - pillW - 24 * u;
    const pillY = hy - pillH * 0.5;
    ctx.fillStyle = C.trackMuted;
    roundedRectPath(pillX, pillY, pillW, pillH, pillH * 0.5);
    ctx.fill();

    const pillFill = easeOutCubic(range01(p, 0.14, 0.64));
    if (pillFill > 0.01) {
      ctx.fillStyle = C.emerald;
      roundedRectPath(pillX, pillY, Math.max(pillH, pillW * pillFill), pillH, pillH * 0.5);
      ctx.fill();
    }

    // Horizontal gridlines & solid baseline
    const plotLeft = left + 28 * u;
    const plotRight = left + cardW - 28 * u;
    const baseY = 102 * u;

    ctx.strokeStyle = '#1E3A6B';
    ctx.lineWidth = 1.5 * u;
    for (let g = 1; g <= 3; g++) {
      const gy = baseY - g * 46 * u;
      ctx.beginPath();
      ctx.moveTo(plotLeft, gy);
      ctx.lineTo(plotRight, gy);
      ctx.stroke();
    }

    ctx.strokeStyle = '#365FA3';
    ctx.lineWidth = 2.5 * u;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(plotLeft, baseY);
    ctx.lineTo(plotRight, baseY);
    ctx.stroke();

    // 4 evenly spaced flat duotone bars (width = 40u, gap = 28u)
    const barW = 40 * u;
    const barData = [
      { x: -102, h: 48, delay: 0.12, cL: C.emeraldMid, cR: C.emeraldDeep },
      { x: -34, h: 74, delay: 0.17, cL: C.emerald, cR: C.emeraldMid },
      { x: 34, h: 100, delay: 0.22, cL: C.emerald, cR: C.emeraldMid },
      { x: 102, h: 126, delay: 0.27, cL: C.mint, cR: C.emerald }
    ];

    const liveP = range01(p, 0.48, 0.84);
    const livePhase = liveP * Math.PI * 2;
    const liveEnv = Math.sin(liveP * Math.PI);
    const trendNodes = [];

    for (let i = 0; i < barData.length; i++) {
      const b = barData[i];
      const grow = easeOutCubic(range01(p, b.delay, b.delay + 0.18));
      const ripple = Math.sin(livePhase - i * 0.75) * 3.5 * u * liveEnv;
      const bh = Math.max(0, b.h * u * grow + ripple);
      const bx = b.x * u - barW * 0.5;
      const by = baseY - bh;

      trendNodes.push([b.x * u, by - 26 * u]);

      if (bh > 2 * u) {
        ctx.save();
        roundedRectPath(bx, by, barW, bh, 7 * u);
        ctx.clip();
        ctx.fillStyle = b.cL;
        ctx.fillRect(bx, by, barW * 0.5, bh);
        ctx.fillStyle = b.cR;
        ctx.fillRect(bx + barW * 0.5, by, barW * 0.5, bh);
        ctx.restore();
      }
    }

    // Crisp trend line connecting elevated nodes
    const lineP = easeInOutCubic(range01(p, 0.30, 0.56));
    ctx.strokeStyle = C.ice;
    ctx.lineWidth = 4 * u;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    drawPartialPolyline(trendNodes, lineP);

    for (let i = 0; i < trendNodes.length; i++) {
      const threshold = i / (trendNodes.length - 1);
      const nodeAppear = easeOutCubic(range01(lineP, Math.max(0, threshold - 0.06), Math.min(1, threshold + 0.08)));
      if (nodeAppear <= 0.01) continue;
      const nx = trendNodes[i][0];
      const ny = trendNodes[i][1];
      const rOut = 7.5 * u * nodeAppear;
      const rIn = 3.5 * u * nodeAppear;

      ctx.fillStyle = C.surfaceMid;
      ctx.beginPath();
      ctx.arc(nx, ny, rOut + 2 * u, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = C.ice;
      ctx.beginPath();
      ctx.arc(nx, ny, rOut, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = C.emerald;
      ctx.beginPath();
      ctx.arc(nx, ny, rIn, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.restore();
  }

  // =========================================================================
  // SCENE 3 (10-15s): FINANCIAL ROCKET ARROW (Standalone Open-Space Flight, ZERO Circular Disc)
  // =========================================================================
  function drawScene3Rocket(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    ctx.save();
    ctx.translate(cx, cy + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    // Rotate -45 deg for upward-right financial growth trajectory
    ctx.rotate(-Math.PI * 0.25);

    // Parallel aerodynamic speed streaks strictly on outer flanks (|y| >= 104u, smooth fade at ends!)
    const streakSpeed = p * 2.6;
    const streaks = [
      { y: -144, len: 56, off: 0.12, col: '#2D528C' },
      { y: -106, len: 82, off: 0.56, col: C.emeraldMid },
      { y: 106, len: 78, off: 0.30, col: C.emeraldMid },
      { y: 144, len: 52, off: 0.78, col: '#2D528C' }
    ];
    ctx.lineCap = 'round';
    ctx.lineWidth = 3.4 * u;
    for (let i = 0; i < streaks.length; i++) {
      const s = streaks[i];
      const frac = (streakSpeed + s.off) % 1;
      const streakFade = Math.sin(frac * Math.PI);
      const sx = (170 - frac * 390) * u;
      ctx.save();
      ctx.globalAlpha = env.alpha * streakFade * 0.9;
      ctx.strokeStyle = s.col;
      ctx.beginPath();
      ctx.moveTo(sx, s.y * u);
      ctx.lineTo(sx + s.len * u, s.y * u);
      ctx.stroke();
      ctx.restore();
    }

    // Smooth controlled rocket cruise entry + balanced axial glide (bold standalone hero scale)
    const entrySlide = (1 - easeOutQuint(range01(p, 0.04, 0.28))) * -52 * u;
    const cruiseGlide = Math.sin(range01(p, 0.20, 0.85) * Math.PI * 2) * 8 * u;
    ctx.translate(16 * u + entrySlide + cruiseGlide, 0);
    ctx.scale(1.24, 1.24);

    // Symmetric swept side fins (flush with fuselage edges)
    ctx.fillStyle = C.emerald;
    ctx.beginPath();
    ctx.moveTo(-24 * u, -30 * u);
    ctx.lineTo(-64 * u, -62 * u);
    ctx.lineTo(-74 * u, -52 * u);
    ctx.lineTo(-66 * u, -24 * u);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = C.emeraldDeep;
    ctx.beginPath();
    ctx.moveTo(-24 * u, 30 * u);
    ctx.lineTo(-64 * u, 62 * u);
    ctx.lineTo(-74 * u, 52 * u);
    ctx.lineTo(-66 * u, 24 * u);
    ctx.closePath();
    ctx.fill();

    // Thruster nozzle base
    ctx.fillStyle = C.trackStroke;
    roundedRectPath(-78 * u, -19 * u, 16 * u, 38 * u, 4 * u);
    ctx.fill();

    // Clean separated thrust plume (8u clear separation behind nozzle)
    const flamePulse = 0.86 + 0.14 * Math.sin(p * Math.PI * 8);
    const fLen = 58 * u * flamePulse;

    ctx.fillStyle = C.emerald;
    ctx.beginPath();
    ctx.moveTo(-86 * u, -14 * u);
    ctx.quadraticCurveTo(-86 * u - fLen * 0.55, -12 * u, -86 * u - fLen, 0);
    ctx.quadraticCurveTo(-86 * u - fLen * 0.55, 12 * u, -86 * u, 14 * u);
    ctx.closePath();
    ctx.fill();

    const fIn = fLen * 0.62;
    ctx.fillStyle = C.ice;
    ctx.beginPath();
    ctx.moveTo(-86 * u, -7.5 * u);
    ctx.quadraticCurveTo(-86 * u - fIn * 0.5, -6 * u, -86 * u - fIn, 0);
    ctx.quadraticCurveTo(-86 * u - fIn * 0.5, 6 * u, -86 * u, 7.5 * u);
    ctx.closePath();
    ctx.fill();

    // Main sleek rocket fuselage silhouette (clipped for clean flat duotone)
    ctx.save();
    ctx.beginPath();
    ctx.moveTo(-66 * u, -24 * u);
    ctx.quadraticCurveTo(-22 * u, -34 * u, 28 * u, -30 * u);
    ctx.quadraticCurveTo(72 * u, -24 * u, 104 * u, 0);
    ctx.quadraticCurveTo(72 * u, 24 * u, 28 * u, 30 * u);
    ctx.quadraticCurveTo(-22 * u, 34 * u, -66 * u, 24 * u);
    ctx.closePath();
    ctx.clip();

    ctx.fillStyle = C.ice;
    ctx.fillRect(-70 * u, -40 * u, 180 * u, 40 * u);

    ctx.fillStyle = C.mint;
    ctx.fillRect(-70 * u, 0, 180 * u, 40 * u);

    ctx.fillStyle = C.emerald;
    ctx.fillRect(56 * u, -40 * u, 56 * u, 40 * u);
    ctx.fillStyle = C.emeraldMid;
    ctx.fillRect(56 * u, 0, 56 * u, 40 * u);

    ctx.fillStyle = C.surfaceLight;
    ctx.fillRect(-66 * u, -40 * u, 14 * u, 80 * u);
    ctx.restore();

    // Circular porthole window
    ctx.fillStyle = C.surfaceDark;
    ctx.beginPath();
    ctx.arc(18 * u, 0, 17 * u, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = C.emerald;
    ctx.beginPath();
    ctx.arc(18 * u, 0, 11 * u, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = C.ice;
    ctx.beginPath();
    ctx.arc(21.5 * u, -3.5 * u, 3.2 * u, 0, Math.PI * 2);
    ctx.fill();

    ctx.restore();
  }

  // =========================================================================
  // SCENE 4 (15-20s): ASSET DIAMOND MILESTONE (Wealth Crystal)
  // =========================================================================
  function drawScene4Diamond(p) {
    const env = getSceneEnvelope(p);
    if (env.alpha <= 0.001 || env.scale <= 0.001) return;

    const floatY = Math.sin(range01(p, 0.14, 0.86) * Math.PI * 2) * 6 * u;

    ctx.save();
    ctx.translate(cx, cy + floatY + env.liftY);
    ctx.scale(env.scale * heroZoom, env.scale * heroZoom);
    ctx.globalAlpha = env.alpha;

    const yTop = -112 * u;
    const yMid = -38 * u;
    const yBot = 124 * u;

    const tL = [-98 * u, yTop];
    const tC1 = [-46 * u, yTop];
    const tC2 = [46 * u, yTop];
    const tR = [98 * u, yTop];

    const mFL = [-156 * u, yMid];
    const mIL = [-64 * u, yMid];
    const mIR = [64 * u, yMid];
    const mFR = [156 * u, yMid];

    const bot = [0, yBot];

    function fillPoly(pts, color) {
      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.moveTo(pts[0][0], pts[0][1]);
      for (let i = 1; i < pts.length; i++) {
        ctx.lineTo(pts[i][0], pts[i][1]);
      }
      ctx.closePath();
      ctx.fill();
    }

    fillPoly([tL, tC1, mIL, mFL], C.mint);
    fillPoly([tC1, tC2, mIR, mIL], C.ice);
    fillPoly([tC2, tR, mFR, mIR], C.emerald);
    fillPoly([mFL, mIL, bot], C.emeraldMid);
    fillPoly([mIL, mIR, bot], C.emerald);
    fillPoly([mIR, mFR, bot], C.emeraldDeep);

    ctx.strokeStyle = C.bgTop;
    ctx.lineWidth = 2.4 * u;
    ctx.lineJoin = 'round';
    ctx.beginPath();
    ctx.moveTo(mFL[0], mFL[1]);
    ctx.lineTo(mFR[0], mFR[1]);
    ctx.moveTo(tC1[0], tC1[1]);
    ctx.lineTo(mIL[0], mIL[1]);
    ctx.moveTo(tC2[0], tC2[1]);
    ctx.lineTo(mIR[0], mIR[1]);
    ctx.moveTo(mIL[0], mIL[1]);
    ctx.lineTo(bot[0], bot[1]);
    ctx.moveTo(mIR[0], mIR[1]);
    ctx.lineTo(bot[0], bot[1]);
    ctx.stroke();

    // Clipped diagonal sheen sweep inside diamond silhouette
    const sheenP = easeInOutCubic(range01(p, 0.34, 0.66));
    if (sheenP > 0 && sheenP < 1) {
      ctx.save();
      ctx.beginPath();
      ctx.moveTo(tL[0], tL[1]);
      ctx.lineTo(tR[0], tR[1]);
      ctx.lineTo(mFR[0], mFR[1]);
      ctx.lineTo(bot[0], bot[1]);
      ctx.lineTo(mFL[0], mFL[1]);
      ctx.closePath();
      ctx.clip();

      const sx = (-240 + sheenP * 480) * u;
      ctx.translate(sx, 0);
      ctx.rotate(Math.PI * 0.2);
      ctx.fillStyle = 'rgba(255, 255, 255, 0.28)';
      ctx.fillRect(-24 * u, -200 * u, 48 * u, 400 * u);
      ctx.restore();
    }

    ctx.strokeStyle = C.ice;
    ctx.lineWidth = 3 * u;
    ctx.lineJoin = 'round';
    ctx.beginPath();
    ctx.moveTo(tL[0], tL[1]);
    ctx.lineTo(tR[0], tR[1]);
    ctx.lineTo(mFR[0], mFR[1]);
    ctx.lineTo(bot[0], bot[1]);
    ctx.lineTo(mFL[0], mFL[1]);
    ctx.closePath();
    ctx.stroke();

    // 6 symmetrical outer radial accent rays cleanly separated outside diamond
    const rayIn = easeOutCubic(range01(p, 0.26, 0.44));
    const rayOut = 1 - easeInCubic(range01(p, 0.68, 0.84));
    const rayAmt = Math.min(rayIn, rayOut);
    if (rayAmt > 0.01) {
      const deg = Math.PI / 180;
      const rayAngles = [-90 * deg, -32 * deg, 32 * deg, 90 * deg, 148 * deg, -148 * deg];
      ctx.strokeStyle = C.mint;
      ctx.lineWidth = 3.5 * u;
      ctx.lineCap = 'round';
      for (let i = 0; i < rayAngles.length; i++) {
        const a = rayAngles[i];
        const r0 = (196 + (1 - rayAmt) * 8) * u;
        const r1 = r0 + 20 * u * rayAmt;
        ctx.beginPath();
        ctx.moveTo(Math.cos(a) * r0, Math.sin(a) * r0);
        ctx.lineTo(Math.cos(a) * r1, Math.sin(a) * r1);
        ctx.stroke();
      }
    }

    ctx.restore();
  }

  // =========================================================================
  // RENDER PIPELINE
  // =========================================================================
  ctx.save();
  drawBackground();
  drawSideTelemetry();

  if (currentScene === 0) {
    drawScene1Coin(sceneProgress);
  } else if (currentScene === 1) {
    drawScene2Chart(sceneProgress);
  } else if (currentScene === 2) {
    drawScene3Rocket(sceneProgress);
  } else {
    drawScene4Diamond(sceneProgress);
  }
  ctx.restore();
}
